window.JASTROW_CHUNKS[30]={"12000":{"h":"*כַּדְכּוֹר","r":"K00138","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Num. XXIV, 8</span>, read: <a href=\"#\" data-headword=\"כַּרְכּוֹם\">כַּרְכּוֹי</a>, v. <a href=\"#\" data-headword=\"כְּרַךְ II\">כְּרַכָּא</a></div>","alt":[]},"12001":{"h":"כדכיאות","r":"K00139","html":"<div class=\"sense\">, <span class=\"citation\">Sifré Deut. 204</span> <span dir=\"rtl\">תקון וכ׳</span>, <span class=\"citation\">Yalk. Deut. 923</span> <span dir=\"rtl\">תיקון ודוגיאות</span>, a corrupt., read: <span dir=\"rtl\">תִּיקּוּנֵי כַרְכּוֹמִין</span> <i>preparations for sieges;</i> cmp. <span class=\"citation\">Targ. Deut. XX, 20</span> a. Pesik. Zutr. a. l. (Deut. p. 67).</div>","alt":[]},"12002":{"h":"כדכריינון","r":"K00140","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּדְכְּדוֹן\">כִּדְכְּדוֹן</a></div>","alt":[]},"12003":{"h":"כדמת","r":"K00141","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּרֶמֶת\">כָּרֶמֶת</a></div>","alt":[]},"12004":{"h":"כָּדַן","r":"K00142","html":"<div class=\"sense\">, (cmp. Assyr. <i>kidînu</i> servant, Friedr. Del. Proleg. p. 200 note 7) [<i>to bend</i>,] <i>to yoke, put to work</i>. <span class=\"citation\">Y. Peah I, 15ᶜ</span> bot.; <span class=\"citation\">Y. Kidd. I, 61ᵇ</span> <span dir=\"rtl\">(<span dir=\"rtl\">בריחיים</span>) <span dir=\"rtl\">כּוֹדְנוֹ לריחיים</span></span> he puts his father to treading the mill (Bab. <span class=\"citation\">ib. 31ᵃ</span> bot. <span dir=\"rtl\">מטחינו</span>, v. <a href=\"#\" data-headword=\"טָחַן\">טָחַן</a>). <span class=\"citation\">Y. Pes. IV, 31ᵃ</span> top <span dir=\"rtl\">לכשיזקין הוא כודנו בריחיים</span></div><div class=\"sense\"><b>Pi. כִּידֵּן</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"כדמת\">same</a>.—Part. pass. <span dir=\"rtl\">מְכוּדָּן</span>. <span class=\"citation\">Lam. R. to I, 14</span> (ref. to <span dir=\"rtl\">נפש חיה</span>, <span class=\"citation\">Gen. II, 7</span>, as if meaning <i>self-supporting</i>) <span dir=\"rtl\">עשאו עבד מ׳ בפני עצמו וכ׳</span> the Lord made man a slave put to work for himself, for if he does not work, he has nothing to eat; <span class=\"citation\">Gen. R. s. 14</span> <a href=\"#\" data-headword=\"מכורן\">מכורן</a>, <span dir=\"rtl\">מחורר</span>; <span class=\"citation\">Koh. R. to II, 17</span> <span dir=\"rtl\">מכורן עבד</span> (corr. acc.).—<i>Pl. fem</i>. <span dir=\"rtl\">מְכוּדָּנוֹת</span>. <span class=\"citation\">Lev. R. s. 16</span> (play on <span dir=\"rtl\">יְשִׂפַּח</span>, <span class=\"citation\">Is. III, 17</span>) <span dir=\"rtl\">עשאן שְׁפָחוֹת מכ׳</span> the enemies made them handmaids, forced to hard labor; ib. <span dir=\"rtl\">מהו מ׳ אמהן משעבדן</span>; <span class=\"citation\">Lam. R. to IV, 15</span> <span dir=\"rtl\">מכודניות</span> (corr. acc.).—V. <a href=\"#\" data-headword=\"כּוּדְנָא\">כּוּדְנָא</a>.</div></div>","alt":[]},"12005":{"h":"*כַּדְנָא","r":"K00143","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>jug</i>. Targ. II Esth. I, 2 (prob. <a href=\"#\" data-headword=\"כַּוָּוא\">כַּדְּתָא</a> fem. form of <a href=\"#\" data-headword=\"כַּדָּא\">כַּדָּא</a>).</div>","alt":[]},"12006":{"h":"כְּדֵנָא","r":"K00144","html":"<div class=\"sense\"><i>thus</i>, v. <a href=\"#\" data-headword=\"דֵּן\">דֵּן</a>.</div>","alt":["כִּדְנָא"]},"12007":{"h":"כִּדְנְוָן","r":"K00145","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"כּוּדְנָא\">כּוּדנָא</a>.</div>","alt":[]},"12008":{"h":"כָּדַר","r":"K00146","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כַּד II\"><span dir=\"rtl\">כַּד</span> II</a>) <i>to be arched, rounded</i>. <span class=\"citation\">Ab. Zar. 40ᵃ</span>; <span class=\"citation\">Ḥull. 64ᵃ</span> (sign of eggs of clean birds) <span dir=\"rtl\">כל שכּוֹדֶרֶת ועגולגולת</span> (Var. <a href=\"#\" data-headword=\"קוֹדֵם\">קוֹדֶרֶת</a>, <span dir=\"rtl\">קוֹדֶדֶת</span>, <span dir=\"rtl\">כּוֹדֶדֶת</span>) that which is arched (on top not pointed) and rounded (rolling); <span class=\"citation\">Tosef. ib. III</span> (<span class=\"citation\">IV), 23</span>.</div><div class=\"sense\"><b>Hithpa. הִתְכַּדֵּר</b> <div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כַּדּוּר\">כַּדּוּר</a>) <i>to be thrown around in a circle of players</i>. <span class=\"citation\">Koh. R. to XII, 11</span> <span dir=\"rtl\">מה הכדור הזה מִתְכַּדֵּר וכ׳</span> as the ball is thrown around from hand to hand.</div></div>","alt":[]},"12009":{"h":"כַּדָּר","r":"K00147","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּדָּד\">כַּדָּד</a></div>","alt":[]},"12010":{"h":"כֹּה","r":"K00148","html":"<div class=\"sense\"> (b. h.) <i>here; thus</i>. <span class=\"citation\">Gen. R. s. 56</span> (ref. to <span dir=\"rtl\">עד־כה</span>, <span class=\"citation\">Gen. XXII, 5</span>) <span dir=\"rtl\">נלך … בסופו של כה</span> we shall go and see what will be the outcome of <i>koh</i> (the promise, ‘<i>thus</i> shall be thy seed’, <span class=\"citation\">Gen. XV, 5</span>); Tanḥ. Vayera 23.</div>","alt":[]},"12011":{"h":"כָּה","r":"K00149","html":"<div class=\"sense\"> ch., v. <a href=\"#\" data-headword=\"כָּא\">כָּא</a></div>","alt":[]},"12012":{"h":"כְּהָא","r":"K00150","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כהי\">כהי</a></div>","alt":["כָּהָה","כְּהָה"]},"12013":{"h":"כֵּהֶה","r":"K00151","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"כְּהָא\">preced.</a>) </div><div class=\"sense\"><b>1)</b>  (of light) <i>dim</i>. <span class=\"citation\">Gen. R. s. 31</span> <span dir=\"rtl\">בשעה שהיא כ׳</span> when it (the jewel) shone faintly.—Pl. <span dir=\"rtl\">כֵּהִים</span>, <a href=\"#\" data-headword=\"כֵּהוּת\">כֵּהוֹת</a>, <a href=\"#\" data-headword=\"כֵּהֶה\">כֵּי׳</a>. Ib.; <span class=\"citation\">Y. Pes. I, beg. 27ᵃ</span> <span dir=\"rtl\">בשעה שהיו כ׳ וכ׳</span> when the lights burned dimly, we knew it was day-time. Ib. 27ᵇ top <span dir=\"rtl\">בשעה שהיו כיהות</span> when the jewels were dim.—Pesik. Kumi, p. 145ᵇ (ref. to <span dir=\"rtl\">כ̇ה̇חלנות</span> <span class=\"citation\">Ez. XL, 25</span>) <span dir=\"rtl\">חלונות כ׳ היו</span> the windows were dim (stained glass). <span class=\"citation\">Ḥag. 16ᵃ</span> <span dir=\"rtl\">עיניו כ׳</span> his eyes will grow dim; a. e.</div><div class=\"sense\"><b>—2)</b>  (of leprosy) <i>faint, dull</i>, opp. <a href=\"#\" data-headword=\"עַזָּה I\">עזה</a>. <span class=\"citation\">Neg. II, 1</span>, v. <a href=\"#\" data-headword=\"בַּהֶרֶת\">בַּהֶרֶת</a>. <span class=\"citation\">Ib. 2</span> <span dir=\"rtl\">לפי שהכ׳נראית עזה</span> because (in the early morning &amp;c.) the faint spot appears bright; Sifra Thazr., Neg., <span class=\"citation\">Par. II</span>, ch. II.—<span class=\"citation\">Y. Shebu. I, 32ᵈ</span> <span dir=\"rtl\">הִכְהָה טמא הִכְ׳ מן הַכֵּ׳ טהור</span> if it grows one shade fainter, it is unclean, but when it grows fainter than the next fainter shade, it is clean; Sifra l. c. ed. Ven.; <span class=\"citation\">Yalk. Lev. 551</span> <span dir=\"rtl\">כִּיהָה מן הכֵּ׳</span>; Y. l. c.; a. fr.—</div><div class=\"sense\"><b>*3)</b>  (trnsf.) <i>doubtful</i>. <span class=\"citation\">Nidd. 19ᵃ</span>; <span class=\"citation\">Naz. 65ᵇ</span>; <span class=\"citation\">Snh. 87ᵇ</span>; <span class=\"citation\">Keth. 75ᵇ</span> ר׳ י׳ אומר כ׳ R. Josh. says, It is doubtful; (<span class=\"citation\">Neg. IV, 11</span> <span dir=\"rtl\">ר׳ י׳ קֵיהָה</span> or <a href=\"#\" data-headword=\"כהי\">כִּיהָה</a>, v. <a href=\"#\" data-headword=\"כהי\">כהי</a>, <a href=\"#\" data-headword=\"קהי\">קהי</a>).</div>","alt":["כֵּו׳","כֵּהָה","כֵּי׳"]},"12014":{"h":"כְּהוּנָּה","r":"K00152","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>priesthood, priestly privileges; priestly community.</i> <span class=\"citation\">Ab. IV, 13</span>. <span class=\"citation\">Sot. 11ᵇ</span> <span dir=\"rtl\">בתי כ׳</span> priestly families. <span class=\"citation\">Midd. I, 8</span>, a. fr. <span dir=\"rtl\">פרחי כ׳</span> young priests (novices). <span class=\"citation\">Y. Ber. III, 6ᵃ</span> bot.; <span class=\"citation\">Y. Naz. VII, 56ᵃ</span> top <span dir=\"rtl\">אין כ׳ היום</span> there is no priesthood to-day (the laws for priests are suspended on the day of Rabbi’s funeral). <span class=\"citation\">Tosef. Ḥall. II, 7</span>, a. fr. <span dir=\"rtl\">כ&quot;ד מתנות כ׳</span> twenty-four gifts of priesthood (priestly prerogatives). <span class=\"citation\">Keth. 14ᵃ</span> <span dir=\"rtl\">כשרה לכ׳</span> fit to marry into the priesthood; a. v. fr.</div>","alt":[]},"12015":{"h":"כְּהוּנְּתָא","r":"K00153","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ex. XXIX, 9</span>. <span class=\"citation\">Targ. Num. XVI, 10</span> <span dir=\"rtl\">כ׳ רבתא</span> high-priesthood; a. fr.—<span class=\"citation\">Targ. O. Ex. XL, 15</span> <span dir=\"rtl\">כְּהוּנַת</span> ed. Berl. (ed. <a href=\"#\" data-headword=\"כַּהֲנוּתָא\">כַּהֲנוּת</a>).—<span class=\"citation\">Y. Keth. I, 25ᶜ</span> <span dir=\"rtl\">סליקא לכ׳</span> she rose to priesthood (as a priest’s wife); <span dir=\"rtl\">נחיתא מן כ׳</span> went down from priesthood (ceased to enjoy priestly privileges as a priest’s wife).</div>","alt":["כְּהוּנְתָּא"]},"12016":{"h":"כֵּהוּת","r":"K00154","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּהָא\">כָּהָה</a>) <i>dimness</i>. <span class=\"citation\">Meg. 28ᵃ</span> (ref. to <span class=\"citation\">Gen. XX, 16</span>) <span dir=\"rtl\">א&quot;ת כסות … אלא כ׳ עינים</span> Ms. M. (ed. <span dir=\"rtl\">כסיית</span>) read not ‘cover of the eyes’ but ‘dimness of eye-sight’; <span class=\"citation\">Yalk. Gen. 91</span>.</div>","alt":[]},"12017":{"h":"כָּהוּתָא","r":"K00155","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּהִי\">כְּהִי</a>) <i>worriment, trouble</i>. <span class=\"citation\">Targ. Prov. XXVI, 21</span>, v. <a href=\"#\" data-headword=\"בָּהוּתָא\">בָּהוּתָא</a> (ed. Lag. <a href=\"#\" data-headword=\"הַרְתָּא\">הַרְתָּא</a>).</div>","alt":[]},"12018":{"h":"כהי","r":"K00156","html":"<div class=\"sense\"><b>1)</b> <i>to be dim</i> (of sight, light). <span class=\"citation\">Gen. R. s. 65</span> <span dir=\"rtl\">כָּהוּ עיניו</span> his eyes grew dim. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שיִכְהוּ עיניו</span> that his eye-sight shall fail. <span class=\"citation\">Kidd. 24ᵇ</span> <sub>…</sub> <span dir=\"rtl\">הכהו וכָהֲתָה</span> if the master struck him on his eye, and it grew dim; a. fr.—Part. pass. <span dir=\"rtl\">כָּהוּי</span>, f. <span dir=\"rtl\">כָּהוּיָה</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">הרי שהיתה עינו כ׳ וכ׳</span> if his eye-sight was dim, and he (the master) made him perfectly blind.</div><div class=\"sense\"><b>—2)</b>  (of color) <i>to be dull</i>, v. <a href=\"#\" data-headword=\"כֵּהֶה\">כֵּהֶה</a>. [Tosef. Erub. XI (VIII), 8; Tanḥ. Noah 9, v. <a href=\"#\" data-headword=\"כָּחַח\">כָּחַח</a>.]</div><div class=\"sense\"><b>Pi. כִּיהָה  כִּהָה</b> <div class=\"sense\"><i>to grow duller, to be shaded</i>. Sifra Thazr., Neg., Par. 2, ch. II <span dir=\"rtl\">אם העז וכ׳</span> if the spot grew brighter and grew duller again; a. fr.—2) <i>to declare doubtful.</i> <span class=\"citation\">Neg. IV, 11</span> <span dir=\"rtl\">ר׳ י׳ כ׳</span>, v. <a href=\"#\" data-headword=\"כֵּהֶה\">כֵּהֶה</a>.</div></div><div class=\"sense\"><b>Hif. הִכְהָה</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"כָּהוּתָא\">same</a>. Y. Shebu. I, 32ᵈ, v. <a href=\"#\" data-headword=\"כֵּהֶה\">כֵּהֶה</a>. <span class=\"citation\">Neg. XI, 5</span> <span dir=\"rtl\">ה׳ בתחלה</span> if the suspicious spot grew fainter at once (before the ordered isolation was begun); <span dir=\"rtl\">ה׳ בראשון</span> if it grew faint in the first week; Tosef. ib. V, 6 quot. in R. S. to Neg. l. c. (ed. Zuck. <span dir=\"rtl\">כהה כתחלה</span>, oth. ed. only <span dir=\"rtl\">כתחלה</span>, corr. acc.); a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to make dim</i>. Gen. R. l. c. <span dir=\"rtl\">הריני מַכְהֶה וכ׳</span> I will make his eye-sight dim. <span class=\"citation\">Yalk. Ruth 601</span> <span dir=\"rtl\">ייסורין מַכְהִין וכ׳ …</span> sufferings of poverty dim men’s eyes. <span class=\"citation\">Pesik. R. s. 14</span> <span dir=\"rtl\">מכהה גלגל חמה</span> dimmed (outshone) the sun in brightness; Pesik. Parah, p. 37ᵃ <span dir=\"rtl\">שיַכְהֶה</span>; a. e.</div></div>","alt":["כָּהָה"]},"12019":{"h":"כְּהִי","r":"K00157","html":"<div class=\"sense\"><span class=\"citation\">Targ. Gen. XXVII, 1</span>. <span class=\"citation\">Targ. I Kings XIV, 4</span>; a. e.—<span class=\"citation\">Y. Ned. IX, 41ᵇ</span> bot. <span dir=\"rtl\">עיני כַּהֲיָיא</span> my eye-sight is failing.</div><div class=\"sense\"><b>Pa. כַּהֵי  כַּהֵה</b> <div class=\"sense\"><b>1)</b> <i>to dim, make blind</i>. <span class=\"citation\">Yoma 69ᵇ</span>; <span class=\"citation\">Snh. 64ᵃ</span> כַּהֲיִינְהוּ לעיניה Ar. (ed. <a href=\"#\" data-headword=\"כחלינהו\">כחלינהו</a>, cmp. <a href=\"#\" data-headword=\"כְּבִי\">כְּבִי</a>) they made his eye-sight dim. Ib. 27ᵃ <span dir=\"rtl\">ליכַהֲיוּהוּ לעיניה</span> (v. Rabb. D. S. a. l. note 80) he shall be blinded.</div><div class=\"sense\"><b>—2)</b>  (sub. <span dir=\"rtl\">לִבֵּיה</span>) <i>to be angry;</i> (with <a href=\"#\" data-headword=\"ב\">ב־</a> of person) <i>to rebuke</i>. <span class=\"citation\">Targ. I Sam. III, 13</span>.</div></div><div class=\"sense\"><b>Af. אַכְהֵי</b> <div class=\"sense\"><b>1)</b> <i>to dim</i>. <span class=\"citation\">Targ. Ez. XXXII, 7</span> <span dir=\"rtl\">באַכְהָיוּתִי</span> when I make dim (h. text <span dir=\"rtl\">בכבותך</span>).</div><div class=\"sense\"><b>—2)</b> <i>to make the heart faint, to annoy, reproach</i> (<i>falsely</i>). Ib. XIII, 22 <span dir=\"rtl\">אַכְהֵיתִין לב וכ׳</span> ye denounced the heart of the righteous to be false (h. text <span dir=\"rtl\">הכאות</span>).</div></div><div class=\"sense\"><b>Ithpe. אִתְכְּהִי</b> <div class=\"sense\"><i>to be reproached</i>. Ib. (h. text <span dir=\"rtl\">הכאבתיו</span>).</div></div>","alt":["כְּהָא"]},"12020":{"h":"כֵּהָיוֹן","r":"K00158","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּהִי\">preced.</a> wds.) <i>dimness, fainter color</i>. <span class=\"citation\">Tosef. Neg. V, 6</span> <span dir=\"rtl\">חזר לכ׳</span> if the suspicious spot again turned fainter.</div>","alt":[]},"12021":{"h":"כַּהֲיוּתָא","r":"K00159","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כֵּהָיוֹן\">preced.</a> wds.) <i>blindness</i>. <span class=\"citation\">Bekh. 44ᵃ</span>, contrad. to <a href=\"#\" data-headword=\"מַחְסוֹרְיָיתָא\">מחסורייתא</a> defective eye-sight.</div>","alt":[]},"12022":{"h":"*כַּהֲיִי","r":"K00160","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Kahăyi</i>. Y. Pes. II, end, 29ᶜ ed. Krot. (oth. ed. <span dir=\"rtl\">בחיי</span>).</div>","alt":[]},"12023":{"h":"כָּהֵיל","r":"K00161","html":"<div class=\"sense\">, v. <span dir=\"rtl\">כְּהֵל</span></div>","alt":[]},"12024":{"h":"כָּהֵין","r":"K00162","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּהֵן ²\"><span dir=\"rtl\">כָּהֵן</span> I</a></div>","alt":[]},"12025":{"h":"כֹּהֵן","r":"K00163","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"כּוּן\">כּוּן</a>; cmp. b. h. <a href=\"#\" data-headword=\"כַּן\">כַּן</a>) [<i>standing, stationed</i>,] <i>officer</i>, esp. <i>priest</i>. <span class=\"citation\">Yoma 6ᵃ</span>, a. fr. <span dir=\"rtl\">כ׳ גדול</span> (abbr. <span dir=\"rtl\">כ&quot;ג</span>) high priest, <span dir=\"rtl\">כ׳ הדיוט</span> ordinary priest. <span class=\"citation\">Meg. I, 9</span> <span dir=\"rtl\">כ׳ משוח</span> an anointed high priest, contrad. to <span dir=\"rtl\">מרובה בגדים</span> a high priest distinguished only by his robes (but not anointed, as in the days of the Second Temple). Ib. <span dir=\"rtl\">כ׳ משמש</span> officiating highpriest, <span dir=\"rtl\">כ׳ שעבר</span> a substitute of the high priest no longer required, ex-substitute. <span class=\"citation\">Hor. III, 8</span> <span dir=\"rtl\">ממזר … קודם לכ&quot;ג ע&quot;ה</span> a bastard who is a scholar has the precedence of an ignorant high priest; a. v. fr.—Pl. <a href=\"#\" data-headword=\"כֹּהֲנִי\">כֹּהֲנִים</a>. <span class=\"citation\">Yeb. 86ᵇ</span>, a. e. <span dir=\"rtl\">בכ&quot;ד מקומות נקראו הכ׳ וכ</span> in twenty four Biblical passages the priests are designated as Levites; a. v. fr.—<span dir=\"rtl\">תּוֹרַת כֹּהֲנִים</span> (abbr. <span dir=\"rtl\">ת&quot;כ</span>) <i>Torath Kohănim</i>, a) name of <i>the third book of Moses, Leviticus</i>. <span class=\"citation\">Kidd. 33ᵃ</span>. <span class=\"citation\">Lev. R. s. 7</span> <span dir=\"rtl\">מפני מה … בת&quot;כ</span> why do we, in teaching children, commence with Leviticus? a. e.—b) name of <i>an halachic commentary to Leviticus</i>, also named <i>Sifra</i>. <span class=\"citation\">Yeb. 72ᵇ</span>; a. fr.—Fem. <a href=\"#\" data-headword=\"כֹּהֶנֶת\">כֹּהֶנֶת</a>, <span dir=\"rtl\">כּוֹהֶ׳</span> <i>a priest’s daughter</i> or <i>wife</i>. <span class=\"citation\">Ḥull. 131ᵇ</span>, sq.—<span class=\"citation\">Keth. IV, 8</span> <span dir=\"rtl\">ובכ׳</span> and in the case of a priest’s wife. <span class=\"citation\">Ib. VII, 1</span>, sq. (70ᵃ) <span dir=\"rtl\">ובכ׳</span> Mish. a. Y. ed. (Bab. ed. <span dir=\"rtl\">ובכהן</span>). Ib. 71ᵃ; a. fr.—Pl. <span dir=\"rtl\">כֹּהֲנוֹת</span>, <span dir=\"rtl\">כּוֹהֲ׳</span>. <span class=\"citation\">Ber. 44ᵃ</span>. <span class=\"citation\">Yeb. III, 10</span> <span dir=\"rtl\">אם היו כ׳</span> (Y. ed. <span dir=\"rtl\">כוה׳</span>) if they are daughters of priests; a. e.</div>","alt":[]},"12026":{"h":"כָּהַן","r":"K00164","html":"<div class=\"sense\">, (b. h.), <i>Nithpa.</i> <span dir=\"rtl\">נִתְכַּהֵן</span> (denom. of <a href=\"#\" data-headword=\"כֹּהֵן\">כֹּהֵן</a>) <i>to be appointed priest, to act as priest</i>. <span class=\"citation\">Zeb. 101ᵇ</span> לא נ׳ פנחס וכ׳ Phineas was not appointed high priest until &amp;c. <span class=\"citation\">Ib. 102ᵃ</span></div>","alt":[]},"12027":{"h":"כָּהֵן","r":"K00165","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Jer. XIV, 18</span>. <span class=\"citation\">Targ. Mal. II, 7</span>. <span class=\"citation\">Targ. Lev. I, 7</span>; a. v. fr.—<span class=\"citation\">Snh. 110ᵃ</span>, a. fr. <span dir=\"rtl\">כ׳ רבא</span> high priest. <span class=\"citation\">Ḥull. 49ᵃ</span> ישמעאל כ׳ מסייע כהני Ishmael, being a priest, favors the priests. <span class=\"citation\">Gitt. 59ᵇ</span> <span dir=\"rtl\">קרי בכ׳</span> read from the Torah in the priest’s place, i.e. was called up the first; <span class=\"citation\">Meg. 22ᵃ</span> Ms. O. (ed. <span dir=\"rtl\">בכהני</span> pl.); a. fr.—Pl. <span dir=\"rtl\">כַּהֲנִין</span>, <span dir=\"rtl\">כַּהֲנַיָּא</span>, <a href=\"#\" data-headword=\"כֹּהֲנִי\">כַּהֲנֵי</a>. <span class=\"citation\">Targ. Ex. XIX, 6</span>. <span class=\"citation\">Targ. O. Lev. I, 5</span>; a. fr.—Gitt. l. c. <span dir=\"rtl\">כ׳ חשיבי דא&quot;י</span> highly esteemed Palestinean priests; a. fr.—<i>Fem</i>. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"כֹּהֶנֶת\">כֹּהֶנֶת</a>) <a href=\"#\" data-headword=\"כַּהַנְתָּא\">כַּהַנְתָּא</a></span>. <span class=\"citation\">Ḥull. 131ᵇ</span> … <span dir=\"rtl\">יהיב לכ׳</span> gave priestly gifts to a priest’s daughter (married to an Israelite). <span class=\"citation\">Pes. 49ᵃ</span> <span dir=\"rtl\">נסיב כ׳</span> married a priest’s daughter.—Pl. <a href=\"#\" data-headword=\"כַּהַנְתָּא\">כַּהֲנָתָא</a>. <span class=\"citation\">Ber. 44ᵃ</span></div>","alt":["כָּהֵין","כַּהֲנָא I"]},"12028":{"h":"כָּהֵן ²","r":"K00166","html":"<div class=\"sense\"> (or <a href=\"#\" data-headword=\"כֹּהֵן\">כֹּהֵן</a>), <a href=\"#\" data-headword=\"כָּהֵן\">כַּהֲנָא</a> II pr. n. m. <i>Kahen, Kahăna</i>, name of several Amoraim. <span class=\"citation\">Y. Ber. III, 6ᵃ</span>, a. fr. <span dir=\"rtl\">ר׳ כהן</span>.—<span class=\"citation\">B. Kam. 117ᵃ</span>. Y. R. Hash. IV, beg. 59ᵇ; a. fr.—<span class=\"citation\">Erub. 8ᵇ</span> <span dir=\"rtl\">רב כ׳ רביה דרב</span> (v., however, Ms. M. a. Rabb. D. S. a. l. notes); a. fr.—v. Fr. M’bo, p. 109ᵇ, sq.</div>","alt":[]},"12029":{"h":"כַּהֲנוּתָא","r":"K00167","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּהוּנְּתָא\">כְּהוּנְתָּא</a></div>","alt":[]},"12030":{"h":"כֹּהֲנִי","r":"K00168","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"כֹּהֵן\">כֹּהֵן</a>) <i>one proving priestly descent, belonging to the priestly caste</i>. <span class=\"citation\">Kidd. IV, 1</span>; <span class=\"citation\">Yeb. 37ᵃ</span> (collective noun).—Pl. <a href=\"#\" data-headword=\"כֹּהֲנִי\">כֹּהֲנִים</a>. <span class=\"citation\">Ib. 85ᵃ</span>; v. <a href=\"#\" data-headword=\"יִשְׂרְאֵלִי\">יִשְׂרְאֵלִי</a>.</div>","alt":[]},"12031":{"h":"*כַּהֲנָכָא","r":"K00169","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">כהן</span>, with format. <a href=\"#\" data-headword=\"כ\">כ</a>; v. letter <a href=\"#\" data-headword=\"כ\">כ</a>) <i>the attendant’s</i> or <i>priest’s lustral basin</i> (v. Sm. Ant. s. v. Chernips).—Pl. <a href=\"#\" data-headword=\"*כַּהֲנָכָא\">כַּהַנְכָתָא</a>. <span class=\"citation\">Targ. Y. Num. XXXI, 23</span>; cmp. <a href=\"#\" data-headword=\"*כַּרְנִיבָּאוֹת\">כַּרְנִיבָּאוֹת</a>.</div>","alt":["כַּהֲנַכְתָּא"]},"12032":{"h":"כֹּהֶנֶת","r":"K00170","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֹּהֵן\">כֹּהֵן</a></div>","alt":[]},"12033":{"h":"כַּהַנְתָּא","r":"K00171","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּהֵן ²\"><span dir=\"rtl\">כָּהֵן</span> I</a></div>","alt":[]},"12034":{"h":"כַּו","r":"K00172","html":"<div class=\"sense\"><i>, </i> pl. <a href=\"#\" data-headword=\"כַּלִּין\">כַּוִּין</a>, v. <a href=\"#\" data-headword=\"כַּוָּוא\">כַּוָּוא</a>, end.</div>","alt":[]},"12035":{"h":"כְּוָא","r":"K00173","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּוִי\">כְּוִי</a></div>","alt":[]},"12036":{"h":"כַּוַָּא","r":"K00174","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּוָּוא\">כַּוַָּוא</a></div>","alt":[]},"12037":{"h":"כְּוָאָה","r":"K00175","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , <i>burn, searing, cautery</i>. <span class=\"citation\">Targ. O. Ex. XXI, 25</span>. <span class=\"citation\">Targ. O. Lev. XIII, 24</span> (Y. ed. Amst. <a href=\"#\" data-headword=\"כַּוָּואָה\">כַּוָּואָה</a>).—<span class=\"citation\">Sabb. 62ᵇ</span>, v. <a href=\"#\" data-headword=\"כֵּיבָא\">כֵּיבָא</a>.</div>","alt":[]},"12038":{"h":"*כְּוָאנָא","r":"K00176","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pers. Arab. ḫiwân) <i>dining table</i>. Yalk. Ms. to <span class=\"citation\">II Kings ch. XVI</span> (from <span class=\"citation\">Taan. 25ᵃ</span>) <span dir=\"rtl\">אבואנא</span> (read <a href=\"#\" data-headword=\"*אִכְרוּם\">אַכְּ׳</a>) a 1a table; (Taan. l. c. <a href=\"#\" data-headword=\"פְּתוֹרָא\">פתורא</a>, Ms. M. <span dir=\"rtl\">אתּכָּא</span>, v. Rabb. D. S. l. c. note). Comp. <a href=\"#\" data-headword=\"כְּוַאנְגַּר\">next w.</a></div>","alt":[]},"12039":{"h":"כְּוַאנְגַּר","r":"K00177","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַכְוַנְגַּר\">אַכְוַנְגַּר</a></div>","alt":[]},"12040":{"h":"כַּוָּארָא","r":"K00178","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּוְורָא\">כַּוְורָא</a></div>","alt":[]},"12041":{"h":"כּוּב","r":"K00179","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*כְּבַב\">כָּבַב</a>, v. <a href=\"#\" data-headword=\"*כְּבַב\">כְּבַב</a>) </div><div class=\"sense\"><b>1)</b>  [<i>ball</i>,] <i>thorn, a prickly salt-plant</i>.—Pl. <span dir=\"rtl\">כּוּבִּים</span>, <span dir=\"rtl\">כּוּבִּין</span>. <span class=\"citation\">Gen. R. s. 49</span> <span dir=\"rtl\">למגל כוסחת כ׳</span> like a sickle mowing thorns; <span class=\"citation\">Yalk. Prov. 950</span> <a href=\"#\" data-headword=\"כּוּב\">כוב</a>. <span class=\"citation\">Ex. R. s. 42</span> <span dir=\"rtl\">נעשו כזבים</span> (corr. acc.), v. <a href=\"#\" data-headword=\"סֵרָיוּת\">סֵרָיוּת</a>.</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">מדבר כ׳</span> pr. n. <i>Desert of Kub</i> (cmp. <span class=\"citation\">Ez. XXX, 5</span>) = Biblical <a href=\"#\" data-headword=\"שׁוּר\">שׁוּר</a>. <span class=\"citation\">Ex. R. s. 24</span>; <span class=\"citation\">Yalk. ib. 255</span>; (Tanḥ. <span class=\"citation\">B’shall. 18</span>; Mekh. ib., Vayassa 1; <span class=\"citation\">Yalk. Jer. 266</span> <span dir=\"rtl\">בזב</span>).</div>","alt":[]},"12042":{"h":"כּוּבָּא I","r":"K00180","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Prov. XXVI, 9</span> (h. text <a href=\"#\" data-headword=\"חוֹחַ\">חוח</a>).—<span class=\"citation\">Gen. R. s. 44</span>; <span class=\"citation\">Yalk. Jer. 285</span> (prov.) <span dir=\"rtl\">עד דסנדלך … כ׳</span> while the sandal is on thy foot, tread the thorn down; Pesik. Asser, p. 99ᵇ <span dir=\"rtl\">כבוש בופה</span> (corr. acc.); <span class=\"citation\">Yalk. Deut. 892</span>.—Pl. <span dir=\"rtl\">כּוּבִּין</span>, <a href=\"#\" data-headword=\"כּוּבְיָא\">כּוּבַּיָּא</a>, <span dir=\"rtl\">כּוּבֵּי</span>, <span dir=\"rtl\">כֻּבּ׳</span>. <span class=\"citation\">Targ. Gen. III, 18</span> (some ed. <span dir=\"rtl\">כּוּבִין</span>, incorr.). <span class=\"citation\">Targ. II Sam. XXIII, 6</span>. <span class=\"citation\">Targ. Hos. II, 8</span>.—<span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד כות׳ 1), v. <a href=\"#\" data-headword=\"גְּבַב\">גְּבַב</a>,—<span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span> <span dir=\"rtl\">לאילין כ׳</span>, v. <a href=\"#\" data-headword=\"סְדַר\">סְדַר</a>. Ib. bot. <span dir=\"rtl\">סייגין כ׳</span> (read <span dir=\"rtl\">דכ׳</span>) hedges of thornbushes. <span class=\"citation\">Gen. R. s. 2</span> (ref. to <span class=\"citation\">Gen. I, 2</span>) <span dir=\"rtl\">עד דהיא פגה אפיקת כ׳</span> while she (the earth) was yet in her incipiency, she produced thorns; <span class=\"citation\">Yalk. Gen. 4</span> <span dir=\"rtl\">כובה</span> (corr. acc.); <span class=\"citation\">Yalk. Jer. 274</span> <span dir=\"rtl\">כובי</span>; <span class=\"citation\">Yalk. Prov. 959</span>.</div>","alt":["כֻּבָּא"]},"12043":{"h":"כּוּבָּא II","r":"K00181","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כּוּבָּא I\">preced.</a>; cmp. <a href=\"#\" data-headword=\"כַּד II\"><span dir=\"rtl\">כַּד</span> II</a>) </div><div class=\"sense\"><b>1)</b> <i>wine cask</i>(h. . <span class=\"citation\">Sabb. 48ᵃ</span>. <span class=\"citation\">Ab. Zar. 60ᵃ</span> <span dir=\"rtl\">נכרי אדנא וישראל אכ׳</span> the gentile attending to the barrel (emptying it) and the Israelite to the cask (receiving the wine). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כ׳ מליא</span> (if the gentile carries) a cask which is brimful. <span class=\"citation\">Sabb. 141ᵃ</span> [read:] <span dir=\"rtl\">לא ליצדד … כ׳ בארעא</span> (v. Rabb. D. S. a. l. note) one must not (on the Sabbath) bend sideways a cask which rests in the ground; a. e.—Pl. <span dir=\"rtl\">כּוּבֵּי</span>. <span class=\"citation\">Ab. Zar. 33ᵇ</span> <span dir=\"rtl\">אנס הני כ׳ וכ׳</span> carried casks away from Pumbeditha by force. <span class=\"citation\">B. Mets. 25ᵇ</span>.—בי כ׳ <i>the retailer’s wine shop</i>. <span class=\"citation\">B. Kam. 86ᵃ</span>; <span class=\"citation\">B. Mets. 64ᵇ</span> <span dir=\"rtl\">מרקיד בי כ׳</span> he dances in the wine house.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"כּוֹבַע\">כּוֹבַע</a>, <a href=\"#\" data-headword=\"אֲקוּנְבִּי\">אֲקוִּנְבִּי</a>), pl. <span dir=\"rtl\">כּוּבֵּי</span> <i>turrets</i> of a fort. <span class=\"citation\">Yoma 11ᵃ</span> <span dir=\"rtl\">חזוק אקרא דכ׳</span> a support for the Fort of Turrets (of M’ḥuza); [Ms. L. <span dir=\"rtl\">ליוקרא דכ׳</span> for the weight of &amp;c.; v. Rabb. D. S. a. l. note 400.]—<span class=\"citation\">Kidd. 70ᵇ</span> <span dir=\"rtl\">בי כ׳ דפומבדיתא</span> the fort of P.—[<span class=\"citation\">Meg. 6ᵃ</span> <span dir=\"rtl\">בי כ׳</span> ed. (Ms. M. <a href=\"#\" data-headword=\"כסי\">כסי</a>, Ms. O. <span dir=\"rtl\">מִכְסֵי</span>); <span class=\"citation\">Keth. 112ᵃ</span> <span dir=\"rtl\">מִיכְסֵי</span>.]</div>","alt":[]},"12044":{"h":"כּוּבָּא III","r":"K00182","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*כְּבַב\">כְּבַב</a><i>Pa</i>.) <i>roasted</i> or <i>charred dough</i>, <span dir=\"rtl\">כ׳ דארעא</span> <i>roasted</i> (<i>over coals</i>) <i>in a cavity of the ground</i>, name of <i>a pastry baked in a cavity made in the stove</i>. <span class=\"citation\">Ber. 37ᵇ</span>, expl. <a href=\"#\" data-headword=\"טרוקנין\">טרוקנין</a>. <span class=\"citation\">Ib. 38ᵃ</span>. [Ar. s. v. <a href=\"#\" data-headword=\"כַּכָּא\">ככא</a>, reads <a href=\"#\" data-headword=\"כּוּךְ ²\">כוכא</a>.] [<span class=\"citation\">Gitt. 68ᵃ</span> bot., v. <a href=\"#\" data-headword=\"כּוּךְ ²\">כּוֹכָא</a>.]</div>","alt":[]},"12045":{"h":"כובאי","r":"K00183","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בִּיכַאי\">בִּיכַי</a></div>","alt":[]},"12046":{"h":"כּוֹבֶד","r":"K00184","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>weight, heaviness, pressure</i>. <span class=\"citation\">Snh. 63ᵇ</span> א&quot;ת כבודו אלא כּוֹבְדוֹ Ms. M., v. <a href=\"#\" data-headword=\"כָּבֵד II\"><span dir=\"rtl\">כָּבֵד</span> II</a>. <span class=\"citation\">Yoma 41ᵇ</span> <span dir=\"rtl\">בעי כ׳</span> it requires weight (must be heavy so as to sink into the fire). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כדי שיהא בהן כ׳</span> (they are tied together) in order that they may be heavy. <span class=\"citation\">Y. Ḥag. II, 77ᵈ</span> <span dir=\"rtl\">צריך לכבוש את כּוֹבְדוֹ</span> (in putting his hands on the sacrifice) he must press his weight on it; (Bab. <span class=\"citation\">ib. 16ᵇ</span> <span dir=\"rtl\">סמיכה בכל בחו</span>). <span class=\"citation\">Naz. 5ᵃ</span> <a href=\"#\" data-headword=\"כ׳\">כ׳</a> the feeling of heaviness (of the hair).—כ׳ ראש <i>bending down the head; humble, solemn disposition</i>, opp. <span dir=\"rtl\">קלות ראש</span>. <span class=\"citation\">Ber. V, 1</span> <span dir=\"rtl\">אין עומדין … כ׳ ראש</span> we must not rise for prayer in any other than a humble &amp;c. <span class=\"citation\">Y. Ab. Zar. I, 39ᵈ</span> top; <span class=\"citation\">Tosef. Ab. Zar. I, 2</span> <span dir=\"rtl\">שואל בשלומו בכ׳ ר׳</span> greet him with a bent head (without ostentation). <span class=\"citation\">M. Kat. 21ᵇ</span> <span dir=\"rtl\">בשפה רפה ובכ׳ ר׳</span> in an undertone and with solemnity.</div><div class=\"sense\"><b>—2)</b> <i>roller</i> or <i>beam of a loom</i>; <span dir=\"rtl\">כ׳ העליון</span> the upper beam from which the warp depends; <span dir=\"rtl\">כ׳ התחתון</span> the lower beam, the roller on which the web is wound as it advances. <span class=\"citation\">Kel. XXI, 1</span> (Talm. ed. <a href=\"#\" data-headword=\"כֹּבֶד\">כֹּבֶד</a>). <span class=\"citation\">Neg. XI, 9</span> (<i>fem</i>.). <span class=\"citation\">Sabb. 113ᵃ</span>; Y. ib. XVII, 16ᵃ bot.</div>","alt":[]},"12047":{"h":"כובדים","r":"K00185","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כוברים\">כוברים</a></div>","alt":["כובדין"]},"12048":{"h":"כּוּבְיָא","r":"K00186","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>frying pan</i>, v. <a href=\"#\" data-headword=\"בּוּבְיָא I\"><span dir=\"rtl\">בּוּבְיָא</span> I</a>.</div>","alt":[]},"12049":{"h":"*כּוּבִּיתָא","r":"K00187","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*כְּבַב\">כְּבַב</a>, cmp. <a href=\"#\" data-headword=\"כּוּב\">כּוּב</a>) <i>a little globe</i>. <span class=\"citation\">R. Hash. 24ᵃ</span> <span dir=\"rtl\">כ׳ דעיבא וכ׳</span> ed. (Ms. M. 1 <a href=\"#\" data-headword=\"כּוֹכְבִיתָא\">כּוֹכְבִיתָא</a>, Ms. M. 2 a. Ar. <a href=\"#\" data-headword=\"כוכיתא\">כוכיתא</a>) they saw merely a globe-shaped cloudlet (which, they thought, was the moon).</div>","alt":[]},"12050":{"h":"כובליאר","r":"K00188","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוֹכְלִיאָר\">כּוֹכְלִיאָר</a></div>","alt":[]},"12051":{"h":"כּוֹבְלִין","r":"K00189","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֶּבֶל\">כֶּבֶל</a></div>","alt":[]},"12052":{"h":"כּוֹבֶלֶת","r":"K00190","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*כּוֹכֶלֶת\">כּוֹכֶלֶת</a></div>","alt":[]},"12053":{"h":"כּוֹבֵס","r":"K00191","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>washer, fuller</i>. <span class=\"citation\">Ber. 28ᵃ</span>; <span class=\"citation\">Keth. 103ᵇ</span>; a. e.—Pl. <a href=\"#\" data-headword=\"כּוֹבְלִין\">כּוֹבְסִין</a>. <span class=\"citation\">Tosef. Kel. B. Mets. III, 14</span> (ed. Zuck. <span dir=\"rtl\">כובשין</span>), v. <a href=\"#\" data-headword=\"מְלַקֵּט II\"><span dir=\"rtl\">מְלַקֵּט</span> II</a>.</div>","alt":[]},"12054":{"h":"כּוּבְסָא","r":"K00192","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּבָסָא\">כְּבָסָא</a></div>","alt":[]},"12055":{"h":"כּוֹבַע","r":"K00193","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>helmet, turban</i>. <span class=\"citation\">Ber. 24ᵃ</span> <span dir=\"rtl\">מניחן בכ׳ וכ׳</span> let him put them (the T’fillin) into the turban under his pillow. <span class=\"citation\">Gitt. 14ᵇ</span> (of the Persians) <span dir=\"rtl\">כּוֹבְעָן אמה</span> their turban is one cubit high; a. e.—Pl. <span dir=\"rtl\">כּוֹבְעִים</span>, <a href=\"#\" data-headword=\"כּוֹבְלִין\">כּוֹבְעִין</a>. <span class=\"citation\">Gen. R. s. 99</span> <span dir=\"rtl\">לובשי כ׳</span> wearing helmets. Y. Gitt. I, end, 43ᵈ; <span class=\"citation\">Y. Kidd. III, 64ᵃ</span> bot. <span dir=\"rtl\">כּוֹבְעֵיהֶן אמה</span> (v. supra).—Trnsf. <i>the thyroid cartilage, Adam’s apple</i>. <span class=\"citation\">Ḥull. 19ᵃ</span> <span dir=\"rtl\">משיפוי כ׳ וכ׳</span> from where the thyroid cartilage begins to protrude and downward.</div>","alt":[]},"12056":{"h":"כּוֹבְעָא","r":"K00194","html":"<div class=\"sense\">, esp. <i>the priest’s turban</i>.—Pl. <a href=\"#\" data-headword=\"כּוֹבְלִין\">כּוֹבְעִין</a>, <span dir=\"rtl\">כּוֹבְעַיָּא</span>. <span class=\"citation\">Targ. Ex. XXVIII, 40</span>; <span class=\"citation\">XXXIX, 28</span>; a. e. (ed. Berl. <a href=\"#\" data-headword=\"ק׳\">ק׳</a>; h. text <span dir=\"rtl\">מגבעות</span>).—Trnsf. <span dir=\"rtl\">חודא דכובעא</span> the highest point of the <i>thyroid cartilage</i>, v. <a href=\"#\" data-headword=\"כּוֹבַע\">preced.</a> <span class=\"citation\">Ḥull. 18ᵇ</span></div>","alt":[]},"12057":{"h":"כּוֹבְעָה","r":"K00195","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <span dir=\"rtl\">כּוֹבְעוֹת</span> (<a href=\"#\" data-headword=\"כּוֹבְעָא\">preced.</a> wds.) the <i>tops of stalks of sheaves</i>. <span class=\"citation\">Peah V, 8</span> <span dir=\"rtl\">המעמר לכ׳</span> he who binds sheaves for covering the stalks; expl. Y. ib. V, end, 19ᵃ <span dir=\"rtl\">מן לעיל</span> sheaves to be put on top, opp. <span dir=\"rtl\">לכומסות</span>; v. <a href=\"#\" data-headword=\"כּוֹמְסָה\">כּוֹמְסָה</a>.</div>","alt":[]},"12058":{"h":"כוברים","r":"K00196","html":"<div class=\"sense\">, <span class=\"citation\">Pesik. R. s. 14</span> <span dir=\"rtl\">לולייאני בר׳ כ׳</span>, Pesik. Par., p. 39ᵃ <span dir=\"rtl\">שוורי׳</span>, read: <span dir=\"rtl\">טַבְרִינִי</span>, as Tanḥ., ed. Bub., <span class=\"citation\">B’resh. 4</span> (v. Pesik. l. c. note 167).</div>","alt":["כובד׳"]},"12059":{"h":"כּוּבְרִיתָא","r":"K00197","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּבָּרִיתָא\">כַּבָּרִיתָא</a></div>","alt":[]},"12060":{"h":"כּוֹבֵשׁ","r":"K00198","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">כּוֹבְשִׁים</span>, (<a href=\"#\" data-headword=\"כָּבַשׁ\">כָּבַשׁ</a>) <span dir=\"rtl\">כּוֹבְשִׁין</span> <i>troops of siege, stormers</i>. Pesik. Vayhi p. 67ᵃ <span dir=\"rtl\">העמיד עליהן כ׳ כגון האדבה</span> he orders against them the storming troops which corresponds to the plague of locusts; <span class=\"citation\">Pesik. R. s. 17</span>.—[Y. Erub. II, 24ᵇ bot. <span dir=\"rtl\">כובשי כבשים</span>, read: <span dir=\"rtl\">כִּבּיּשֵׁי</span>]. [<span class=\"citation\">Tosef. Kel. B. Mets. III, 14</span> ed. Zuck., v. <a href=\"#\" data-headword=\"כּוֹבֵס\">כּוֹבֵס</a>.]</div>","alt":[]},"12061":{"h":"כּוּבְשָׁנָא","r":"K00199","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּפְשָׁנָא\">כּוּפְשָׁנָא</a></div>","alt":[]},"12062":{"h":"כּוּבֶּשֶׁת","r":"K00200","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּבֶּשֶׁת\">כַּבֶּשֶׁת</a></div>","alt":[]},"12063":{"h":"כּוּד","r":"K00201","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּיר\">כִּיר</a></div>","alt":[]},"12064":{"h":"*כּוּדָא","r":"K00202","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"כַּבְדָּא\">כבדא</a>, cmp. Syr. <a href=\"#\" data-headword=\"*כּוּדָא\">כודא</a>, <span dir=\"rtl\">כודתא</span>, P. Sm. 1690 sq., a. <a href=\"#\" data-headword=\"קָשָׁה\">קָשָׁה</a>) <i>suffering in child-birth</i>. <span class=\"citation\">Ab. Zar. 29ᵃ</span> <span dir=\"rtl\">לכ׳ בשיכרא</span> for a woman in child-birth the mixture is made with beer.</div>","alt":["כַּוְדָּא"]},"12065":{"h":"כּוּדְנָא","r":"K00203","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"כָּדַן\">כדן</a>) [<i>working beast</i>,] <i>mule</i>. <span class=\"citation\">Targ. Ps. XXXII, 9</span> (Ms. <a href=\"#\" data-headword=\"כּוּנְדָּא\">כונדא</a>).—<span class=\"citation\">Sabb. 110ᵇ</span> <span dir=\"rtl\">כפותא דכ׳ חיורא</span> (Rashi <a href=\"#\" data-headword=\"חִיוַּור\">חיוורתא</a>) excrements of a white mule.—<span class=\"citation\">B. Bath. 91ᵃ</span> כ׳ עקרה במאי פרע לי Ms. M. (ed. <span dir=\"rtl\">פרעא</span>, Ar. <span dir=\"rtl\">כודניא</span>) the mule (Manoah) being barren, how will he pay me back?—Pl. <span dir=\"rtl\">כּוּדְנַיָּא</span>. <span class=\"citation\">Targ. Zech. XIV, 15</span>.—<i>Fem</i>. <a href=\"#\" data-headword=\"כּוּדְנָא\">כּוּדְנָיָא</a>, <a href=\"#\" data-headword=\"כּוּזַנְתָּא\">כּוּדַנְתָּא</a>. <span class=\"citation\">Targ. II Sam. XIII, 29</span>; a. e.—<span class=\"citation\">Bekh. 8ᵇ</span>.—Pl. <span dir=\"rtl\">כּוּדַנְיָן</span>, <span dir=\"rtl\">כּוּדַנְיָן</span>, <span dir=\"rtl\">כּוּדְנַיָּיתָא</span>. <span class=\"citation\">Targ. I Kings X, 25</span>; <span class=\"citation\">Targ. II Chr. IX, 24</span>. <span class=\"citation\">Targ. Y. Gen. XXXVI, 24</span> (not <span dir=\"rtl\">כּוֹדְנַיְיתָא</span>). <span class=\"citation\">Targ. Is. LXVI, 20</span> <span dir=\"rtl\">כודנוון</span> ed. Lag. (ed. Wil. <a href=\"#\" data-headword=\"כִּדְנְוָן\">כִּדְנְיָן</a>); a. e.—<span class=\"citation\">Ḥull. 7ᵇ</span> <span dir=\"rtl\">כ׳ חיוורתא</span> white mules. [<span class=\"citation\">B. Mets. 97ᵃ</span> <span dir=\"rtl\">כודנייתא</span>, Ms. M. <span dir=\"rtl\">כונדתיה</span>, read <span dir=\"rtl\">כּוּדַנְתֵּיה</span> his mule.]</div>","alt":[]},"12066":{"h":"כָּוָה","r":"K00204","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כוי\">כוי</a></div>","alt":[]},"12067":{"h":"כּוֹהֵן","r":"K00205","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֹּהֵן\">כֹּהֵן</a></div>","alt":["כּוֹהֶנֶת"]},"12068":{"h":"כַּוָּוא","r":"K00206","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (√<a href=\"#\" data-headword=\"כַּו\">כו</a>, v. <a href=\"#\" data-headword=\"*כְּבַב\">כבב</a>, <i>to be arched, hollow</i>) = h. <a href=\"#\" data-headword=\"חַלּוֹן\">חַלּוֹן</a>, <i>aperture, window</i>. <span class=\"citation\">Targ. Zeph. II, 14</span> (ed. Lag. <a href=\"#\" data-headword=\"כָּוָה\">כַּוָּה</a>). <span class=\"citation\">Targ. Prov. VII, 6</span> ed. Lag. (oth. ed. <a href=\"#\" data-headword=\"כַּלַּיָּא\">כַּוַּיָּא</a> pl.). <span class=\"citation\">Targ. Hos. XIII, 3</span> <span dir=\"rtl\">כַּוַּת נורא</span> smoke-hole; a. e.—<span class=\"citation\">M. Kat. 11ᵃ</span> כוותא דדשא Ar. a. Rashi Ms. (ed. <a href=\"#\" data-headword=\"קביותא\">קביותא</a>, Ms. M. <a href=\"#\" data-headword=\"קַבְוָותָא\">קבוותא</a>, v. Rabb. D. S. a. l. note) the arch of the door, upper door-post. <span class=\"citation\">Y. Yeb. IV, 6ᵇ</span> bot. <span dir=\"rtl\">אודיק ר׳ מן כ׳</span> Rabbi looked out of the window. <span class=\"citation\">Sabb. 35ᵃ</span> <span dir=\"rtl\">וסימניך כ׳</span> (or <a href=\"#\" data-headword=\"כַּוָּוא\">כַּוָּותָא</a> <i>pl.</i>) thy sign by which to remember be ‘window’ (which reflects the light of the setting sun); a. fr.—<i>Pl.</i> <span dir=\"rtl\">כַּוִּוין</span>, <span dir=\"rtl\">כַּוַּויָּא</span>, <a href=\"#\" data-headword=\"כַּוָּוא\">כַּוָּותָא</a>, <a href=\"#\" data-headword=\"כְּלֵי\">כַּוֵּי</a> &amp;c. <span class=\"citation\">Targ. I Kings VI, 4</span>. <span class=\"citation\">Targ. Y. II, Gen. XLIX, 22</span>. <span class=\"citation\">Targ. Cant. II, 9</span>.—<span class=\"citation\">B. Bath. 6ᵃ</span> <span dir=\"rtl\">בֵּי כַּוֵּי לא וכ׳</span> apertures in the party wall (for beam-rests) are no evidence of the neighbor’s share in the wall. <span class=\"citation\">Ib. 75ᵃ</span> <span dir=\"rtl\">כ׳ דבי זיקא</span> (Ms. O. <span dir=\"rtl\">כַּוֵּי זיקא</span>) apertures for the air (windows, contrad. to openings for doors).—<i>Hebr. pl.</i> <a href=\"#\" data-headword=\"כַּלִּין\">כַּוִּין</a>. <span class=\"citation\">Sifré Deut. 309</span> (play on <span dir=\"rtl\">ויכוננך</span>, <span class=\"citation\">Deut. XXXII, 6</span>) <span dir=\"rtl\">עשאך כ׳ כ׳</span> he made thy body full of cavities (v. Pesik. Zutr. ed. Bub., Deut. p. 111); Yalk. ib. 942 <span dir=\"rtl\">כיון כיון</span> (corr. acc.).</div>","alt":["כַּוָּא","כַּוְּותָא","כַּוְּתָא"]},"12069":{"h":"כַּוָּואָה","r":"K00207","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּוָאָה\">כְּוָאָה</a></div>","alt":[]},"12070":{"h":"כָּוָוה","r":"K00208","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כוי\">כוי</a></div>","alt":[]},"12071":{"h":"כַּוָּוי","r":"K00209","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כַּוָּוא\">כַּוָּוא</a>) <i>aperture</i>. <span class=\"citation\">Yalk. Jer. 276</span> (ref. to <a href=\"#\" data-headword=\"כַּוָּנִים\">כַּוָּנִים</a>, <span class=\"citation\">Jer. VII, 18</span>) <span dir=\"rtl\">היה חופר בתוך ביתו כ׳ קטנה והיו מכוונים וכ׳</span> used to make in his house a small aperture which was directed exactly towards the east, so that when the morning star rose, he might rise and worship it; <span class=\"citation\">Pesik. R. s. 31</span> <span dir=\"rtl\">קטה כמין ניכו׳</span> (corr. acc.); v. <a href=\"#\" data-headword=\"כּוֹכֶבֶת\">כּוֹכֶבֶת</a>.</div>","alt":[]},"12072":{"h":"*כַּוָּון","r":"K00210","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>exactly determined place</i> (for worship).—Pl. <a href=\"#\" data-headword=\"כַּוָּנִים\">כַּוָּונִים</a>. <span class=\"citation\">Pesik. R. s. 31</span>; <span class=\"citation\">Yalk. Jer. 276</span> (ref. to <span class=\"citation\">Jer. VII, 18</span>) <span dir=\"rtl\">מהו כ׳</span> what is <i>kavvanim?</i>, v. <a href=\"#\" data-headword=\"כַּוָּוי\">preced.</a> [In b. h. our w. seems to mean certain <i>cakes</i> placed due east.]</div>","alt":[]},"12073":{"h":"כִּוּוּן","r":"K00211","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כּוּן\">כּוּן</a>, cmp. <a href=\"#\" data-headword=\"כַּוָּנָה\">כַּוָּנָה</a>) <i>exact selection of place</i>. <span class=\"citation\">Gen. R. s. 15</span>, beg. <span dir=\"rtl\">צריכה כ׳</span> (planting) requires exact selection; <span class=\"citation\">ib.</span> <span dir=\"rtl\">צריך לכַוֵּון את רוחותיה</span> one must determine its position with reference to the cardinal points.</div>","alt":[]},"12074":{"h":"כֵּוָונָא","r":"K00212","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֵּיוָנָא I\">כֵּיוָנָא</a></div>","alt":[]},"12075":{"h":"כַּוָּונָה","r":"K00213","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">כונ׳</span>.</div>","alt":["כַּוָּונוּתָא","כַּוַּונְתָּא"]},"12076":{"h":"כֵּוָונִיתָא","r":"K00214","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֵּיוָן\">כֵּיוָנ׳</a></div>","alt":["כֵּוַונְתָּא"]},"12077":{"h":"כְּוַוץ","r":"K00215","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּוֵץ\">כְּוץ</a></div>","alt":[]},"12078":{"h":"כַּוְורָא","r":"K00216","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כְּוֶורֶת\">כְּוֶורֶת</a>) [<i>basket, cauf</i>, cmp. <a href=\"#\" data-headword=\"נָחִיל\">נָחִיל</a>,] <i>fish in the cauf</i>, in gen. <i>fish</i>. <span class=\"citation\">M. Kat. 11ᵃ</span> [read:] <span dir=\"rtl\">כ׳ טווייה באחוה וכ׳</span> (v. Rabb. D. S. a. l.) roast the fish with its brother (salt) &amp;c. <span class=\"citation\">Y. Sabb. VII, 10ᵃ</span> <span dir=\"rtl\">ההן דצייד כ׳</span> he who catches fish (on the Sabbath). <span class=\"citation\">Gitt. 36ᵃ</span>, a. e. <span dir=\"rtl\">צייר כ׳</span> drew the figure of a fish (in place of his signature); a. fr.—Pl. <span dir=\"rtl\">כַּיְורַיָּא</span>, <span dir=\"rtl\">כַּוְורֵי</span>, <span dir=\"rtl\">כַּוְי</span>. <span class=\"citation\">Targ. Y. Gen. I, 26</span>, a. fr. (only in Targ. Y.).—[<span class=\"citation\">Targ. Job. XLI, 26</span> <span dir=\"rtl\">בני כוורי</span>, Ms. <span dir=\"rtl\">כונדי</span>, Regia <span dir=\"rtl\">טורי</span>; h. text <span dir=\"rtl\">בני שחץ</span>.]—<span class=\"citation\">Taan. 24ᵃ</span> פירא דכ׳ <i>the fish-pond</i>. <span class=\"citation\">Kidd. 72ᵃ</span>.—M. Kat. l. c. <span dir=\"rtl\">לבאי כ׳</span> (Var. <span dir=\"rtl\">כַּוָּארֵי</span>), v. <a href=\"#\" data-headword=\"*בְּדִיתָא\">בְּדִיתָא</a>; a. e.</div>","alt":["כַּוְרָא"]},"12079":{"h":"כוורדקי","r":"K00217","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַכְוַנְגַּר\">אַכְוַנְגַּר</a></div>","alt":[]},"12080":{"h":"כַּוָּורִיתָא","r":"K00218","html":"<div class=\"sense\"> f<i>.</i> <i> honey-comb</i>, v. <a href=\"#\" data-headword=\"כַּבְרִיתָא I\"><span dir=\"rtl\">כַּבְרִיתָא</span> I</a>.</div>","alt":[]},"12081":{"h":"כְּוַורְנָק","r":"K00219","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַכְוַרְנְקָא\">אַכְוַרְנְקָא</a></div>","alt":["כְּוַורְנְקִי"]},"12082":{"h":"כְּוֶורֶת","r":"K00220","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כּוֹר\">כור</a>, cmp. <a href=\"#\" data-headword=\"כְּבָרָה\">כְּבָרָה</a>; v. Fl. to Levy Targ. Dict. I, p. 428ᵃ) </div><div class=\"sense\"><b>1)</b> <i>a large round vessel, receptacle</i> of grain, water &amp;c.; <span dir=\"rtl\">כ׳ דבורים</span> <i>bee-hive</i>. <span class=\"citation\">Num. R. s. 1</span>; Tanḥ. B’midb. 2, v. <a href=\"#\" data-headword=\"כַּדּוֹרִית\">כַּדּוֹרֶת</a>. <span class=\"citation\">Shebi. X, 7</span>. <span class=\"citation\">Kel. XV, 1</span> <span dir=\"rtl\">כ׳ הקש וכ׳ הקנים</span> a receptacle made of straw or reeds. <span class=\"citation\">Ib. VIII, 1</span>; <span class=\"citation\">Tosef. Kel. B. Kam. VI, 3</span> <span dir=\"rtl\">כ׳ פחותה וכ׳</span> a defective <i>k’vereth</i> which was repaired with a stuffing of straw. <span class=\"citation\">Ib. V, 8</span> [read:] <span dir=\"rtl\">כָּאוֶרֶת של מתכת וכ׳</span> (ed. Zuck. <a href=\"#\" data-headword=\"ניארת\">ניארת</a>, corr. acc.) a metal <i>k</i>. used in the household. <span class=\"citation\">Men. 95ᵃ</span> <span dir=\"rtl\">כמין כ׳</span> a kind of bee-hive (honeycombed plate in the stove); <span class=\"citation\">Tosef. ib. XI, 2</span> <a href=\"#\" data-headword=\"מזרת\">מזרת</a>, <span dir=\"rtl\">מורת</span> (corr. acc.); a. e.—Pl. <span dir=\"rtl\">כְּוָורוֹת</span>. <span class=\"citation\">Tosef. Ohol. X, 5</span> <span dir=\"rtl\">שתי כ׳</span> (<span dir=\"rtl\">כוורת</span> ed. Zuck., Var. <span dir=\"rtl\">כוארת</span>, corr. acc.).</div><div class=\"sense\"><b>—2)</b>  the <i>ramifications of the vine, espalier, the widest extent of branches</i>. <span class=\"citation\">Tosef. Kil. III, 4</span>; Y. ib. V, 29ᵈ <span dir=\"rtl\">הכ׳ מְכוּוָּן והגוף וכ׳</span> (sub <a href=\"#\" data-headword=\"בֵּיתָא I\">בֵּית</a>) if the espalier is in a certain direction, but the body of the vine is not in the line. <span class=\"citation\">Y. Erub. III, 21ᵃ</span> top <span dir=\"rtl\">בשהיתה כְּוַרְתּוֹ ארבעה</span> when its ramifications had a circumference of four cubits; <span class=\"citation\">Y. Succ. II, 52ᵈ</span> bot. <a href=\"#\" data-headword=\"ככרתו\">ככרתו</a> (corr. acc. or <span dir=\"rtl\">כְּבַרְתּוֹ</span>). <span class=\"citation\">Y. Ber. I, 2ᶜ</span> bot., v. <a href=\"#\" data-headword=\"נוֹף I\"><span dir=\"rtl\">נוֹף</span> I</a>; a. e.—Midr. Sam. ch. XIII <span dir=\"rtl\">קוֹרָתוֹ של חרוב</span> (= <a href=\"#\" data-headword=\"כְּוָא\">כְּוַ׳</a>), v. next w.—Pl. m. <span dir=\"rtl\">כְּוָורָתִים</span>, <span dir=\"rtl\">כְּוָורָתִין</span>. <span class=\"citation\">Y. Kil. IV, 29ᵇ</span> top <span dir=\"rtl\">הכוור׳</span> R. S. to <span class=\"citation\">Kil. IV, 3</span> (ed. <a href=\"#\" data-headword=\"כָּֽרָתִים\">כָּֽרָתִים</a> contr., cmp. <a href=\"#\" data-headword=\"דָּֽרְבָן\">דָּֽרְבָן</a>). <span class=\"citation\">Ib. VI</span>, beg. 30ᵇ <span dir=\"rtl\">כרתין</span>. <span class=\"citation\">Ib. IV</span>, 29ᶜ <span dir=\"rtl\">כרתין</span>; <span class=\"citation\">ib. V</span>, 30ᵃ top <a href=\"#\" data-headword=\"כרתון\">כרתון</a> (corr. acc.).</div>","alt":[]},"12083":{"h":"כְּוַורְתָּא","r":"K00221","html":"<div class=\"sense\"><b>1)</b> <i>bee-hive</i>. <span class=\"citation\">Targ. Jer. V, 27</span> ככ׳ דמליא זיבורייתא Vers. in ed. Lag. (v. preface to Proph. XXXIV, 13) like a hive full of bees.</div><div class=\"sense\"><b>—2)</b> <i>ramification</i>. <span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">כ׳ דחרוביתא</span> the circumference of a carob-tree; <span class=\"citation\">Y. Sot. I, 17ᵇ</span> top ed. Amst. (ed. Krot. <a href=\"#\" data-headword=\"אוּרְתָּא\">אורתא</a>, corr. acc.); <span class=\"citation\">Y. Peah VII, 20ᵃ</span> bot. <span dir=\"rtl\">בירתא</span> (corr. acc.); (Midr. Sam. ch. XIII, v. <a href=\"#\" data-headword=\"כְּוֶורֶת\">preced.</a>).</div>","alt":["כַּוְורַת","כְּוַרְתָּא","(כּוֹרְתָא)"]},"12084":{"h":"כְּוָות","r":"K00222","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּוָת\">כְּוָת</a></div>","alt":[]},"12085":{"h":"כַּוְּותָא I","r":"K00223","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>window</i>, v. <a href=\"#\" data-headword=\"כַּוָּוא\">כַּוָּוא</a>.</div>","alt":[]},"12086":{"h":"כַּוְּותָא II","r":"K00224","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּוִי\">כְּוִי</a>) <i>searing, blister</i> from a burn. <span class=\"citation\">Snh. 84ᵇ</span> ed., v. <a href=\"#\" data-headword=\"*בּוּעֲתָא I\"><span dir=\"rtl\">בּוּעֲתָא</span> I</a>.</div>","alt":[]},"12087":{"h":"כּוּז","r":"K00225","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"כַּד II\"><span dir=\"rtl\">כַּד</span> II</a>) <i>an oil vessel</i>, used in the Temple. <span class=\"citation\">Tam. III, 6</span> <span dir=\"rtl\">והכ׳ דומה וכ׳</span> the <i>kuz</i> had the shape of a large wine cup. <span class=\"citation\">Ib. 9</span>.</div>","alt":[]},"12088":{"h":"כּוּזָא","r":"K00226","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, <i>wine pitcher, jug</i>. Targ. II Esth. II, 21.—<span class=\"citation\">Sabb. 77ᵇ</span> (playful etymology) <span dir=\"rtl\">כּוּזָה כָּזֶה</span> ed. (Rashi <a href=\"#\" data-headword=\"כּוּזָא\">כוזא</a>) it is named <i>kuza</i>—‘like this’ (give us to drink from). <span class=\"citation\">Ḥull. 107ᵃ</span> <span dir=\"rtl\">כ׳ בת רביעתא</span> a <i>Kuza</i> must contain one fourth of a Log. <span class=\"citation\">Sabb. 33ᵇ</span>. <span class=\"citation\">Taan. 20ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"אֲכוּזָא\">אֲכוּזָא</a>); a. fr.—<span class=\"citation\">Yeb. 70ᵃ</span>, v. <a href=\"#\" data-headword=\"כַּדָּא\">כַּדָּא</a>.</div>","alt":[]},"12089":{"h":"כּוֹזָב","r":"K00227","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוֹזְכָא\">next w.</a></div>","alt":[]},"12090":{"h":"כּוֹזְכָא","r":"K00228","html":"<div class=\"sense\"><b>1)</b>  <span dir=\"rtl\">(<a href=\"#\" data-headword=\"בַּר\">בַּר</a>) <span dir=\"rtl\">בֶּן כ׳</span></span> pr. n. m. <i>Ben</i>-(<i>Bar-</i>) <i>Koz’ba</i>, name of the leader of the Jewish uprising against Hadrian, usually named <span dir=\"rtl\">בר כוכבא</span> <i>Bar-Kokhba</i>. <span class=\"citation\">Y. Taan. IV, 68ᵈ</span> bot. <span dir=\"rtl\">עקיבא … דרך כוכב … דרך כ׳</span> Akiba, my teacher, preached, ‘A star goes forth from Jacob’ (<span class=\"citation\">Num. XXIV, 17</span>) Koz’ba went forth; <span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">א&quot;ת כוכב אלא כּוֹזָב</span> read not <i>Kokhab</i> but <i>Kozab</i>. Y. Taan. l. c. <span dir=\"rtl\"><a href=\"#\" data-headword=\"בֵּן\">בן</a> (<span dir=\"rtl\">בר</span>) <a href=\"#\" data-headword=\"כּוֹזְכָא\">כוזבה</a></span>. Ib. 69ᵃ top <span dir=\"rtl\">כזובה</span> (corr. acc.). Lam. R. l. c. <span dir=\"rtl\"><a href=\"#\" data-headword=\"בֵּן\">בן</a> (<span dir=\"rtl\">בר</span>) <span dir=\"rtl\">כוזיבא</span></span>; <span class=\"citation\">Yalk. Deut. 946</span>.—Denom. <span dir=\"rtl\">כּוֹזְבִי</span>; f. <span dir=\"rtl\">כּוֹזְבִית</span>, pl. <span dir=\"rtl\">כּוֹזְבִיּוֹת</span>. <span class=\"citation\">Tosef. Maas. Sh. I, 6</span>; <span class=\"citation\">B. Kam. 97ᵇ</span> <span dir=\"rtl\">מעות כ׳</span> coins issued by Bar-K.—</div><div class=\"sense\"><b>*2)</b>  <a href=\"#\" data-headword=\"כֵּיפֵי\">בֵּית כ׳</a> pr. n. <i>Beth-Koz’ba</i>, name of a valley. Tanḥ. Ḥuck. 1; (ed. Bub. ib. <span dir=\"rtl\">טופח</span>; <span class=\"citation\">Num. R. s. 18</span> <a href=\"#\" data-headword=\"תּוֹפֶת\">תופת</a>; <span class=\"citation\">Gen. R. s. 10</span> <span dir=\"rtl\">בי טרפא</span>; <span class=\"citation\">Lev. R. s. 22</span> <span dir=\"rtl\">בית שופרי</span>; <span class=\"citation\">Koh. R. to V, 8</span> <a href=\"#\" data-headword=\"*טוֹפֶת\">טופת</a>; <span class=\"citation\">Yalk. Koh. 972</span> <span dir=\"rtl\">נטופא</span>).</div>","alt":["כּוֹזְבָה","כּוֹזִיבָא"]},"12091":{"h":"כּוּזָה","r":"K00229","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּזָא\">כּוּזָא</a></div>","alt":[]},"12092":{"h":"כּוֹזִיבָא","r":"K00230","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוֹזְכָא\">כּוֹזְבָא</a></div>","alt":[]},"12093":{"h":"כּוּזִית","r":"K00231","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Kuzith</i>, surname of one R. Samuel. <span class=\"citation\">Gen. R. s. 23</span>; s. 51 Ar. (absent in eds.).</div>","alt":[]},"12094":{"h":"כוזני","r":"K00232","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּזַנְתָּא\">next w.</a></div>","alt":[]},"12095":{"h":"כּוּזַנְתָּא","r":"K00233","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"כּוּזָא\">כּוּזָא</a>, <i>jug</i>. <span class=\"citation\">Ab. Zar. 71ᵇ</span>; <span class=\"citation\">M. Kat. 12ᵃ</span> quot. in Rashi to Ab. Zar. l. c. (ed. <a href=\"#\" data-headword=\"כּוּזְתָא\">כּוּזְתָא</a>, Ms. M. <a href=\"#\" data-headword=\"כּוּזָא\">כּוּזָא</a>). <span class=\"citation\">Sabb. 139ᵇ</span> אפומא דכוזנתא Rashi Ms. (ed. <span dir=\"rtl\">בפומיה דכוזני דחביתא</span>; Ms. O. <span dir=\"rtl\">בפומא דכוזתא</span>, v. Rabb. D. S. a. l. note) on the mouth of the jug (used for taking wine out of the larger vessel).</div>","alt":[]},"12096":{"h":"כּוּזְתָא","r":"K00234","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּזַנְתָּא\">preced.</a></div>","alt":[]},"12097":{"h":"כּוּחַ","r":"K00235","html":"<div class=\"sense\"><i>to cough</i>, v. <a href=\"#\" data-headword=\"כָּחַח\">כָּחַח</a>.</div>","alt":[]},"12098":{"h":"כּוֹחַ","r":"K00236","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֹּחַ\">כֹּחַ</a>, <a href=\"#\" data-headword=\"כֹּחַ ²\"><a href=\"#\" data-headword=\"כֹּחַ ²\">כֹּחָא</a>.</a></div>","alt":["כּוֹחָא"]},"12099":{"h":"כּוֹחִילְנָא","r":"K00237","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כּוֹחָל\">next w.</a>) <i>koḥilna</i>, name of a bird. <span class=\"citation\">Ḥull. 62ᵇ</span> (Ar. <a href=\"#\" data-headword=\"גְּחִילְנָא\">גְּחִילְנָא</a>).</div>","alt":[]},"12100":{"h":"כּוֹחָל","r":"K00238","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"גֶּחָל\">גחל</a>, v. Lane Customs, 1837, p. 51 sq.) <i>ko</i> <i>ḥl, a powder used for painting the eye-lids, stibium</i>. <span class=\"citation\">Sabb. VIII, 3</span> (<span class=\"citation\">78ᵇ</span>) <a href=\"#\" data-headword=\"כֹּחַ ²\">כּוֹ׳</a> Ar. (ed. <span dir=\"rtl\">כְּח׳</span>); Y. ib. 11ᵇ bot. <span dir=\"rtl\">כו׳</span>. <span class=\"citation\">Ḥull. 88ᵇ</span> <span dir=\"rtl\">השחור והכ׳</span> powdered coal and stibium. <span class=\"citation\">Snh. 14ᵃ</span>; <span class=\"citation\">Keth. 17ᵃ</span> (in a song) <span dir=\"rtl\">לא כֹּחָל</span> here is no paint (no showiness). [<span class=\"citation\">Tosef. Nidd. VI, 4</span> <a href=\"#\" data-headword=\"כּוֹחָל\">כוחל</a>, read: <a href=\"#\" data-headword=\"בּוֹחַל\">בּוֹחַל</a>.]</div>","alt":["(כְּחוֹל)"]},"12101":{"h":"כּוֹחֲלָא","r":"K00239","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"כּוֹחָל\">same</a>. Targ. II Esth. I, 3 (2); <span class=\"citation\">Ber. 18ᵇ</span>, v. <a href=\"#\" data-headword=\"גּוּבְתָא\">גּוּבְתָא</a>.—<span class=\"citation\">Ḥull. 47ᵇ</span> <a href=\"#\" data-headword=\"כּוֹכָב ²\">ככ׳</a> as black as stibium. <span class=\"citation\">Gitt. 69ᵃ</span> top <span dir=\"rtl\">תרתי מנתא כ׳ וכ׳</span></div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">אבנא דכ׳</span> a species of <i>black marble</i>(b. h. , v. Sm. Ant. s. v. Carbunculus). <span class=\"citation\">Kidd. 12ᵃ</span> <span dir=\"rtl\">אקדיש בא׳ דכ׳</span> betrothed a woman by giving her a piece of black marble (of little value). <span class=\"citation\">B. Bath. 4ᵃ</span>; <span class=\"citation\">Succ. 51ᵇ</span>, v. <a href=\"#\" data-headword=\"מַרְמָרָא\">מַרְמָרָא</a>.</div>","alt":[]},"12102":{"h":"כּוֹחֲלִי","r":"K00240","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוֹחֲלִית\">כּוֹחֲלִית</a></div>","alt":[]},"12103":{"h":"כּוֹחֲלִין","r":"K00241","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (used as sing.; v. <a href=\"#\" data-headword=\"כּוֹחֲלִי\">preced.</a> wds.; cmp. b. h. <a href=\"#\" data-headword=\"נֹפֶךְ\">נֹפֶךְ</a> a. <a href=\"#\" data-headword=\"פּוּךְ\">פּוּךְ</a>) <i>carbuncle</i>, name of a jewel. <span class=\"citation\">Ex. R. s. 38</span>, end (corresp. to <span dir=\"rtl\">לשם</span>, <span class=\"citation\">Ex. XXVIII, 19</span>). [V., however, <a href=\"#\" data-headword=\"כַּחֲלֵי\">כַּחֲלֵי</a>.]</div>","alt":[]},"12104":{"h":"כּוֹחֲלִית","r":"K00242","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Koḥălith</i>, a district conquered by John Hyrcan, [perh. = <span dir=\"rtl\">לפַח</span>, <span class=\"citation\">Num. XXI, 30</span>, cmp. <a href=\"#\" data-headword=\"כּוֹחֲלִין\">preced.</a> wds. a. <a href=\"#\" data-headword=\"פֶּחָם\">פֶּחָם</a>]. <span class=\"citation\">Kidd. 66ᵃ</span> כ׳ שבמדבר K. in the desert.—<span dir=\"rtl\">אזוב כ׳</span> a species of <i>hyssop</i> named after that district. <span class=\"citation\">Neg. XIV, 6</span> <a href=\"#\" data-headword=\"כּוֹחֲלִי\">כּוֹחֲלִי</a>; <span class=\"citation\">Succ. 13ᵃ</span> לית … Ms. M. (ed. … <a href=\"#\" data-headword=\"לֵי\">לי</a>). <span class=\"citation\">Par. XI, 7</span>; <span class=\"citation\">Ḥull. 62ᵇ</span>; <span class=\"citation\">Sifré Num. 129</span>.</div>","alt":[]},"12105":{"h":"כוי","r":"K00243","html":"<div class=\"sense\"> [<i>to cause discoloring</i>,] <i>to sear, cauterize; to scald</i>. <span class=\"citation\">B. Kam. VIII, 1</span> <span dir=\"rtl\">כְּוָאוֹ בשפוד וכ׳</span> if a person hurt another with a hot spit &amp;c.; Y. ib. 6ᵃ; 6ᵇ (Mish. a. Ib.) <span dir=\"rtl\">כְּוָייוֹ</span>, <span dir=\"rtl\">כְּוָויוֹ</span>; a. e.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"כַּוָּוי\">כָּווּי</a> <i>burn-marked, flame-spotted</i>. <span class=\"citation\">Lev. R. s. 15</span> … <span dir=\"rtl\">חמורה ונכוית ויצא בנה כ׳</span> a she-ass was sick and was cauterized, and her child was born with a flame-mark; (<span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">מרושם</span>).</div><div class=\"sense\"><b>Hif. הִכְוָה</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"כּוֹחֲלִית\">same</a>. <span class=\"citation\">Neg. VII, 4</span> <span dir=\"rtl\">וה׳ את המחיה</span> if one cauterized the cicatrizing spot.</div></div><div class=\"sense\"><b>Pi. כִּייָּה</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"כּוֹחֲלִית\">same</a>. Num. R. l. c. <span dir=\"rtl\">הוליכה … וכי׳ אותה</span> he took her to the veterinary surgeon, and he cauterized her.</div></div><div class=\"sense\"><b>Nif. נִכְוֶה</b> <div class=\"sense\"><i>to be burnt; to be cauterized</i>. <span class=\"citation\">B. Bath. 75ᵃ</span> כל אחד וא׳ נִכְוָה חופתו מחופת וכ׳ Ms. M. (v. Rabb. D. S. a. l. note) each man’s tent will be stained by fire from his neighbor’s tent. Lev. R. l. c. <span dir=\"rtl\">נִכְוֵית</span>, v. supra. Num. R. l. c. <span dir=\"rtl\">ממה שנִכְוֵת אמו</span> because his mother had been cauterized. <span class=\"citation\">Sabb. 30ᵇ</span>; <span class=\"citation\">Pes. 117ᵃ</span> <span dir=\"rtl\">תִּכָּוֶינָה</span> (his lips) be burnt. <span class=\"citation\">Tosef. Ḥag. II, 6</span> <span dir=\"rtl\">היטה לכאן וניכ׳ בארו … ונכווה בשלג</span> if he deviates this way, he will be burnt by the fire, if that way, he will be frost-bitten; (<span class=\"citation\">Ab. d’R. N. ch. XXVIII</span> <span dir=\"rtl\">לוקה בצינה</span>). <span class=\"citation\">Tosef. Ḥull. III, 6</span> <span dir=\"rtl\">יכולה לִיכָּווֹת וכ׳</span> she may be cauterized and recover.—Y. Sabb. III, 6ᵇ top <span dir=\"rtl\">והיא נכוית</span> and it (the hand) is scalded (v. <a href=\"#\" data-headword=\"סָלַד\">סָלַד</a>). Y. Ber. II, 5ᵇ bot. <span dir=\"rtl\">כמדומה … שאתם נִיכְוִין בפושרין וכ׳</span> I thought you would be scalded with tepid water (understand a slight hint), but you do not feel even hot water (distinct intimation); Bab. <span class=\"citation\">Ber. 16ᵇ</span>.—Y. Nidd. III, 50ᵈ [read:] <span dir=\"rtl\">רישיה דרישך יִכָּוֶה בפושרין ואתה לא תִיכָּוֶה אפי׳ ברותחין</span> thy head’s head (thy teacher’s teacher) feels tepid water, but thou &amp;c., i.e. you must not claim superiority to your predecessors (cmp. <span class=\"citation\">Sabb. 55ᵃ</span>); a. fr.</div></div>","alt":["כָּוָה","כָּוָא"]},"12106":{"h":"כְּוִי","r":"K00244","html":"<div class=\"sense\">Y. Bets. II, 61ᶜ top; Y. Maas. Sh. V, 56ᶜ top, a. e. <span dir=\"rtl\">(<span dir=\"rtl\">כָּוְיָה</span>) <a href=\"#\" data-headword=\"כַּוְרָא\">כַּוְיָא</a></span>, v. <a href=\"#\" data-headword=\"גּוּמְרָא\">גּוּמְרָא</a></div><div class=\"sense\"><b>Ithpa. אִתְכַּוִּי</b> <div class=\"sense\"><i>to be burnt</i>. <span class=\"citation\">Targ. Prov. VI, 28</span> מִתְכַּוְיָן Ms. (ed. <span dir=\"rtl\">כְּוִין …</span>, corr. acc.).</div></div>","alt":["כְּוָא"]},"12107":{"h":"כּוֹי","r":"K00245","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Koy</i>, (prob.) a kind of <i>bearded dear</i> or <i>antelope</i> (τραγέλαφος). [The rabbis leave it undecided whether K. belongs to the genus of cattle (<a href=\"#\" data-headword=\"בְּהֵמָה\">בְּהֵמָה</a>) or beasts of chase <a href=\"#\" data-headword=\"חַיָּה I\">(חַיָּה</a>).] <span class=\"citation\">Y. Bicc. II, end, 65ᵇ</span>, v. <a href=\"#\" data-headword=\"עִיזָּה\">עִיזָּה</a>. <span class=\"citation\">Ḥull. 80ᵃ</span> (various opinions). <span class=\"citation\">Tosef. ib. VI</span> (<span class=\"citation\">V), 1</span>. <span class=\"citation\">Tosef. Bekh. II, 9</span>; a. fr.</div>","alt":[]},"12108":{"h":"כְּוֵיץ","r":"K00246","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּוֵץ\">כְּוֵץ</a></div>","alt":[]},"12109":{"h":"כּוּךְ","r":"K00247","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">כוכו</span>, v. <a href=\"#\" data-headword=\"כַּוָּוא\">כַּוָּוא</a>) <i>cavity, cave</i>, esp. <i>sepulchral chamber</i>. [<span class=\"citation\">Taan. 25ᵇ</span> כ׳ המחרישה R. Gersh. (Ms. M. <span dir=\"rtl\">כון</span>, v. Rabb. D. S. a. l. note, ed. <a href=\"#\" data-headword=\"בֶּרֶךְ\">בֶּרֶךְ</a>) the cavity made by the plough.]—Y. B. Bath. III, beg. 13ᵈ <span dir=\"rtl\">חמוכר … בכ׳ חזקה לכל הכ׳</span> if one sells a burial place (<span dir=\"rtl\">קבר</span>) to his neighbor, as soon as the latter has buried one dead in the chamber, he has the possession of the entire chamber; a. e.—Pl. <span dir=\"rtl\">כּוּכִין</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">קבר … בג׳ כ׳ וכ׳</span> when he buried three dead in three different chambers &amp;c. <span class=\"citation\">Tosef. Ohol. XVII, 11</span> [read:] … <span dir=\"rtl\">שדה … בתוכה היא כשדה כ׳ ואיזו היא שדה כ׳ כל חכ׳ לצדדין</span> a field in which a grave (known to have been there) has disappeared, is like a field of sepulchral chambers. And what is a field &amp;c.? Where you dig out (a square) in the ground, and make chambers in the walls. <span class=\"citation\">B. Bath. VI, 8</span>; a. e.</div>","alt":[]},"12110":{"h":"כּוּךְ ²","r":"K00248","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"כּוּךְ\">same</a>. <span class=\"citation\">Targ. Job XXX, 2</span>; <span class=\"citation\">ib. V, 26</span> (h. text <span dir=\"rtl\">כלח</span>).).</div><div class=\"sense\"><b>—2)</b> <i>an improvised subterranean dwelling</i>. <span class=\"citation\">Taan. 22ᵃ</span> ככ׳ דציידי Rashi (ed. <span dir=\"rtl\">ככוּכֵי</span>, pl., Ar. s. v. <a href=\"#\" data-headword=\"כְּכָי\">ככי</a>: <span dir=\"rtl\">לא נצרכה אלא לבי כ׳ דאגמא</span>) like the hunters’ cave. <span class=\"citation\">Gitt. 68ᵃ</span> bot. <span dir=\"rtl\">מטא גבי כ׳ דההיא וכ׳</span> Ar. (ed. <a href=\"#\" data-headword=\"כּוּבָּא I\">כובא</a>, corr. acc.) he came to the hut of a certain widow. [<span class=\"citation\">Ber. 37ᵇ</span> כ׳ דארעא Ar., v. <a href=\"#\" data-headword=\"כּוּבָּא III\"><span dir=\"rtl\">כּוּבָּא</span> III</a>.]</div>","alt":["כּוֹכָא"]},"12111":{"h":"כּוֹכָב","r":"K00249","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.; = <a href=\"#\" data-headword=\"כַּבְכָּב\">כבכב</a>, v. <a href=\"#\" data-headword=\"*כְּבַב\">כבב</a>) [<i>rounded, globe</i>,] <i>star, planet</i>. <span class=\"citation\">Y. Ber. I, 2ᵇ</span> <span dir=\"rtl\">כ׳ אחד ודאי יום</span> as long as one star only is visible, it is surely day-time. <span class=\"citation\">Hor. 10ᵃ</span> כ׳ אחד יש ועולה וכ׳ Ms. M. (v. Rabb. D. S. a. l. note) there is a certain star (comet) which appears once in seventy years. <span class=\"citation\">Gen. R. s. 100</span> <span dir=\"rtl\">עשרה כוכבים בקשו לאבד כ׳ אחד</span> ten stars (sons of Jacob) desired to destroy one star (Joseph); a. fr.—Pl. <span dir=\"rtl\">כּוֹכָבִים</span>, <a href=\"#\" data-headword=\"כּוֹכָב ²\">כֹּכָ׳</a>. Ib.—<span class=\"citation\">Ber. 10ᵃ</span> <span dir=\"rtl\">כ׳ ומזלות</span> stars and planets; a. fr.—<span dir=\"rtl\">עובד כ׳</span>, <span dir=\"rtl\">עובד כ׳ ומזלות</span> (abbr. <span dir=\"rtl\">עו&quot;כ</span>, <span dir=\"rtl\">עכו&quot;ם</span>), <span dir=\"rtl\">עבודת כ׳</span>, v. <a href=\"#\" data-headword=\"עָבַד\">עָבַד</a>, <a href=\"#\" data-headword=\"עֲבוֹדָה\">עֲבוֹדָה</a>. <span class=\"citation\">Succ. 22ᵇ</span>; Y. ib. II, beg. 22ᵈ <span dir=\"rtl\">כּוֹכְבֵי חמה</span> scintillations of the sun as seen through the covering of the festive booth. <span class=\"citation\">Yalk. Esth. 1053</span> <span dir=\"rtl\">כ׳ חנגה</span>, v. <a href=\"#\" data-headword=\"כּוֹכָב ²\">next w.</a></div>","alt":["כֹּכָב"]},"12112":{"h":"כּוֹכָב ²","r":"K00250","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Am. V, 26</span>.—<span class=\"citation\">Y. Maas. Sh. IV, 55ᵇ</span> bot.; a. fr.—Esp. <i>the planet Mercury</i>. <span class=\"citation\">Sabb. 156ᵃ</span> <span dir=\"rtl\">האי מאן דבכ׳</span> he who was born under Mercury.—<span dir=\"rtl\">כ׳ נוגה</span>, <span dir=\"rtl\">כ׳ נוגהא</span> <i>Venus</i>. Targ. II Esth. II, 7 (v. <a href=\"#\" data-headword=\"אִיסְתִּירָא\">אִיסְתִּירָא</a>); <span class=\"citation\">Yalk. Esth. 1053</span> (hebr.), v. <a href=\"#\" data-headword=\"אִסְתְּהַר\">אִסְתְּהַר</a>.—Sabb. l. c.; a. e.—כ׳ רשביט <i>comet</i>. <span class=\"citation\">Ber. 58ᵇ</span>.—Pl. <span dir=\"rtl\">כּוֹכְבַיָּא</span>, <span dir=\"rtl\">כּוֹכְבֵי</span>, <a href=\"#\" data-headword=\"כּוֹכָב ²\">כֹּכְ׳</a>. <span class=\"citation\">Targ. Gen. I, 16</span>; a. fr.—<span class=\"citation\">Snh. 39ᵃ</span> מצינא למימני כ׳ I can count the stars. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מני לי כ׳</span> the number of the stars is known to me. <span class=\"citation\">Ab. Zar. 29ᵃ</span> <span dir=\"rtl\">דתלי לה בי כ׳</span> which he suspended under the stars (in open air over night); a. fr.—[<span class=\"citation\">B. Mets. 86ᵃ</span> כֹּכְבִין דנרדא Ar. balls of nardus, ed. <span dir=\"rtl\">כִּכְּרִין</span>.]</div>","alt":["כּוֹכְבָא","כֹּכ׳"]},"12113":{"h":"כּוֹכְבִיתָא","r":"K00251","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>a little globe</i>, v. <a href=\"#\" data-headword=\"*כּוּבִּיתָא\">כּוּבִּיתָא</a>.</div>","alt":[]},"12114":{"h":"כּוֹכֶבֶת","r":"K00252","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כּוֹכְבִיתָא\">preced.</a> wds.) <i>the planet Venus, morning star, evening star</i>. <span class=\"citation\">Yalk. Jer. 276</span> (ref. to <span class=\"citation\">Jer. VII, 18</span>) <span dir=\"rtl\">שהיו עובדים למלכת השמים זו היא חכ׳</span> (not <span dir=\"rtl\">מלאכת</span>) they worshipped the queen of the heavens, that is Venus; <span class=\"citation\">Pesik. R. s. 31</span> <span dir=\"rtl\">הכוכבים</span> (corr. acc.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">היו בנו ירושלם עובדים לכ׳ וכ׳</span> (not <span dir=\"rtl\">לכוכבים</span>) the Jerusalemites worshipped Venus openly &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">שכשתעלה הב׳</span> (not <span dir=\"rtl\">הכוכבים</span>), v. <a href=\"#\" data-headword=\"כַּוָּוי\">כַּוָּוי</a>.</div>","alt":[]},"12115":{"h":"כּוֹכַבְתָּא","r":"K00253","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Jer. VII, 18</span>, a. e. <span dir=\"rtl\">כּוֹכְבַת שמיא</span>, v. preced.—<span class=\"citation\">Y. Ber. I, 2ᵇ</span> <span dir=\"rtl\">ובלחוד … בר מן הדא כ׳</span> provided three stars are seen besides the evening star.—Ib.ᶜ <span dir=\"rtl\">מאן דאמר כ׳ וכ׳</span> he who says <i>ăyalta d’shaḥra</i> is the morning star, is mistaken; <span class=\"citation\">Y. Yoma III, beg. 40ᵇ</span>; <span class=\"citation\">Gen. R. s. 50</span> <span dir=\"rtl\">כ׳ דצפרא</span>.</div>","alt":[]},"12116":{"h":"*כּוּכְיָא","r":"K00254","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"כְּכָי\">כְּכָי</a>) <i>spiderweb</i>, v. <a href=\"#\" data-headword=\"*בּוּכְיָא\">בּוּכְיָא</a>.</div>","alt":[]},"12117":{"h":"כוכיתא","r":"K00255","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*כּוּבִּיתָא\">כּוּבִּיתָא</a></div>","alt":[]},"12118":{"h":"כּוֹכְלִיאָר","r":"K00256","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cochlear) [<i>a kind of spoon pointed on one end for drawing snails out of their shells</i>,] <i>a pin of the shape of a cochlear</i>. <span class=\"citation\">Sabb. VI, 3</span> כוכלייר Y. ed., Ms. O. <a href=\"#\" data-headword=\"כּוֹכְלִיאָר\">כוכליאר</a> (Mish. a. Bab. ed. 62ᵃ <a href=\"#\" data-headword=\"כוליאר\">כוליאר</a>, Ms. M. in Ib. <a href=\"#\" data-headword=\"כובליאר\">כובליאר</a>, corr. acc., v. Rabb. D. S. a. l. notes 20 a. 70); expl. ib. 62ᵃ <a href=\"#\" data-headword=\"מַכְבַּנְתָּא\">מַכְבַּנְתָּא</a>. V. <a href=\"#\" data-headword=\"כּוֹכְלִיאָס\">next w.</a></div>","alt":["כּוֹכְלְיָיר"]},"12119":{"h":"כּוֹכְלִיאָס","r":"K00257","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κοχλίας, cochlea) <i>any thing spiral, a spiral stair-case, screw</i> &amp;c. (v. Gr. a. Lat. Dict. s. v.). <span class=\"citation\">Tosef. Succ. IV, 16</span> <span dir=\"rtl\">מקיפין ועומדין כקבולין</span> ed. Zuck. (Var. <span dir=\"rtl\">בכולייס</span>, <span dir=\"rtl\">ככולייר</span>, read <span dir=\"rtl\">בכוכלייס</span>) stood around in a spiral figure; <span class=\"citation\">Tosef. Yoma I, 10</span> <span dir=\"rtl\">בקבילין</span> ed. Zuck. (Var. <span dir=\"rtl\">בכלאים</span>, <span dir=\"rtl\">ככוליור</span>); <span class=\"citation\">Yoma 25ᵃ</span> <span dir=\"rtl\">כמין בכוליאר</span> (Ms. M. <span dir=\"rtl\">כולייר</span>, O. a. L. <span dir=\"rtl\">ככולייר</span>, v. Rabb. D. S. a. l. note). <span class=\"citation\">Y. Shek. VII, beg. 50ᶜ</span> <span dir=\"rtl\">כמין כובלין היו עשויין</span> (corr. acc.) the boxes in the Temple for contributions were put up so as to form a spiral figure; (Bab. ed. <a href=\"#\" data-headword=\"קובליים\">קובליים</a>, <span dir=\"rtl\">בוכלייאר</span>, <span dir=\"rtl\">כובליי׳</span>, corr. acc.).</div>","alt":["כּוֹכְלְיָיס","קוֹכְ׳"]},"12120":{"h":"*כּוֹכֶלֶת","r":"K00258","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <span dir=\"rtl\">כלכלת</span>, cmp. <a href=\"#\" data-headword=\"גּוֹגַלְתָּא\">גּוֹגַלְתָּא</a>; <a href=\"#\" data-headword=\"כִּלְכֵּל\">כִּלְכֵּל</a>) [<i>refreshing bottle</i>,] <i>a charm containing a perfume</i>. <span class=\"citation\">Sabb. VI, 3</span>. Ib. v. 62ᵃ, <a href=\"#\" data-headword=\"חוּמַרְתָּא\">חוּמַרְתָּא</a>; [Ed. a several Mss. read: (<a href=\"#\" data-headword=\"כָּבַל\">כָּבַל</a>) <a href=\"#\" data-headword=\"כּוֹבֶלֶת\">כּוֹבֶלֶת</a> <i>chain</i>, v. Rabb. D. S. a. l., a. Koh. Ar. Compl. s. v.]; Tosef. ib. IV (V), 11.</div>","alt":[]},"12121":{"h":"כּוּל","r":"K00259","html":"<div class=\"sense\"> (b. h.) [<i>to enclose</i>,] <i>to measure.</i> <span class=\"citation\">Ter. X, 8</span> וכָל גרב Ms. (ed. <span dir=\"rtl\">כל</span>), v. <a href=\"#\" data-headword=\"גָּרָב I\"><span dir=\"rtl\">גָּרָב</span> I</a>.—</div><div class=\"sense\"><b>Pilp. כִּלְכֵּל</b> <div class=\"sense\"> q. v.</div></div>","alt":[]},"12122":{"h":"כּוּל ²","r":"K00260","html":"<div class=\"sense\"> Perf. <a href=\"#\" data-headword=\"כָּל\">כָּל</a>; part. <a href=\"#\" data-headword=\"כָּאִיל\">כָּאֵיל</a>, <a href=\"#\" data-headword=\"כָּיִיל\">כָּיֵיל</a>. <span class=\"citation\">Targ. O. Ex. XVI, 18</span> (Y. <span dir=\"rtl\">אָכִילוּ</span> <i>Af</i>.). <span class=\"citation\">Targ. Ruth. III, 15</span>. <span class=\"citation\">Targ. Is. XXVII, 8</span>.—<span class=\"citation\">Men. 53ᵇ</span> <span dir=\"rtl\">כי קא כייל וכ׳</span> when he measures, he measures by &amp;c. <span class=\"citation\">Ab. Zar. 71ᵇ</span> <span dir=\"rtl\">אק כ׳ ודמי וכ׳</span> he measures and pours (the wine) into &amp;c. <span class=\"citation\">Ned. 51ᵃ</span>, v. <a href=\"#\" data-headword=\"אֲכַל II\"><span dir=\"rtl\">אֲכַל</span> II</a>.—<span class=\"citation\">Ḥull. 12ᵃ</span>, a. e. <span dir=\"rtl\">לכי תֵיכוּל עלה כורא דמילחא</span> (I will tell you,) if you will measure out for it a <i>kor</i> of salt (a jesting remark). <span class=\"citation\">Kidd. 79ᵇ</span> <span dir=\"rtl\">כולי עלמא כַּיְילֵי ליה וכ׳</span> to all the world (wisdom) has been measured in a small <i>kab</i>, and to this scholar in a large <i>kab</i>, i.e. he wants to be wiser than all the world.</div><div class=\"sense\"><b>Af. אָכִיל</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"כּוּל\">same</a>. <span class=\"citation\">Targ. Y. Ex. XVI, 18</span>, v. supra. <span class=\"citation\">Targ. Y. II, Gen. XXXVIII, 26</span> <span dir=\"rtl\">מָכִיל</span> (not <a href=\"#\" data-headword=\"מָנִיכָא\">מְ׳</a>).</div></div><div class=\"sense\"><b>Pa. כַּיֵּיל</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"כְּלָלָא\">כְּלָלָא</a>) <i>to generalize; lay down a rule</i>. <span class=\"citation\">Keth. 60ᵃ</span>, v. <a href=\"#\" data-headword=\"כְּלָלָא\">כְּלָלָא</a>.</div></div><div class=\"sense\"><b>Ithpe. אִתְכִּיל  אִתְכַּל</b> <div class=\"sense\"><i>to be measured</i>. Targ. Y. II, Gen. l. c. <span class=\"citation\">Targ. Is. XL, 12</span>; a. e.</div></div>","alt":["כִּיל"]},"12123":{"h":"כּוּלּ־","r":"K00261","html":"<div class=\"sense\"> h., v. <a href=\"#\" data-headword=\"כֹּל\">כֹּל</a></div>","alt":[]},"12124":{"h":"כּוֹל","r":"K00262","html":"<div class=\"sense\"><b>1)</b> <i>all, every one; any</i>. Constr. <a href=\"#\" data-headword=\"כָּל\">כָּל</a> (frequ. used absolutely). <span class=\"citation\">Targ. O. Gen. XVI, 12</span>, sq. <span class=\"citation\">Targ. Ex. XX, 9</span>. <span class=\"citation\">Targ. Y. Deut. XXXII, 49</span> <span dir=\"rtl\">לא כל היאך</span> not at all as (thou sayest); a. fr.—Y. Yoma VIII, 45ᵇ bot. <span dir=\"rtl\">לא כולא מן הדין וכ׳</span> all does not depend upon this man (it is not at all within his power) to say to the king, Thou art no king, i.e. his saying that the Day of Atonement has no atoning power, cannot affect its power; <span class=\"citation\">Y. Shebu. II, 33ᵇ</span> bot.—<span class=\"citation\">Snh. 46ᵇ</span>, a. fr. <span dir=\"rtl\">(<span dir=\"rtl\">לאו</span>) <span dir=\"rtl\">לא כל כמיניה</span></span> all is not as if dependent on him, i.e. he has no power to &amp;c. <span class=\"citation\">Gen. R. s. 79</span>, beg. (expl. <span dir=\"rtl\">בכלח</span>, <span class=\"citation\">Job V, 26</span>) <span dir=\"rtl\">תבא בכולא אלי וכ׳</span> (some ed. <span dir=\"rtl\">בכוֹלָּה</span>) thou shalt enter the grave in fulness, full, wanting nothing.—<span dir=\"rtl\">כָּל דְּכֵן</span> = h. <span dir=\"rtl\">כָּל שֶׁכֵּן</span>, v. <a href=\"#\" data-headword=\"כֹּל\">כֹּל</a>. <span class=\"citation\">Targ. Job IV, 19</span>; a. fr.—<span class=\"citation\">Nidd. 51ᵃ</span>; a. fr.—<span dir=\"rtl\">כָּל עלמא</span>, v. infra.—With suffix <a href=\"#\" data-headword=\"כּוּלָּךְ\">כּוּלָךְ</a>, <span dir=\"rtl\">כּוּלֵיה</span> &amp;c. (Buxt. <a href=\"#\" data-headword=\"כַּלָּךְ\">כֻּלָּךְ</a> &amp;c.) <i>all of thee, of him</i> &amp;c., <i>entire</i>. <span class=\"citation\">Targ. Gen. XXV, 25</span>; a. fr.—<span class=\"citation\">Yoma 14ᵇ</span> <span dir=\"rtl\">כוליה יומא</span> the entire day; <span class=\"citation\">ib. 19ᵃ</span> (not <a href=\"#\" data-headword=\"כולי\">כולי</a>). <span class=\"citation\">Ib. 26ᵃ</span> <span dir=\"rtl\">כּוּלְהוּ מצפרא אתו</span> (v. Rabb. D. S. a. l. note 10) all of them come in (for their share) by the lots cast in the morning; a. fr.—Pl. constr. <a href=\"#\" data-headword=\"כולי\">כּוּלֵי</a> <i>all of</i>. <span class=\"citation\">Targ. Esth. VI, 1</span> <span dir=\"rtl\">כ׳ ליליא</span> (ed. Lag. <span dir=\"rtl\">כוליה</span>). <span class=\"citation\">Targ. Koh. X, 12</span> <span dir=\"rtl\">כ׳ עלמא</span> (ed. Lag. <span dir=\"rtl\">כוליה</span>).—<span class=\"citation\">Y. Ber. II, 4ᵇ</span> <span dir=\"rtl\">כ׳ עלמא ידעין</span> ed. Lehm. (ed. <span dir=\"rtl\">כל</span>) all the world, <i>all people</i> know (abbr. <span dir=\"rtl\">כ&quot;ע</span>); <span class=\"citation\">Y. M. Kat. III, 83ᶜ</span> bot. <span dir=\"rtl\">כל עמא</span>; v. <a href=\"#\" data-headword=\"עָלַם III\">עָלְמָא</a>. <span class=\"citation\">Kidd. 79ᵇ</span>, v. <a href=\"#\" data-headword=\"כּוּל\">כּוּל</a> ch.—<span dir=\"rtl\">כ׳ האי</span> all of that, <i>to that extent</i>. <span class=\"citation\">Erub. 61ᵃ</span>. <span class=\"citation\">B. Mets. 84ᵇ</span> <span dir=\"rtl\">כ׳ ה׳ ודאי וכ׳</span> after it has come to all this (it being so well known), it is surely not proper. <span class=\"citation\">Ab. Zar. 24ᵃ</span>; a. v. fr.—<span class=\"citation\">Ḥag. 4ᵇ</span> <span dir=\"rtl\">כ׳ ה׳ ואולי</span> all this (is required of us) and yet only ‘perhaps’ (<span class=\"citation\">Zeph. II, 3</span>)! <span class=\"citation\">Taan. 25ᵃ</span> <span dir=\"rtl\">כ׳ ה׳ ואפשר</span> all this (trouble) and ‘only perhaps’!—</div><div class=\"sense\"><b>*2)</b> <i>capacity, power</i> (cmp. <span dir=\"rtl\">יכל</span>). <span class=\"citation\">Y. Peah VIII, 20ᵈ</span> bot. <span dir=\"rtl\">לא כָּלָּן מסתור וכ׳</span></div>","alt":["כּוֹלָא","כּוֹלָּא"]},"12125":{"h":"כּוּלָב","r":"K00263","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כָּלַב\">כָּלַב</a>; cmp. <a href=\"#\" data-headword=\"פֶּה\">פֶּה</a>, στόμα for <i>edge</i>) <i>a sharp instrument</i>, <i>axe</i>. <span class=\"citation\">Targ. I Sam. XIII, 20</span> (some ed. <span dir=\"rtl\">כלוב׳</span>, Ar. <a href=\"#\" data-headword=\"כּוּלְּכָא\">כולכא</a>; h. text <a href=\"#\" data-headword=\"קרדם\">קרדם</a>).—<span class=\"citation\">Gen. R. s. 38</span> אייטו לי כולב Ar. (ed. <span dir=\"rtl\">אייתי לי קולב</span>), v. <a href=\"#\" data-headword=\"יְטִי\">יְטִי</a>.—<span class=\"citation\">Lev. R. s. 4</span> <span dir=\"rtl\">הן די … זיינא כּוּלְבֵיה וכ׳</span> (not <span dir=\"rtl\">זייניה כולבא</span>) where the owner of arms (warrior) hangs up his battle axe, the shepherd hangs up his bag, i.e. in the place of justice sits wickedness; <span class=\"citation\">Koh. R. to III, 16</span> <span dir=\"rtl\">קולביה</span>; (<span class=\"citation\">Yalk. Koh. 969</span> <span dir=\"rtl\">באתרא … זייניה</span> where the lord hangs up his armor). <span class=\"citation\">Y. Naz. I, 51ᵇ</span> <a href=\"#\" data-headword=\"כּוּלָב\">כולבה</a> a. <a href=\"#\" data-headword=\"כּוּלָב\">כולבא</a>; <span class=\"citation\">Y. Ned. I, 36ᵈ</span> top <span dir=\"rtl\">כולכה</span>, v. <a href=\"#\" data-headword=\"קַנְתָּא\">קַנְתָּא</a>.—Pl. <span dir=\"rtl\">כּוּלְבַיָּיא</span>. <span class=\"citation\">Targ. I Sam. XIII, 21</span>. <span class=\"citation\">Targ. Jud. IX, 48</span> (Ar. <a href=\"#\" data-headword=\"כולבסין\">כולכ׳</a>). <span class=\"citation\">Targ. Ps. LXXIV, 5</span>.—V. <a href=\"#\" data-headword=\"*כָּלוּב\">כָּלוּב</a>.</div>","alt":["כּוּלְבָא","כּוּלְבָה"]},"12126":{"h":"כּוּלְבּוּס","r":"K00264","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּלְבּוּס\">כַּלְבּוּס</a></div>","alt":[]},"12127":{"h":"כולבסין","r":"K00265","html":"<div class=\"sense\">, <span class=\"citation\">Y. Dem. II, 22ᶜ</span> bot., v. <a href=\"#\" data-headword=\"בּוּלְבּוֹס\">בּוּלְבּוֹס</a></div>","alt":["כולכ׳"]},"12128":{"h":"כּוּלָה","r":"K00266","html":"<div class=\"sense\">, <i>a measure</i>, v. <a href=\"#\" data-headword=\"*כְּלָה\">כְּלָה</a>.</div>","alt":[]},"12129":{"h":"כּוֹלָה","r":"K00267","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוֹל\">כּוֹלָא</a></div>","alt":[]},"12130":{"h":"כולוניס","r":"K00268","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Mets. IV, 7</span>, v. <a href=\"#\" data-headword=\"כָּלִינוֹס\">כָּלִינוֹס</a></div>","alt":[]},"12131":{"h":"כולי","r":"K00269","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בּוּלִי I\"><span dir=\"rtl\">בּוּלִי</span> I</a>, II.—<a href=\"#\" data-headword=\"כולי\">כּוּלֵי</a> pl. constr. of <a href=\"#\" data-headword=\"כּוֹל\">כּוֹלָא</a>.</div>","alt":[]},"12132":{"h":"כּוֹלְיָא","r":"K00270","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(v. <a href=\"#\" data-headword=\"כִּלְיָה\">כִּלְיָה</a>) [<i>rounded</i>,] </div><div class=\"sense\"><b>1)</b> <i>testicle</i>. <span class=\"citation\">Targ. Y. II, Lev. XXI, 20</span>. <span class=\"citation\">Targ. Y. ib. XXII, 23</span>.</div><div class=\"sense\"><b>—2)</b> <i>kidney</i>. <span class=\"citation\">Ḥull. 97ᵃ</span>.—Pl. <a href=\"#\" data-headword=\"כּוֹלְיָא\">כּוֹלְיָן</a>, <a href=\"#\" data-headword=\"כּוֹלְיָא\">כּוֹלְיָין</a>, <span dir=\"rtl\">כּוֹלְיָתָא</span> (<a href=\"#\" data-headword=\"כּוֹלְיָא\">כּוּלְ׳</a>. <a href=\"#\" data-headword=\"כּוֹלְיָא\">כָּלְ׳</a>). <span class=\"citation\">Targ. Lev. III, 4</span>; a. fr. <span class=\"citation\">Targ. Job XXXVIII, 36</span> <span dir=\"rtl\">כוליין</span> ed. Lag. (oth. <a href=\"#\" data-headword=\"כַּלִּין\">כָּלְיָן</a>, Ms. Var. <span dir=\"rtl\">כוליתא</span>). <span class=\"citation\">Targ. Is. XXXIV, 6</span> <span dir=\"rtl\">כָּלְיַת</span> constr.—<span class=\"citation\">Sabb. 119ᵇ</span>.—[<a href=\"#\" data-headword=\"כּוֹלְיָא\">כּוּלְיָא</a> h., v. <a href=\"#\" data-headword=\"כִּלְיָה\">כִּלְיָה</a>.]</div>","alt":["כּוֹלְיָיא","(כּוּל׳","כָּלְ׳)"]},"12133":{"h":"כוליאר","r":"K00271","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוֹכְלִיאָר\">כּוֹכְלְיָיר</a></div>","alt":[]},"12134":{"h":"כּוּלְיָה","r":"K00272","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּלְיָה\">כִּלְיָה</a></div>","alt":[]},"12135":{"h":"כּוֹלִיקוֹס","r":"K00273","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (χολικός, in the sense of μελαγχολικός) <i>one afflicted with melancholy</i>. <span class=\"citation\">Y. Ter. I, 40ᵇ</span> <span dir=\"rtl\">המקרע את כסותו כ׳</span> if one tears his clothes, I may say, he is melancholy (but not insane); <span class=\"citation\">Y. Gitt. VII, beg. 48ᶜ</span> <span dir=\"rtl\">המקרע … קינוקוס</span> (corr. acc.).</div>","alt":[]},"12136":{"h":"כּוּלָּךְ","r":"K00274","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּלָּךְ\">כַּלָּךְ</a></div>","alt":[]},"12137":{"h":"כּוּלְּכָא","r":"K00275","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>cissaros-blossom</i> (v. <a href=\"#\" data-headword=\"*אַגְבִּין\">אַגְבִּין</a>). <span class=\"citation\">Sabb. 20ᵇ</span>; Y. ib. II, beg. 4ᵈ, expl. <a href=\"#\" data-headword=\"כַּלָּךְ\">כַּלָּךְ</a>. <span class=\"citation\">Y. Kil. IX, 32ᵃ</span> top <span dir=\"rtl\">כַּלְּכָה שמו</span> its name is <i>kall’kha</i>. [<a href=\"#\" data-headword=\"כּוּלְּכָא\">כולכא</a>, <span dir=\"rtl\">כולכה</span>, for <a href=\"#\" data-headword=\"כּוּלָב\">כולבא</a>, v. <a href=\"#\" data-headword=\"כּוּלָב\">כּוּלְבָא</a>.)</div>","alt":[]},"12138":{"h":"כולכסין","r":"K00276","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כולבסין\">כולבסין</a></div>","alt":[]},"12139":{"h":"כולם","r":"K00277","html":"<div class=\"sense\">, <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">וכן דימוס וכן כ׳</span> (some ed. <span dir=\"rtl\">כולו</span>), read: <a href=\"#\" data-headword=\"בּוּלִי II\"><span dir=\"rtl\">בּוּלִי</span> II</a>.</div>","alt":[]},"12140":{"h":"כולמתא","r":"K00278","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּלְנִיתָא\">next w.</a></div>","alt":[]},"12141":{"h":"כּוּלְנִיתָא","r":"K00279","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. Löw Pfl. p. 200 sq.) [<i>Little Bride</i>,] <i>Papaver Spinosum</i>.—Pl. <span dir=\"rtl\">כּוּלְנְיָיתָא</span>. <span class=\"citation\">Pes. 35ᵃ</span> Ar. (ed. <a href=\"#\" data-headword=\"כַּלְנִיתָא\">כַּלְנְיָתָא</a>; Ms. O. <span dir=\"rtl\">כַּלְנְיָיתָא</span>; Ms. M. 1 <a href=\"#\" data-headword=\"כולמתא\">כולמתא</a>; Ms. M. 2 <span dir=\"rtl\">כיליניתא</span>); v. <a href=\"#\" data-headword=\"קַרְמִית\">קַרְמִית</a>.</div>","alt":["כַּלְנִיתָא"]},"12142":{"h":"כולסא","r":"K00280","html":"<div class=\"sense\">, <span class=\"citation\">Sabb. 154ᵇ</span>, v. <a href=\"#\" data-headword=\"בּוּלְסָא\">בּוּלְסָא</a></div>","alt":[]},"12143":{"h":"כּוֹלֵף","r":"K00281","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">כלף</span>, cmp. <span dir=\"rtl\">קלף</span>, <span dir=\"rtl\">גלב</span>) <i>plane</i>. <span class=\"citation\">Tosef. Kel. B. Bath. VII, 3</span> <span dir=\"rtl\">יד הכ׳ ובֶן כ׳</span> (not <span dir=\"rtl\">ובין</span>) the handle of a large or of a small plane (some ed. <span dir=\"rtl\">הכילוף וכן הכילוף</span>, corr. acc.).</div>","alt":[]},"12144":{"h":"כולפסון","r":"K00282","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kil. III, 12</span> ed. Zuck., read: <a href=\"#\" data-headword=\"בּוּלְבְּסִין\">בּוּלְבְּסִין</a>, v. <a href=\"#\" data-headword=\"בּוּלְבּוֹס\">בּוּלְבּוֹס</a></div>","alt":[]},"12145":{"h":"כולקוס","r":"K00283","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּלְקִיס\">כַּלְקִיס</a></div>","alt":[]},"12146":{"h":"*כּוֹלֶּקְטָר","r":"K00284","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (collectarius), pl. <span dir=\"rtl\">כּוֹלֶּקְטָרִין</span> <i>cashiers</i>. Pesik. Haḥod. p. 56ᵃ <span dir=\"rtl\">מי פורע … שני דלקטירין וכ׳</span> (corr. acc.) who will collect for you the debt from them (bring about their punishment)? Two collectors, Mordecai and Esther; <span class=\"citation\">Pesik. R. s. 15</span> <span dir=\"rtl\">בלקטירים</span>; <span class=\"citation\">Yalk. Ex. 191</span> <a href=\"#\" data-headword=\"סלקטירין\">סלקטירין</a> (corr. acc.).</div>","alt":[]},"12147":{"h":"כּוּלְתָא","r":"K00285","html":"<div class=\"sense\"><i>wrath</i>, v. <a href=\"#\" data-headword=\"כָּלוּ\">כָּלוּ</a>.</div>","alt":[]},"12148":{"h":"כּוּמָז","r":"K00286","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> an opprobrious name for <i>an ornament</i> bearing the impress of the female breast or pudenda. Y. Sabb. V, 8ᵇ bot.; Bab. <span class=\"citation\">Sabb. 64ᵃ</span></div>","alt":[]},"12149":{"h":"*כּוּמְנִי","r":"K00287","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (prob. a corrupt. of χαμεύνη, <i>a pallet-bed</i>) <i>mattress</i> used as a seat for travelling women. <span class=\"citation\">Tosef. B. Bath. IV, 2</span>; <span class=\"citation\">B. Bath. 78ᵃ</span>, expl. <span dir=\"rtl\">מרכבתא דנשי</span>.</div>","alt":[]},"12150":{"h":"כּוֹמְסָה","r":"K00288","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <span dir=\"rtl\">כּוֹמְסוֹת</span>, (<a href=\"#\" data-headword=\"כָּמַס\">כָּמַס</a>) <span dir=\"rtl\">כּוֹמְסָאוֹת</span> <i>sheaves put at the bottom of a stack</i> as foundation, contrad. to <a href=\"#\" data-headword=\"כּוֹבְעָה\">כּוֹבְעָה</a>. <span class=\"citation\">Peah V, 8</span>; Y. ib. V, end, 19ᵃ, expl. <span dir=\"rtl\">מן לרע</span> (with ref. to <span class=\"citation\">Deut. XXXII, 34</span>).</div>","alt":["כּוֹמְסִי"]},"12151":{"h":"כּוּמְצָא","r":"K00289","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">כמץ</span>, cmp. <span dir=\"rtl\">כמן</span>) <i>trap, pit</i>. <span class=\"citation\">Targ. Is. XXIV, 17</span>, sq.; <span class=\"citation\">Targ. Jer. XLVIII, 43</span>, sq. (h. text <span dir=\"rtl\">פחת</span>). V. <a href=\"#\" data-headword=\"קוּמְצָא ²\"><span dir=\"rtl\">קוּמְצָא</span> II</a>, cmp. <a href=\"#\" data-headword=\"גּוּמָּצָא\">גּוּמְצָא</a>.</div>","alt":[]},"12152":{"h":"כּוֹמֶר I","r":"K00290","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּמַר\">כָּמַר</a>) <i>a mass of olives or grapes shrunk</i> from exposure to the sun or from being put in the ground, prior to being placed in the press. <span class=\"citation\">B. Mets. 74ᵃ</span>. <span class=\"citation\">Y. Ber. II, 4ᵇ</span> bot. <span dir=\"rtl\">ככ׳ הזה של ענבים וכ׳</span> like the mass of heated grapes that drips of itself; <span class=\"citation\">Cant. R. to VII, 10</span> <span dir=\"rtl\">כבמרזה וכ׳</span> some ed. (read <span dir=\"rtl\">ככֹּמֶר הזה</span>); <span class=\"citation\">Yeb. 97ᵃ</span>; <span class=\"citation\">Bekh. 31ᵇ</span>; <span class=\"citation\">Y. Shek. II, end, 47ᵃ</span> <a href=\"#\" data-headword=\"כֹּמֶר\">כֹּמֶר</a>.</div>","alt":[]},"12153":{"h":"כּוֹמֶר II","r":"K00291","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>to guard</i>, cmp. <a href=\"#\" data-headword=\"כֹּהֵן\">כֹּהֵן</a>. In Syriac <a href=\"#\" data-headword=\"כּוּמָרָא\">כומרא</a> interchanges with <a href=\"#\" data-headword=\"כָּהֵן\">כהנא</a>, v. P. Sm. 1757 s. v.) <i>attendant, priest</i>, always used of idolaters. <span class=\"citation\">Kidd. 20ᵇ</span> <span dir=\"rtl\">נעשה כ׳ לע&quot;ז</span> (<span class=\"citation\">Arakh. 30ᵇ</span> <span dir=\"rtl\">משרת</span>) became an attendant of an idolatrous temple. <span class=\"citation\">Y. Ab. Zar. I, 39ᵈ</span>. <span class=\"citation\">Pesik. R. s. 35</span> <span dir=\"rtl\">יתרו לא כ׳ וכ׳</span> was not Jethro an idolatrous priest?; a. fr.—Pl. <span dir=\"rtl\">כּוּמָרִים</span>, <span dir=\"rtl\">כּוּמָרִין</span>. <span class=\"citation\">Ab. Zar. 51ᵇ</span> <span dir=\"rtl\">בטובת כ׳</span> for the benefit of the idolatrous priests, opp. <span dir=\"rtl\">עובדיה</span> worshippers; Y. ib. IV, 43ᵈ bot. <span class=\"citation\">Erub. 79ᵇ</span> bot. Ms. M. (ed. <span dir=\"rtl\">משרתי ע&quot;ז</span>). <span class=\"citation\">Gen. R. s. 65</span>, beg.; a. fr.</div>","alt":["כּוּמָר"]},"12154":{"h":"כּוּמָרָא","r":"K00292","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Jud. XVII, 5</span>; <span class=\"citation\">13</span> (interch. with <span dir=\"rtl\">כהין</span> <span class=\"citation\">ib. 10</span>; <span class=\"citation\">12</span>; h. text <a href=\"#\" data-headword=\"כֹּהֵן\">כֹּהֵן</a>); a. e.—<span class=\"citation\">Lam. R. to I, 9</span> <span dir=\"rtl\">ההוא כ׳</span> (<span class=\"citation\">Yalk. Ez. 356</span> <span dir=\"rtl\">ההיא אפיקורוס</span>).—Pl. <span dir=\"rtl\">כּוּמָרִין</span>, <span dir=\"rtl\">כּוּמָרַיָּא</span>, <a href=\"#\" data-headword=\"כֻּרְהָנָא\">כּוּמְ׳</a>. <span class=\"citation\">Targ. Jud. XVIII, 30</span>. <span class=\"citation\">Targ. II Kings XXIII, 5</span>; a. fr.—<span class=\"citation\">Gen. R. s. 26</span>, v. <a href=\"#\" data-headword=\"אֱלָהּ\">אֱלָהּ</a>. <span class=\"citation\">Ex. R. s. 9</span> (prov.) <span dir=\"rtl\">מחי אלהיא ויבעתון כ׳</span> strike the gods, and the priests will be frightened.</div>","alt":["כּוּמְרָא I"]},"12155":{"h":"כּוּמְרָא II","r":"K00293","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כּוֹמֶר I\"><span dir=\"rtl\">כּוֹמֶר</span> I</a>) <i>withering</i>. <span class=\"citation\">Ber. 40ᵇ</span> בושלי כ׳ Ms. M. a. oth. (ed. <a href=\"#\" data-headword=\"כֹּמֶר\">כמרא</a>, expl. <span dir=\"rtl\">נובלות</span>) dates ripened through withering.</div>","alt":[]},"12156":{"h":"כּוּמְרָנָא","r":"K00294","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"כּוּמָרָא\">כּוּמָרָא</a>.—Pl. <span dir=\"rtl\">(<span dir=\"rtl\">כּוּמַרְנַיָּא</span>) <span dir=\"rtl\">כּוּמְרָנַיָּא</span></span>. <span class=\"citation\">Targ. Y. Gen. XXXIX, 20</span>; a. e. (in Y.).</div>","alt":[]},"12157":{"h":"כּוּמְתָא","r":"K00295","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">כמם</span>, v. <span dir=\"rtl\">כמן</span>; cmp. Arab. <i>kummath</i>, Fl. to Levy Talm. Dict. II, 450ᵇ) <i>skull-cap</i>, worn under the turban <a href=\"#\" data-headword=\"סוּדָרָא\">(סוּדְרָא</a>). <span class=\"citation\">Erub. 84ᵇ</span> <span dir=\"rtl\">דילמא כשהרבים … בכ׳ וסודרא</span> perhaps the public use of them (the low roofs) refers to people putting their cap and turban on them? <span class=\"citation\">Ib. 91ᵃ</span> bot. <span dir=\"rtl\">בכ׳ וס׳</span> it may be possible with cap &amp;c. (by putting them on in the house and taking them off in the court). <span class=\"citation\">M. Kat. 15ᵃ</span> <span dir=\"rtl\">אכ׳ וס׳</span> it refers to (the mourner’s) cap and turban. <span class=\"citation\">Gitt. 39ᵇ</span> <span dir=\"rtl\">שקל כּוּמְתֵיה וכ׳</span> he took his cap and threw it at her. <span class=\"citation\">Sabb. 147ᵃ</span> <span dir=\"rtl\">הב לי כּוּמְתָאִי</span> hand me my cap.</div>","alt":[]},"12158":{"h":"כּוּן","r":"K00296","html":"<div class=\"sense\"> (b. h.) <i>to stand, exist, be firm</i>.</div><div class=\"sense\"><b>Pi. כִּיוֵּון</b> <div class=\"sense\"><b>1)</b> <i>to straighten</i>. <span class=\"citation\">Sifré Deut. 308</span> <span dir=\"rtl\">מְכַוְּונוֹ במעגילה</span> he tries to straighten the wood in a press; <span class=\"citation\">Yalk. Deut. 942</span> (not <span dir=\"rtl\">מכינן</span>); Pesik. Zutr. Haăz. (ed. Bub. V, p. 111) <span dir=\"rtl\">נתנו לאומן שיְכַוְּונוֹ</span> he gave it to a mechanic to straighten it.</div><div class=\"sense\"><b>—2)</b> <i>to place in a line, direct</i>. <span class=\"citation\">Macc. II, 5</span> (<span class=\"citation\">9ᵇ</span>) <span dir=\"rtl\">מְכַוְּונִין להן דרך וכ׳</span> Ms. M. (ed. <span dir=\"rtl\">ומְכוּוָּנוֹת להן דרכים</span>, v. infra) we make for them direct roads from one place of refuge to the other.</div><div class=\"sense\"><b>—3)</b> <i>to determine exactly</i> (place, time &amp;c.). Y. Erub. V, 22ᶜ <span dir=\"rtl\">לְכַוֵּין את הרוחות</span> how to determine exactly the four cardinal points (v. <a href=\"#\" data-headword=\"רָבַע\">רָבַע</a>). Ib. bot. <span dir=\"rtl\">הארון היה מְכַוֵּין וכ׳</span> the Ark indicated for them the points of the compass. <span class=\"citation\">Gen. R. s. 15</span>, beg., v. <a href=\"#\" data-headword=\"כִּוּוּן\">כִּוּוּן</a>. <span class=\"citation\">M. Kat. 10ᵃ</span> <span dir=\"rtl\">אין יכול לכַוֵּין אימרא וכ׳</span> is unable to sew the fringe accurately on the bosom of the shirt. <span class=\"citation\">Ber. 7ᵃ</span> <span dir=\"rtl\">לכַוֵּין אותה שעה</span> to seize the opportunity of just that moment; a. fr.</div><div class=\"sense\"><b>—4)</b>  (with <a href=\"#\" data-headword=\"לֵב\">לב</a> or sub. <a href=\"#\" data-headword=\"לֵב\">לב</a>) <i>to direct</i> or <i>prepare one’s mind, to pay attention, to do a thing with an intention</i>. <span class=\"citation\">Ber. II, 1</span> <span dir=\"rtl\">אם כ׳ לבו</span> if he (while reading in the Law) had his mind directed (to the Sh’ma); <span class=\"citation\">ib. 13ᵃ</span> <span dir=\"rtl\">אם כ׳ לבו לקרות</span> it means, he read with attention (to the sense, not merely like one going over the text for correction). <span class=\"citation\">R. Hash. 28ᵇ</span> <span dir=\"rtl\">כ׳ לבו לצאת</span> he had the intention of complying with the law (v. <a href=\"#\" data-headword=\"יָצָא\">יָצָא</a>); opp. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"כ׳\">כ׳</a>) <span dir=\"rtl\">לשמוע</span></span> he directed his attention to listening, i.e. heard the sound with consciousness (but without devotion); v. <a href=\"#\" data-headword=\"כַּוָּונָה\">כַּוָּונָה</a>. <span class=\"citation\">Ber. V, 1</span> <span dir=\"rtl\">היו שוהין … כדי שיְכַוְּונוּ לבם וכ׳</span> tarried a while before prayer, in order to direct their hearts to their Father in heaven. Y. ib. II, 5ᵃ <span dir=\"rtl\">חזקה כִּוֵּין</span> the presumption is that he read with attention; a. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"*מְכַוֵּון\">מְכוּוָּן</a>, f. <span dir=\"rtl\">מְכוּוָּנָה</span>, <span dir=\"rtl\">מְכוּוֶּנֶת</span>; pl. <span dir=\"rtl\">מְכוּוָּנִים</span>, … <a href=\"#\" data-headword=\"נִין\">נִין</a>; <span dir=\"rtl\">מְכוּוָּנוֹת</span> a) <i>in a line, corresponding</i>. Y. Kil. V, beg. 30ᵇ <span dir=\"rtl\">עריס המכ׳</span> a straight bed of vines, opp. <span dir=\"rtl\">מעוקם</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מכ׳ הן</span> they (the vines) are in a straight line. Y. Ber. IV, 8ᶜ top <span dir=\"rtl\">בית … מ׳ כנגד … של מעלן</span> the situation of the earthly Holy of Holies corresponds with that of the heavenly &amp;c. <span class=\"citation\">Macc. II, 5</span> <span dir=\"rtl\">ומכוונות להן דרכים</span> (not … <span dir=\"rtl\">נת</span>), v. supra. <span class=\"citation\">Ib. 9ᵇ</span> <span dir=\"rtl\">ומכוונות היו כמין וכ׳</span> (Ms. M. <span dir=\"rtl\">ומכוונין הן</span>) and they (the three towns on this side and those on the other side of the Jordan respectively) were in straight parallel lines like two rows in a vineyard; a. fr.—b) <i>exact, precise.</i> <span class=\"citation\">Toh. III, 1</span> sq. <span dir=\"rtl\">כביצה מ׳</span> exactly the quantity of an egg. <span class=\"citation\">Mikv. VII, 6</span>; <span class=\"citation\">Ḥag. 19ᵃ</span>; <span class=\"citation\">Gitt. 16ᵃ</span></div></div><div class=\"sense\"><b>Hif. הֵכִין</b> <div class=\"sense\"><i>to put in proper position, to prepare; to hold ready, to designate</i>. <span class=\"citation\">Bets. 2ᵇ</span> (ref. to <span class=\"citation\">Ex. XVI, 5</span>) <span dir=\"rtl\">חול מֵכִין לשבתוכ׳</span> a week day prepares for the Sabbath (that which has become ready for use on a week day may be used on the Sabbath), but a Holy Day does not prepare for the succeeding Sabbath, <span dir=\"rtl\">ואין שבת מֵכִינָה ליו&quot;ט</span> nor can the Sabbath prepare for a succeeding Holy Day, v. <a href=\"#\" data-headword=\"הֲכָנָה\">הֲכָנָה</a>.—<span class=\"citation\">Meg. 12ᵇ</span> (play on <a href=\"#\" data-headword=\"מְמוּכָן\">ממוכן</a>, <span class=\"citation\">Esth. I, 14</span>) <span dir=\"rtl\">כלום הֵכִינוּ וכ׳</span> have they (the Persians) arranged a table before thee?; Esth. R. to l. c. <span dir=\"rtl\">מי מֵכִין וכ׳</span> who arranges an altar &amp;c.?; a. fr.—[<span class=\"citation\">Tosef. Maasr. I, 4</span> <span dir=\"rtl\">משיכינו</span> ed. Zuck., Var. <span dir=\"rtl\">משייבינו</span>, read: <span dir=\"rtl\">משיניצו</span>.]—<i>Part. pass</i>. <a href=\"#\" data-headword=\"מוּכָן\">מוּכָן</a> <i>prepared, designated, ready</i>. <span class=\"citation\">Bets. I, 2</span> <span dir=\"rtl\">עפר מ׳ מבעוד יום</span> dust (for covering the blood) made ready a day before. Ib. <span dir=\"rtl\">אפר כירה מ׳ הוא</span> ashes of the stove are considered ready (destined to be used for the purpose). Ib. III, 4 <span dir=\"rtl\">אין זה מן המ׳</span> this is not among the things designated for use on the Holy Day. Ib. IV, 6.—Meg. l. c. (play on <a href=\"#\" data-headword=\"מְמוּכָן\">ממוכן</a>, v. supra) <span dir=\"rtl\">שמ׳ לפורענות</span> he was ready for evil; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְכַּיֵּון  הִתְכַּוֵּון</b> </div><div class=\"sense\"><b>Nithpa. נִתְכַּוֵּין</b> <div class=\"sense\"><b>1)</b> <i>to be made straight, to be remedied</i> (cmp. <a href=\"#\" data-headword=\"תְּכַן\">תכן</a>). Pesik. Zutr. l. c. <span dir=\"rtl\">אין אתם מִתְכַּוְּונִים אלא באור</span> you (your crookedness) can be remedied only through fire; Sifré Deut. l. c. <span dir=\"rtl\">אין אתם הולכים אלא לאור</span>; Yalk. Deut. l. c. <span dir=\"rtl\">הולכין אלא לאחור</span> (corr. acc.).</div><div class=\"sense\"><b>—2)</b> <i>to prepare one’s self</i>. Y. Meg. I, 71ᶜ (ref. to <span dir=\"rtl\">הִכּוֹן</span>, <span class=\"citation\">Am. IV, 12</span>) <span dir=\"rtl\">הִתְכַּוֵּון לקראת וכ׳</span> put thyself in proper condition to meet thy God.</div><div class=\"sense\"><b>—3)</b> <i>to intend, propose</i>. <span class=\"citation\">B. Kam. VIII, 1</span> <span dir=\"rtl\">עד שיהא מִתְכַּ יֵן</span> unless he did it with malicious intent. <span class=\"citation\">Tosef. Naz. III, 10</span> <span dir=\"rtl\">לא נִתְכַּוַּונְתִּי אלא כמותה</span> my intention was to be exactly like her (as to her vow). <span class=\"citation\">Ib. 14</span> <span dir=\"rtl\">מי שנ׳ לעלות וכ׳</span> if he who had the intention to eat the flesh of swine &amp;c.; v. <a href=\"#\" data-headword=\"עָלָה\">עָלָה</a>. <span class=\"citation\">Sabb. 22ᵃ</span> <span dir=\"rtl\">ובלבד שלא יִתְכַּוֵּין וכ׳</span> provided he has not the intention of making a groove.—<span class=\"citation\">Bets. 23ᵃ</span>, a. fr. <span dir=\"rtl\">דבר שאינו מִתְכַּ׳</span> a forbidden act which was produced without intent, i.e. an unintended but unavoidable effect of a permitted act. <span class=\"citation\">R. Hash. 28ᵇ</span>. <span class=\"citation\">Pes. 53ᵇ</span>, a. fr. <span dir=\"rtl\">שניהם … נִתְכַּוְּונוּ</span> both meant the same thing; a. fr.</div></div><div class=\"sense\"><b>Polel. כּוֹנֵן</b> <div class=\"sense\"><i>to establish, base firmly</i>. <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">מבקש לְכוֹנֵן עולמים</span> wanted to establish worlds. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">על אלו אני מְכוֹנֵן וכ׳</span> upon those (the patriarchs) I will establish the world.—Part. pass. <a href=\"#\" data-headword=\"מְכוֹנָה\">מְכוֹנָן</a>, f. <span dir=\"rtl\">מְבוֹנֶנֶת</span>. Midr. Sam. ch. XVI (ref. to <span dir=\"rtl\">הכינני</span>, <span class=\"citation\">I Kings II, 24</span>) <span dir=\"rtl\">בזכות התורה המ׳ בארון</span> (the world exists) for the sake of the Law that is put up straight in the holy Ark.</div></div>","alt":[]},"12159":{"h":"כּוּן ²","r":"K00297","html":"<div class=\"sense\">; <i>Pa</i>. <a href=\"#\" data-headword=\"*כַּוָּון\">כַּוֵּון</a> </div><div class=\"sense\"><b>1)</b> <i>to direct, aim, draw a direct line</i>. <span class=\"citation\">Targ. Y. Num. XXII, 23</span>. <span class=\"citation\">Targ. Num. XXXIV, 7</span>, sq. (h. text <span dir=\"rtl\">תאה</span>). <span class=\"citation\">Targ. Y. Deut. X, 5</span> <span dir=\"rtl\">וכוונית</span> (h. text <span dir=\"rtl\">פנה</span>). <span class=\"citation\">Ib. XIX, 3</span> (h. text <span dir=\"rtl\">תכין</span>, v. <a href=\"#\" data-headword=\"כּוּן\">preced.</a>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to draw a parallel, compare</i>. <span class=\"citation\">Targ. Is. XLVI, 5</span> (h. text <span dir=\"rtl\">תמשילני</span>).</div><div class=\"sense\"><b>—3)</b>  (with <a href=\"#\" data-headword=\"דַּעְתָּא\">דעתא</a>, or sub. <a href=\"#\" data-headword=\"דַּעְתָּא\">דעתא</a>) <i>to direct the mind, to pay attention; to do a thing intentionally</i>. <span class=\"citation\">Targ. Y. Num. XI, 1</span> <span dir=\"rtl\">מכ׳ והגיאן ביש</span> intentionally speaking evil.—<span class=\"citation\">Ber. 17ᵇ</span> <span dir=\"rtl\">לא מצי לְכַוּוּנֵי דעתיה</span> he cannot collect his mind (for prayer). <span class=\"citation\">Ib. 30ᵇ</span> <span dir=\"rtl\">מעיקרא לא כ׳ וכ׳</span> the first time he read without attention. <span class=\"citation\">Ḥull. 31ᵃ</span> <span dir=\"rtl\">דלא קָמְכַוֵּין</span> (or <span dir=\"rtl\">קָמִכַּוֵּין</span> <i>Ithpa.</i>) when he had no intention whatever (to cut); a. fr.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"*מְכַוֵּון\">מְכַוַּון</a> a) <i>directed towards, corresponding</i>. <span class=\"citation\">Targ. Ez. I, 9</span>. <span class=\"citation\">Targ. Ex. XXVI, 5</span>; a. fr.—b) <i>straight, firm, upright</i>. <span class=\"citation\">Targ. Job XXI, 8</span> מְכַוְּונִין Bxt. (Ms. <span dir=\"rtl\">מְכַוְּונַן</span>; ed. <span dir=\"rtl\">מכוין</span>, <a href=\"#\" data-headword=\"*מְכַוֵּון\">מְכַוַּון</a>, corr. acc.; h. text <a href=\"#\" data-headword=\"נָכוֹן\">נכון</a>). <span class=\"citation\">Targ. Ps. LI, 12</span>. <span class=\"citation\">Ib. LVII, 8</span> (ed. Wil. <a href=\"#\" data-headword=\"מָכוֹן\">מכוֵן</a>, corr. acc.); a. fr.—<span class=\"citation\">Yoma 28ᵇ</span> לא מְכַוְּונֵי Ms. M. (ed. <span dir=\"rtl\">לא מ׳ טובא</span>) the Temple walls were not exactly straight (the lower portions being thicker than the upper); [Ms. M. 2 <span dir=\"rtl\">משום דמכווני</span> because the walls were exactly built in correspondence with the points of the compass]. <span class=\"citation\">Y. Snh. IV, beg. 22ᵃ</span>; III, 21ᶜ top [read:] <span dir=\"rtl\">כד הוא חמי סהדו מכַוְּונָא … הכן והכן מְכַוֵּון</span> when he found evidences (of two) exactly corresponding, he cross-examined; but when he found them turning hither and thither (differing in details), he tried to harmonize (allowing for errors in time &amp;c., v. <a href=\"#\" data-headword=\"חֲקִירָה\">חֲקִירָה</a>).</div><div class=\"sense\"><b>Ithpa. אִיתְכַּוֵּון  אִיכַּ׳</b> <div class=\"sense\">, <span dir=\"rtl\">כַּוֵּין …</span> </div><div class=\"sense\"><b>1)</b> <i>to place one’s self, to stand</i>. <span class=\"citation\">Targ. Ps. CI, 7</span>.</div><div class=\"sense\"><b>—2)</b> <i>to be precise in doing</i>. Ib. XC, 12 <span dir=\"rtl\">מן יִתְכַּ׳ להודע</span> ed. Lag. (oth. ed. <a href=\"#\" data-headword=\"כֵּן I\">כן</a>, corr. acc.) who can exactly make known? (h. text <span dir=\"rtl\">כן הודע</span>). <span class=\"citation\">Targ. Y. Lev. XIII, 12</span>.</div><div class=\"sense\"><b>—3)</b> <i>to be trained, to be in the habit of</i>. <span class=\"citation\">Targ. Y. Num. XXII, 30</span> (h. text <span dir=\"rtl\">הסכן</span>).</div><div class=\"sense\"><b>—4)</b> <i>to intend, mean</i>. Ib. XXX, 5 <span dir=\"rtl\">ויתכ׳ וישתוק</span> and keeps silence intentionally. <span class=\"citation\">Targ. Y. Deut. XIX, 4</span>; a. e.—<span class=\"citation\">Ḥull. 95ᵃ</span> <span dir=\"rtl\">דאיכ׳ לצעורי׳ וכ׳</span> who meant to vex his neighbor. <span class=\"citation\">Ib. 31ᵃ</span> <span dir=\"rtl\">מִיכַּוֵּין לשום חתיכה</span> had the intention merely to cut (not to slaughter according to the ritual, v. <a href=\"#\" data-headword=\"זְבִיחָה\">זְבִיחָה</a>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מה כלים דלא מִיכַּוְּונֵי וכ׳</span> as vessels (lifeless things) which have no thought &amp;c.; a. e.</div></div><div class=\"sense\"><b>Ithpe. אִיתְכָּן</b> <div class=\"sense\"><i>to be prepared, ready</i> (<a href=\"#\" data-headword=\"מוּכָן\">מוּכָן</a>, v. <a href=\"#\" data-headword=\"כּוּן\">preced.</a>). Ib. 14ᵃ <span dir=\"rtl\">כיון דלא א׳ וכ׳</span> because it was not prepared (designated for use) yesterday.—V. <a href=\"#\" data-headword=\"תְּכַן\">תכן</a>.</div></div>","alt":[]},"12160":{"h":"כֵּוָן","r":"K00298","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">כֵּיוָ׳</span>.</div>","alt":["כֵּוָנָא"]},"12161":{"h":"כַּוְנָא","r":"K00299","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כַּוָּוא\">כַּוָּוא</a>; cmp. <a href=\"#\" data-headword=\"חוֹפֶן\">חוֹפֶן</a> a. <a href=\"#\" data-headword=\"כַּף\">כַּף</a>) <i>the hollow of the hand, handful</i> (as a measure), <i>spoonful</i> (mostly in medicine; cmp. Lat. coclear). [Editions, except ed. Sonc., have <a href=\"#\" data-headword=\"ב׳\">ב׳</a>, Ar. a. Mss. <a href=\"#\" data-headword=\"כ׳\">כ׳</a>, v. Rabb. D. S. a. l. c. infra.] <span class=\"citation\">Sabb. 110ᵇ</span> <span dir=\"rtl\">כ׳ דכמונא וכ׳</span> (Ms. M. <a href=\"#\" data-headword=\"כִּנָּרָא\">כי׳</a>) one handful of cumin-seed, and one of &amp;c. <span class=\"citation\">Gitt. 70ᵃ</span> <span dir=\"rtl\">כ׳ דחמרא וכ׳</span> a spoonful of old wine.—Pl. <span dir=\"rtl\">כַּוְנֵי</span> or <span dir=\"rtl\">כּוּנֵי</span>. <span class=\"citation\">Erub. 29ᵇ</span> (ed. Sonc. <span dir=\"rtl\">כַּוְונֵי</span>, v. Rabb. R. S. a. l. note). <span class=\"citation\">Gitt. 69ᵃ</span> ed. <a href=\"#\" data-headword=\"כ׳\">כ׳</a>. <span class=\"citation\">Ib. 69ᵇ</span> (ed. <a href=\"#\" data-headword=\"ב׳\">ב׳</a>).</div>","alt":["כּוּנָא"]},"12162":{"h":"כּוּנְדָּא","r":"K00300","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּדְנָא\">כּוּדְנָא</a></div>","alt":[]},"12163":{"h":"כונדקא","r":"K00301","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַכְוַנְגַּר\">אַכְוַנְגַּר</a></div>","alt":[]},"12164":{"h":"כונדת׳","r":"K00302","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּדְנָא\">כּוּדְנָא</a></div>","alt":[]},"12165":{"h":"כַּוָּנָה","r":"K00303","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כּוּן\">כּוּן</a>, <i>Pi.</i> a. <i>Hithpa.</i>) <i>intention; attention; devotion</i>. <span class=\"citation\">Ber. 13ᵃ</span> <span dir=\"rtl\">ש&quot;מ מצוות צריכות כ׳</span> shall we derive fom this (Mish. <span class=\"citation\">ib. II, 1</span> <span dir=\"rtl\">אם כיון לבו וכ׳</span>) that religious exercises require the intention (of complying with the law, and must be repeated if performed without such intention)? <span class=\"citation\">R. Hash. 28ᵇ</span>, a. fr. <span dir=\"rtl\">מצוות אין צריכות כ׳</span> the intention of compliance is not indispensable; <span class=\"citation\">Erub. 95ᵇ</span> <span dir=\"rtl\">לצאת בעי כ׳</span> (v. Rabb. D. S. a. l. notes 90 a. 100) in order to have complied with the law, intention of compliance is required. <span class=\"citation\">Ber. 13ᵇ</span> <span dir=\"rtl\">כ׳ בלא קריאה</span> meditating (on the Biblical passage to be recited) without audible recitation. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">עד כאן צריכה כַּוָּנַת הלב</span> up to this (<i>sh’ma</i> to <i>eḥad</i>) attention to the meaning is indispensable. <span class=\"citation\">Meg. 20ᵃ</span> (ref. to <span class=\"citation\">Deut. VI, 6</span>) <span dir=\"rtl\">אחר כ׳ הלב הן הן הדברים</span> the value of ‘the words’ (the recitation) depends on the attention of the mind (devotion). <span class=\"citation\">Ḥull. 31ᵃ</span> <span dir=\"rtl\">כ׳ לשחיטה</span> the intention to slaughter according to the ritual; opp. <span dir=\"rtl\">לחתיכה</span>; a. fr.</div>","alt":["כַּוָּו׳"]},"12166":{"h":"כַּוָּנוּתָא","r":"K00304","html":"<div class=\"sense\"><span class=\"citation\">Targ. Y. Num. XXXV, 20</span> <span dir=\"rtl\">בכַוָּונוּת לבא</span> with premeditation (h. text <span dir=\"rtl\">בצדיה</span>). <span class=\"citation\">Targ. Ps. VII, 4</span>.</div>","alt":["כַּוַּנְתָּא","כַּוּו׳"]},"12167":{"h":"כַּוָּנִים","r":"K00305","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*כַּוָּון\">כַּוָּון</a></div>","alt":[]},"12168":{"h":"כּוּנִישְׁרָא","r":"K00306","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּנְשְׁרָא\">כּוּנְשְׁרָא</a></div>","alt":[]},"12169":{"h":"כּוֹנָן","r":"K00307","html":"<div class=\"sense\"><i>, </i> pl. <a href=\"#\" data-headword=\"כּוֹנָנִית\">כּוֹנָנִים</a>, <a href=\"#\" data-headword=\"כּוֹנָנִית\">כּוֹנָנִין</a>, v. <a href=\"#\" data-headword=\"כּוֹנָנִית\">next w.</a></div>","alt":[]},"12170":{"h":"כּוֹנָנִית","r":"K00308","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <span dir=\"rtl\">כּוֹנָנִיּוֹת</span> (<span dir=\"rtl\">כון</span>, cmp. <a href=\"#\" data-headword=\"*כַּוָּון\">כַּוָּון</a>) [<i>arrangements</i>,] <i>chambers</i>, applied to the entrails arranged above each other. <span class=\"citation\">Ḥull. 56ᵇ</span> (ref. to <span dir=\"rtl\">ויכננך</span>, <span class=\"citation\">Deut. XXXII, 6</span>) <span dir=\"rtl\">שברא הקב&quot;ה כ׳ באדם וכ׳</span> the Lord has created carefully arranged chambers in man, one of which being disturbed man cannot live; <span class=\"citation\">Sifré Deut. 309</span> <span dir=\"rtl\">עשאך כנונים כנונים מבפנים וכ׳</span> (prob. to be read <a href=\"#\" data-headword=\"כּוֹנָנִית\">כּוֹנָנִים</a>); (Yalk. ib. 942 <span dir=\"rtl\">בסיסים</span>, v. <a href=\"#\" data-headword=\"בָּסִיס\">בָּסִיס</a>; cmp. <a href=\"#\" data-headword=\"כֵּן II\"><span dir=\"rtl\">כֵּן</span> II</a>). <span class=\"citation\">Yalk. Lev. 547</span> <a href=\"#\" data-headword=\"כּוֹנָנִית\">כּוֹנָנִין</a> (<span class=\"citation\">Lev. R. s. 14</span> <a href=\"#\" data-headword=\"קִינִּין\">קִינִּין</a>).</div>","alt":[]},"12171":{"h":"כּוֹנֵס","r":"K00309","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּנַס\">כָּנַס</a>) <i>receiver, the lower part of the winnowing shovel</i>. <span class=\"citation\">B. Mets. 105ᵃ</span>.—<span dir=\"rtl\">כ׳ משקה</span>, v. <a href=\"#\" data-headword=\"כָּנַס\">כָּנַס</a>.—<span class=\"citation\">B. Bath. 68ᵃ</span>. v. <a href=\"#\" data-headword=\"כִּינּוּס\">כִּינּוּס</a>.</div>","alt":[]},"12172":{"h":"כּוֹנְסָה","r":"K00310","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּנִיסָה\">כְּנִיסָה</a></div>","alt":[]},"12173":{"h":"כּוּנְשְׁרָא","r":"K00311","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּשֵׁר I\">כשר</a>, with inserted <a href=\"#\" data-headword=\"נ\">נ</a>, cmp. <a href=\"#\" data-headword=\"גּוּנְבְּרָא\">גּוּנְדְּרָא</a>) </div><div class=\"sense\"><b>1)</b>  (= h. <span dir=\"rtl\">כִּישׁוֹר</span>) <i>distaff</i> with the ball of flax. <span class=\"citation\">Targ. Prov. XXXI, 19</span> (ed. Lag. <a href=\"#\" data-headword=\"כּוּשְׁרָא I\">כּוּשְׁרָא</a>, cmp. <a href=\"#\" data-headword=\"כָּשׁוֹרָא\">כָּשׁוֹרָא</a>).</div><div class=\"sense\"><b>—2)</b>  (cmp. <span dir=\"rtl\">קשר</span>) <i>navel</i>. Ib. III, 8 (ed. Lag. <a href=\"#\" data-headword=\"כּוּנִישְׁרָא\">כּוּנִישְׁר׳</a>; Levita Var. <a href=\"#\" data-headword=\"כּוּשְׁרָא I\">כּוּשְׁרָא</a>; h. text <a href=\"#\" data-headword=\"שֵׁירוּתָא\">שָׁרּ׳</a>).</div>","alt":[]},"12174":{"h":"כַּוַּנְתָּא","r":"K00312","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּוָּנוּתָא\">כַּוָּנוּתָא</a></div>","alt":[]},"12175":{"h":"כּוּנְתָּא","r":"K00313","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">כתת</span>, with inserted <a href=\"#\" data-headword=\"נ\">נ</a>, cmp. <a href=\"#\" data-headword=\"כּוּנְשְׁרָא\">כּוּנְשְׁרָא</a>) [<i>that which is pounded</i>,] <i>spelt</i>. <span class=\"citation\">M. Kat. 13ᵇ</span> <span dir=\"rtl\">כי … אמר כ׳</span> when Rab Dimi came (to Babylonia) he defined <i>ḥelka</i> (v. <a href=\"#\" data-headword=\"חֶילְקָא II\"><span dir=\"rtl\">חֶילְקָא</span> II</a>) as <i>kunta</i>.—Pl. <span dir=\"rtl\">כּוּנְתַּיָּא</span>, <span dir=\"rtl\">(<span dir=\"rtl\">כּוּנָּתַיָּא</span>) <span dir=\"rtl\">כּוּנְתִּין</span></span>. <span class=\"citation\">Targ. Ex. IX, 32</span> <span dir=\"rtl\">כּוּנָּ׳</span> ed. Berl. (ed. Amst. <a href=\"#\" data-headword=\"כַּוְנָא\">כּוּנָ׳</a>; Y. <a href=\"#\" data-headword=\"כּוּנְתָּא\">כּוּנְתַּ׳</a>, Var. <span dir=\"rtl\">כָּנְתַּ׳</span>, <span dir=\"rtl\">כֻּנְתַּ׳</span>). <span class=\"citation\">Targ. Is. XXVIII, 25</span>; <span class=\"citation\">Targ. Ez. IV, 9</span> (ed. Wil. <span dir=\"rtl\">כּוּנְתִין</span>, oth. ed. <span dir=\"rtl\">כונתּ׳</span>).</div>","alt":["(כּוּנָּתָא)"]},"12176":{"h":"כּוֹס I","r":"K00314","html":"<div class=\"sense\"> c. (b. h.; or <span dir=\"rtl\">כנס</span>, v. Ges. Thes., a. Hebr. Dict.<sup>10</sup> s. v.) </div><div class=\"sense\"><b>1)</b> <i>cup</i>, also <i>a drink</i>. <span class=\"citation\">Tam. III, 4</span>. <span class=\"citation\">Erub. 65ᵇ</span> <span dir=\"rtl\">בג׳ … בכיסו בכוֹסוֹ בכעסו</span> man’s character is found out in three things, in his money bag, in his cup (when drinking) and in his anger; <span class=\"citation\">Der. Er. Zutta ch. V.—Keth. 75</span><span class=\"citation\">Keth. 75ᵇ</span>, sq., v. <a href=\"#\" data-headword=\"בָּדַק\">בָּדַק</a>. <span class=\"citation\">Pes. 105ᵃ</span> <span dir=\"rtl\">קדושה על הכ׳</span> sanctification (of the Sabbath or Holy Day) over a cup of wine. Ib. <span dir=\"rtl\">אם אין לו אלא כ׳ אחד</span> if he has only enough wine for one cup. <span class=\"citation\">Sabb. XIV, 3</span> <span dir=\"rtl\">כ׳ עיקרים</span>, v. <a href=\"#\" data-headword=\"עִיקָּר\">עִיקָּר</a>; a. fr.—Pl. <span dir=\"rtl\">כּוֹסוֹת</span>. <span class=\"citation\">Kel. XXII, 1</span>; Y. Ab. Zar. II, end, 42ᵃ, v. <a href=\"#\" data-headword=\"הַנָּחָה\">הַנָּחָה</a>. <span class=\"citation\">Men. 28ᵇ</span>, v. <a href=\"#\" data-headword=\"אֲלֶכְסַנְדְּרִי\">אֲלֶכְסַנְדְּרִי</a>. <span class=\"citation\">Pes. X, 1</span>, a. fr. <span dir=\"rtl\">ארבע כ׳</span> four cups of wine to be drunk on the Passover night; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>cavity.</i> <span class=\"citation\">Par. II, 5</span> (two black or white hairs) <span dir=\"rtl\">בתוך כ׳ אחד</span> in one follicle (v. <a href=\"#\" data-headword=\"גַּמָּא\">גוּמָּא</a>).—Pl. as ab. Ib. Y. Ab. Zar. l. c. <span dir=\"rtl\">הן כ׳ הן גומות</span> <i>kosoth</i> and <i>gummoth</i> mean the same things.—בֵּית הכּוֹסוֹת <i>the second stomach</i> of ruminants. <span class=\"citation\">Ḥull. III, 1</span> (<span class=\"citation\">42ᵃ</span>), v. comment. a. <a href=\"#\" data-headword=\"הַבְלִילָא\">הַבְלִילָא</a>. <span class=\"citation\">Ḥull. 49ᵃ</span>; <span class=\"citation\">50ᵇ</span> <span dir=\"rtl\">עובי בית הכ׳</span> the folds (thick walls) of the etc.; a. fr.</div>","alt":[]},"12177":{"h":"*כּוֹס II","r":"K00315","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">כסס</span>, v. <a href=\"#\" data-headword=\"כֵּיסָא\">כֵּיסָא</a>) <i>thorn</i>.—Pl. <span dir=\"rtl\">כּוֹסִים</span>. Pesik. B’shall. p. 92ᵃ (<span class=\"citation\">Y. Maasr. III, 50ᵈ</span> bot. <span dir=\"rtl\">קוצין</span>), v. <a href=\"#\" data-headword=\"כָּסַח\">כָּסַח</a>.</div>","alt":[]},"12178":{"h":"כּוֹס III","r":"K00316","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָכַס\">נָכַס</a>, <a href=\"#\" data-headword=\"נְכַס\">נְכַס</a> a. <a href=\"#\" data-headword=\"כְּסַס\"><a href=\"#\" data-headword=\"כְּסַס\">כְּסַס</a>.</a></div>","alt":["כּוּס"]},"12179":{"h":"כּוֹסָא","r":"K00317","html":"<div class=\"sense\"><i>night-bird, owl</i>, v. <a href=\"#\" data-headword=\"בָּאוָת\">בָּאוָת</a>.</div>","alt":[]},"12180":{"h":"כּוֹסָא ²","r":"K00318","html":"<div class=\"sense\"><i>cup</i>, v. <a href=\"#\" data-headword=\"כַּסָּא I\">כַּסָּא</a>.</div>","alt":[]},"12181":{"h":"כּוֹסָאתָא","r":"K00319","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*כּוּסְתָּא\">כּוּסְתָּא</a></div>","alt":[]},"12182":{"h":"כּוּסְבָּר","r":"K00320","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. Löw Pfl. p. 209) <i>coriander</i> (v. Sm. Ant. s. v. Coriandrum). <span class=\"citation\">Kil. I, 2</span> <span dir=\"rtl\">כ׳ וכוּסְבַּר שדה וכ׳</span> (garden) coriander and field (wild) coriander … are not heterogeneous plants. <span class=\"citation\">Shebi. IX, 1</span>. <span class=\"citation\">Dem. I, 1</span>. Y. ed. <span dir=\"rtl\">כוס׳</span> (Mish. a. Bab. ed. <a href=\"#\" data-headword=\"כִּיסְנִין\">כֻּסְ׳</a>); a. fr.—Y. ib. 21ᵈ top, v. next w.—<span class=\"citation\">Tosef. B. Bath. V, 6</span> <span dir=\"rtl\">כוסברת בפלפלין</span> ed. Zuck. (Var. <span dir=\"rtl\">כסבורא</span>; corr. acc.) he who adulterates pepper by admixing coriander; <span class=\"citation\">Koh. R. to VI, 1</span> <a href=\"#\" data-headword=\"כַּרְשִׁנֵּי\">כרשנים</a> (corr. acc.).</div>","alt":["כּוּסְבָּרָה","כּוּסְבֶּרֶת"]},"12183":{"h":"כּוּסְבַּר","r":"K00321","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Targ. Y. Ex. XVI, 31</span>; <span class=\"citation\">Targ. Y. Num. XI, 7</span> (h. text <a href=\"#\" data-headword=\"גד\">גד</a>).—Y. Dem. I, 21ᵈ top <span dir=\"rtl\">כוסבר</span>(<a href=\"#\" data-headword=\"ה\">ה</a>) <a href=\"#\" data-headword=\"כּוּסְבַּר\">כוסברתא</a> <i>kusbar</i> (of the Mish.) is <i>kusbarta</i>. <span class=\"citation\">Ib.</span> (derisive play on the word) [read:] <span dir=\"rtl\">כּוּס בְּרָה כּוּס בְּרַתָּה וכ׳</span> ‘chew the son, chew the daughter’, who classed thee among the spices?—<span class=\"citation\">Ab. Zar. 10ᵇ</span> (expressing an advice symbolically = <span dir=\"rtl\">כוס ברתא</span> put the daughter to death, v. <a href=\"#\" data-headword=\"נְכַס\">נְכַס</a>; v. <a href=\"#\" data-headword=\"גַּרְגִּילָא\">גַּרְגִּילָא</a>).</div>","alt":["כּוּסְבּרָה","כּוּסְבַּרְתָּא"]},"12184":{"h":"כוסטריינים","r":"K00322","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to VI, 11</span>; <a href=\"#\" data-headword=\"קוסטנרות\">קוסטרינוס</a> <span class=\"citation\">Lev. R. s. 35</span>, a corrupt. of <i>quaestionarius, executioner</i>; v. <a href=\"#\" data-headword=\"קוּסְטִינָר\">קוּסְטִינָר</a>.</div>","alt":[]},"12185":{"h":"כוסיא","r":"K00323","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. Ex. XXII, 8</span>, a. e., v. <a href=\"#\" data-headword=\"בִּסְיָא\">בִּסְיָא</a></div>","alt":[]},"12186":{"h":"כוסיות","r":"K00324","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Mets. X, 6</span>, read: <a href=\"#\" data-headword=\"כִּיסִּיּוֹת\">כִּיסָּיוֹת</a>, v. <a href=\"#\" data-headword=\"כִּסֵּא\">כִּסֵּא</a></div>","alt":[]},"12187":{"h":"כּוֹסֵילְתָּא","r":"K00325","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כֶּסֶל\">כסל</a>, v. <a href=\"#\" data-headword=\"כֶּסֶל\">כֶּסֶל</a>; cmp. P. Sm. s. v. 1786, sq.; cmp. P. Sm. s. v. 1786, sq.) </div><div class=\"sense\"><b>1)</b> <i>the space between the shoulders</i> (interscapilium), <i>shoulder-blade</i>. <span class=\"citation\">Taan. 21ᵇ</span> [read:] <span dir=\"rtl\">לבושא דיתיב ביה קרנא והוה בזיעא בי כ׳</span> (v. Var. in Rabb. D. S. a. l. note) a garment in which there was placed (fastened) a cup (for receiving the blood) which (garment) was cut in at the shoulder (so that the operator could let blood standing behind the female patient); [Ar. <span dir=\"rtl\">לבושא דאית ליה ביזעי ביזעי באפי כ׳</span> a garment in which there were several incisions to correspond to the shoulder-blade.]</div><div class=\"sense\"><b>—2)</b> <i>the lancet for blood-letting</i>. <span dir=\"rtl\">ריבדא דכ׳</span> the puncture made by the lancet. <span class=\"citation\">Sabb. 129ᵃ</span> <span dir=\"rtl\">עד דנפיק מר׳ דכ׳</span> until the puncture was healed up. <span class=\"citation\">Snh. 93ᵇ</span>. <span class=\"citation\">Macc. 21ᵃ</span>. <span class=\"citation\">Keth. 39ᵇ</span> <span dir=\"rtl\">כי ר׳ דכ׳</span> as much pain as is caused by the puncture of the lancet. <span class=\"citation\">Nidd. 67ᵃ</span> <span dir=\"rtl\">הני רבדי דכ׳</span></div>","alt":[]},"12188":{"h":"כּוּסְכּוּס","r":"K00326","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"נָכַס\">נָכַס</a></div>","alt":[]},"12189":{"h":"כּוּסְלָא","r":"K00327","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּסִילָא\">כְּסִילָא</a></div>","alt":[]},"12190":{"h":"כּוּסְּמִים","r":"K00328","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>spelt.</i> <span class=\"citation\">Ḥall. I, 1</span>. <span class=\"citation\">Pes. II, 5</span>. <span class=\"citation\">Ib. 35ᵃ</span> כ׳ מין חטים הוא <i>Kuss’min</i> is a species of wheat. <span class=\"citation\">Y. Ḥall. I, 57ᵇ</span> top (ref. to <span class=\"citation\">Is. XXVIII, 25</span>) <span dir=\"rtl\">כּוּסֶּמֶת זה הכ׳</span> <i>kussemeth is spelt</i>; a. fr.</div>","alt":["כּוּסְּמִין"]},"12191":{"h":"כּוּסֶּמֶת","r":"K00329","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"כּוּסְּמִים\">preced.</a></div>","alt":[]},"12192":{"h":"כּוּסְפָּא","r":"K00330","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּסַף I\">כְּסַף</a>) <i>paring, husk</i>; <span dir=\"rtl\">כ׳ דתמרי</span> <i>substance of ground dates</i> after the juice is pressed out. <span class=\"citation\">Taan. 24ᵇ</span> <span dir=\"rtl\">אכ׳ דת׳ קיימי דקא מזדבן</span> they stand around a mass of ground dates which is to be sold (there being a famine). <span class=\"citation\">Sabb. 50ᵇ</span> <span dir=\"rtl\">כ׳ דיסמין</span> puppy pomace flavored with jasmin (used for a lotion).</div>","alt":[]},"12193":{"h":"כּוּסְפָן","r":"K00331","html":"<div class=\"sense\"> m. h. <a href=\"#\" data-headword=\"כּוּסְפָּא\">same</a> (collect. noun). <span class=\"citation\">Ab. Zar. 38ᵇ</span> <span dir=\"rtl\">הכ׳ של נכרים וכ׳</span> (Rashi: <span dir=\"rtl\">הכּוּסְפִין</span>) pomace of dates belonging to gentiles which was boiled (brewed a second time) in a large caldron.</div>","alt":[]},"12194":{"h":"*כּוּסְתָּא","r":"K00332","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (an adapt. of ξέστης, by confusion with <a href=\"#\" data-headword=\"כּוֹס I\">כּוֹס</a>, <a href=\"#\" data-headword=\"כַּסָּא I\">כַּסָּא</a>) <i>kusta</i>, a liquid measure. <span class=\"citation\">Sabb. 109ᵇ</span> <span dir=\"rtl\">חד כ׳ דשיכרא</span> (Ms. O. <a href=\"#\" data-headword=\"כִּיסְתָא I\">כִּיסְתָּא</a>) one <i>k</i>. of beer.—Pl. <span dir=\"rtl\">כּוּסְיָתָא</span> (fem.). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">חמש עשר כ׳</span> Ms. M. (ed. <span dir=\"rtl\">חמשא כוסתא</span>, Ms. O. <span dir=\"rtl\">כסתתא</span>; Rashi <a href=\"#\" data-headword=\"כּוֹסָאתָא\">כּוֹסָאתָא</a>, v. Rabb. D. S. a. l. note). [Oth. opin. <a href=\"#\" data-headword=\"*כּוּסְתָּא\">כּוֹסְתָא</a> fem. form of <a href=\"#\" data-headword=\"כּוֹסָא\">כּוֹסָא</a>, v. <a href=\"#\" data-headword=\"כַּסָּא I\">כַּסָּא</a>.]</div>","alt":[]},"12195":{"h":"כּוּף I","r":"K00333","html":"<div class=\"sense\"><i>to bend, force</i>, v. <a href=\"#\" data-headword=\"כָּפַף\">כָּפַף</a> a. <a href=\"#\" data-headword=\"כפי\"><a href=\"#\" data-headword=\"כפי\">כָּפָה</a>.</a></div>","alt":[]},"12196":{"h":"כּוּף","r":"K00334","html":"<div class=\"sense\">, <i>to bend</i> (act. a. neuter verb).—Part. <a href=\"#\" data-headword=\"כָּאִיף\">כָּאִיף</a>, <span dir=\"rtl\">כָּיִף</span>, <span dir=\"rtl\">כָּיֵיף</span>. <span class=\"citation\">Targ. Ps. LVII, 7</span>. <span class=\"citation\">Targ. Job XL, 17</span> Ms. (ed. Lag. <a href=\"#\" data-headword=\"כְּפַף\">כפיף</a>; ed. Wil. <a href=\"#\" data-headword=\"כָּפַף\">כָּפַף</a>, Var. <span dir=\"rtl\">כפין</span>).—<span class=\"citation\">Snh. 36ᵃ</span> <span dir=\"rtl\">מֵיכַף הוה כָּיֵיף ליה לרב וכ׳</span> he bent (yielded preference) to R. A.; <span class=\"citation\">Gitt. 59ᵇ</span> <span dir=\"rtl\">מיכף הוו כָיְיפֵי ליה</span>. <span class=\"citation\">Pes. 51ᵃ</span> <span dir=\"rtl\">אנן כַּיְיפִינָן להו</span> we pay reverence to them. <span class=\"citation\">Sabb. 77ᵇ</span>, v. <a href=\"#\" data-headword=\"כְּפַף\">כְּפַף</a>.—<span class=\"citation\">Ḥag. 16ᵃ</span>, v. <a href=\"#\" data-headword=\"יֵצֶר ²\">יִצְרָא</a>. <span class=\"citation\">Snh. 107ᵃ</span>; <span class=\"citation\">Yalk. Ps. 765</span> <span dir=\"rtl\">אי … למִיכְפְּיֵיה … הוה כַיְיפִינָא ליה</span> if I had desired to bend my passion, I should have succeeded. <span class=\"citation\">B. Bath. 4ᵃ</span> דכייף ליה וכ׳ Ms. M. (ed. <a href=\"#\" data-headword=\"כְּפִי\">אכפי</a>, <span dir=\"rtl\">מיכפי</span>) he bends the pegs of the wall inside, … outside, v. <a href=\"#\" data-headword=\"חָזִית\">חָזִית</a>.</div>","alt":[]},"12197":{"h":"כּוּף II","r":"K00335","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּפַף\">כְּפַף</a>) <i>cover, basket</i>. <span class=\"citation\">Y. Erub. VII, beg. 24ᵇ</span> <span dir=\"rtl\">למיכבש עלוי כ׳</span> to press a cover over it.</div>","alt":[]},"12198":{"h":"כּוּפָּה","r":"K00336","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּיפָּה\">כִּיפָּה</a>. [Pesik. Asser, p. 99ᵇ <span dir=\"rtl\">כבוש כ׳</span>, v. <a href=\"#\" data-headword=\"כּוּבָּא I\"><span dir=\"rtl\">כּוּבָּא</span> I</a>.]</div>","alt":[]},"12199":{"h":"כּוּפָּח","r":"K00337","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּפַח\">כָּפַח</a>) [<i>a pouched receptacle</i>,] <i>a small stove, brazier</i>. <span class=\"citation\">Sabb. III, 2</span>. <span class=\"citation\">Ib. 38ᵇ</span> <span dir=\"rtl\">כ׳ מקום שפיתת וכ׳</span> a <i>kuppaḥ</i> is a stove which has room only for one pot. <span class=\"citation\">Men. V, 9</span> <span dir=\"rtl\">מאפה כ׳</span> what is baked in a brazier. <span class=\"citation\">Kel. V, 2</span> <span dir=\"rtl\">הכ׳ עשאו לאפייה … לבישול</span> a <i>k</i>. made for baking, … for cooking.</div>","alt":[]},"12200":{"h":"כּוּפְיָא","r":"K00338","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Kufia</i>, name of <i>afish</i>, supposed to be identical with <i>colias</i>, v. <a href=\"#\" data-headword=\"אִסְפָּנִי\">אִסְפָּנִי</a>. <span class=\"citation\">Pes. 39ᵃ</span> <span dir=\"rtl\">מרירתא דכ׳</span></div>","alt":[]},"12201":{"h":"כופיח","r":"K00339","html":"<div class=\"sense\">, Y. Keth. VII, end, 31ᵈ, read: <a href=\"#\" data-headword=\"כִּיפֵּחַ\">כִּיפֵּחַ</a>.</div>","alt":[]},"12202":{"h":"כופיתא","r":"K00340","html":"<div class=\"sense\">, <span class=\"citation\">B. Mets. 73ᵇ</span>, v. <a href=\"#\" data-headword=\"טְפִיתָא\">טְפִיתָא</a>.—[<span class=\"citation\">Snh. 98ᵇ</span>, v. <a href=\"#\" data-headword=\"כֵּיפְתָא\">כֵּיפְתָא</a>; <span class=\"citation\">B. Bath. 73ᵇ</span>, v. <a href=\"#\" data-headword=\"כַּפּוּתָא\">כַּפּוּתָא</a>.]</div>","alt":[]},"12203":{"h":"כּוּפְלָא","r":"K00341","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֵּיפְלָא\">כֵּיפְלָא</a></div>","alt":[]},"12204":{"h":"כּוּפְנִי","r":"K00342","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּפְנִיתָא\">כָּפְנִיתָא</a></div>","alt":["כּוּפְנִיתָא"]},"12205":{"h":"כּוֹפֵר","r":"K00343","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּפַר\">כָּפַר</a></div>","alt":[]},"12206":{"h":"כּוֹפֶר","r":"K00344","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>cyprus flower</i> (v. Löw Pfl. p. 212). <span class=\"citation\">Shebi. VII, 6</span> והכו׳ Ms. M. (ed. <span dir=\"rtl\">והכפ׳</span>); <span class=\"citation\">Nidd. 8ᵃ</span>.—Chald. <a href=\"#\" data-headword=\"כְּפוֹרָא I\">כְּפוֹרָא</a>.</div>","alt":["כֹּפֶר I"]},"12207":{"h":"כּוֹפֶר II","r":"K00345","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>indemnity, fine</i>; [<i>atonement</i>.] <span class=\"citation\">B. Kam. IV, 5</span> <span dir=\"rtl\">משלם כ׳</span> must pay indemnity for a life lost. <span class=\"citation\">Ib. 40ᵃ</span> <span dir=\"rtl\">חצי כ׳</span> half the assessed fine. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כ׳ שלם אמר רחמנא וכ׳</span> the law (<span class=\"citation\">Ex. XXI, 30</span>) speaks of a full indemnity (as an atonement) &amp;c., v. <a href=\"#\" data-headword=\"כּוּפְרָא I\">next w.</a>; a. fr.—<span class=\"citation\">Treat. Sof’rim XXI, 4</span> <span dir=\"rtl\">לשם כ׳</span> as an obligatory ransom, opp. <span dir=\"rtl\">לשם נדבה</span>.—Pl. <span dir=\"rtl\">כּוֹפְרִין</span>. B. Kam. l. c. <span dir=\"rtl\">חייבי כ׳ מאי</span> how is it about seizing the property of those bound to pay indemnities?; a. fr.</div>","alt":[]},"12208":{"h":"כּוּפְרָא I","r":"K00346","html":"<div class=\"sense\"><span class=\"citation\">B. Kam. 40ᵃ</span> <span dir=\"rtl\">כ׳ כפרה</span> the fine is intended for an atonement (like a sacrifice); <span dir=\"rtl\">כ׳ ממונא</span> it is an indemnification; a. fr.</div>","alt":[]},"12209":{"h":"כּוּפְרָא II","r":"K00347","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>pitch</i>. <span class=\"citation\">Targ. O. Gen. VI, 14</span>.—<span class=\"citation\">Arakh. 19ᵃ</span> <span dir=\"rtl\">באתרא דתקלי כ׳</span> where they sell pitch by the weight. <span class=\"citation\">Gitt. 69ᵇ</span> <span dir=\"rtl\">משחא דכ׳</span> oil of pitch (tar). <span class=\"citation\">Sabb. 74ᵇ</span> <span dir=\"rtl\">האי מאן דארתח כ׳</span> he who heats pitch (on the Sabbath). <span class=\"citation\">B. Mets. 23ᵇ</span>. <span class=\"citation\">Ib. 70ᵃ</span> top <span dir=\"rtl\">בני כ׳</span> <i>sailors</i> (‘tars’).—Pl. <a href=\"#\" data-headword=\"כּוּפְרִי I\">כּוּפְרֵי</a>. <span class=\"citation\">Sabb. 67ᵃ</span> <span dir=\"rtl\">ז׳ כ׳ מז׳ ארכי</span> seven kinds of pitch taken from seven ships. [<span class=\"citation\">B. Kam. 101ᵃ</span> top. v. <a href=\"#\" data-headword=\"כַּפְרָא\">כַּפְרָא</a>.]</div>","alt":[]},"12210":{"h":"כּוּפְרָא III","r":"K00348","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"בְּקִיעִין\">כפר</a>) <i>the inflorescence of palms, a spike covered with numerous flowers, and enveloped by one or more sheathing bracts called spathes</i> (v. Cyclop. Brit. s. v. Palm, a. Löw Pfl. p. 118); <i>the date-berry in its early stage</i>. <span class=\"citation\">Pes. 56ᵃ</span> <span dir=\"rtl\">מנהי כ׳ דיכרא וכ׳</span> (for fertilization) they put the male flower (scatter the pollen) over the female tree. <span class=\"citation\">B. Kam. 59ᵇ</span> <span dir=\"rtl\">האי מאן דקץ כ׳ וכ׳</span> if one cuts a date flower what damages has he to pay?—<span class=\"citation\">Succ. 32ᵃ</span> <span dir=\"rtl\">ואימא כ׳</span> perhaps (<span class=\"citation\">Lev. XXIII, 40</span>) the spike is meant?—<span class=\"citation\">Ber. 36ᵇ</span> <span dir=\"rtl\">בכ׳</span> in the early stage of the berry.—Pl. <a href=\"#\" data-headword=\"כּוּפְרִי I\">כּוּפְרֵי</a>. <span class=\"citation\">Pes. 52ᵇ</span> (Ms. M. sing.), v. <a href=\"#\" data-headword=\"כָּפְנִי\">כָּפְנִי</a>.—<span class=\"citation\">Keth. 10ᵃ</span> <span dir=\"rtl\">אסבוהו כ׳</span>, v. <a href=\"#\" data-headword=\"סְבָא\">סְבָא</a>. [<span class=\"citation\">Y. Shebi. II, 34ᵃ</span> bot. <span dir=\"rtl\">כופריא</span>, v. next w.]</div>","alt":[]},"12211":{"h":"כּוּפְרָאָה","r":"K00349","html":"<div class=\"sense\">—Pl. <a href=\"#\" data-headword=\"כּוּפְרָא I\">כּוּפְרָאֵי</a>. <span class=\"citation\">Y. Shebi. II, 34ᵃ</span> bot. <span dir=\"rtl\">בצליא כ׳</span> R. S. to ib. II, 9 (ed. <span dir=\"rtl\">כופריא</span>, corr. acc.) wild onions, v. <a href=\"#\" data-headword=\"כּוּפְרִי I\">כּוּפְרִי</a>.</div>","alt":[]},"12212":{"h":"כּוּפְרָה","r":"K00350","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Kufra</i>. <span class=\"citation\">Y. Shek. V, 48ᵈ</span> bot.; <span class=\"citation\">Y. Peah VIII, 21ᵃ</span> <a href=\"#\" data-headword=\"כַּפְרָא\">כַּפְרָה</a>.—<span class=\"citation\">Y. Meg. I, 70ᵃ</span> bot. <a href=\"#\" data-headword=\"כִּיפְרָא\">כִּיפְרָא</a> (near Tiberias); a. e.</div>","alt":[]},"12213":{"h":"כּוּפְרִי I","r":"K00351","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"כּוֹפֶר\">כְּפָר</a>) <i>belonging to the village, wild</i>.—כלב כ׳ <i>village dog, ferocious dog</i>. <span class=\"citation\">Tosef. Kil. V, 8</span> <span dir=\"rtl\">כלב כ׳ וכ׳</span> a <i>Kuf’ri</i> dog is a species of wild beasts (not a domestic animal). <span class=\"citation\">Kil. I, 6</span> <span dir=\"rtl\">כלב הכ׳ והשועל וכ׳</span> the wild dog and the jackal … are heterogeneous <a href=\"#\" data-headword=\"כִּלְאַיִם\">(כלאים</a>). Y. ib. I, 27ᵃ bot. (not <span dir=\"rtl\">כופרין</span>). <span class=\"citation\">Lam. R. to I, 4</span>; a. e.—<span dir=\"rtl\">בצל כ׳</span> wild onion, opp. to <span dir=\"rtl\">ב׳ בני המדינה</span> townsmen’s (garden) onion. <span class=\"citation\">Ned. 26ᵇ</span>; <span class=\"citation\">66ᵃ</span> <span dir=\"rtl\">הכ׳ יפה וכ׳</span> (Ar. <span dir=\"rtl\">הכּוּפְרִים יפין</span>) the wild onion is good for the heart (stomach); Tosef. ib. V, 1 <span dir=\"rtl\">הכופרין יפה</span> (corr. acc.), opp. <span dir=\"rtl\">בני בצלים</span> (Var. <a href=\"#\" data-headword=\"שְׁאַר I\">שאר</a>) small onions.—Pl. <span dir=\"rtl\">כּוּפְרִיִּים</span>, <a href=\"#\" data-headword=\"כּוּפְרִי I\">כּוּפְרִים</a>, <a href=\"#\" data-headword=\"כּוּפְרִי I\">כּוּפְרִין</a>. <span class=\"citation\">Ter. II, 5</span>, v. <a href=\"#\" data-headword=\"*פּוֹלִיטִיקִין\">פוליטיקין</a>. <span class=\"citation\">Tosef. B. Kam. VIII, 17</span>. <span class=\"citation\">Tosef. Ab. Zar. II, 3</span>. Tosef. Ned. l. c.; Ned. l. c., v. supra; a. e.</div>","alt":["כּוּפְרִית"]},"12214":{"h":"כּוּפְרִי II","r":"K00352","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><b>1)</b>  prob. <i>Cyprus</i>, v. <a href=\"#\" data-headword=\"זְפִירִין\">זְ֗פִירִין</a>. <span class=\"citation\">Yalk. Num. 701</span>.</div><div class=\"sense\"><b>—2)</b>  v. <a href=\"#\" data-headword=\"כַּפְרִי\">כַּפְרִי</a></div>","alt":[]},"12215":{"h":"כּוּפְרִיתָא","r":"K00353","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּבָּרִיתָא\">כַּבָּרִיתָא</a></div>","alt":[]},"12216":{"h":"כּוּפְרָנָא","r":"K00354","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּפְרָנָא\">כַּפְרָנָא</a></div>","alt":[]},"12217":{"h":"*כּוֹפֶשׁ","r":"K00355","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כְּפִישָׁה\">כְּפִישָׁה</a>) <i>basket</i> in which olives are kept for softening. <span class=\"citation\">Toh. IX, 5</span> Var. (ed. <a href=\"#\" data-headword=\"כּוֹתֶשׁ\">כּוֹתֶשׁ</a>); <span class=\"citation\">Tosef. ib. X, 10</span> <a href=\"#\" data-headword=\"כִּיפֵּשׁ\">כיפש</a> (R. S. to Toh. l. c. <a href=\"#\" data-headword=\"כּוֹתֶשׁ\">כותש</a>).</div>","alt":[]},"12218":{"h":"כּוּפְשָׁנָא","r":"K00356","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <a href=\"#\" data-headword=\"כּוּפְשָׁנָא\">כּוּפְשָׁנֵי</a> (v. <a href=\"#\" data-headword=\"*כּוֹפֶשׁ\">preced.</a>) a species of <i>tamed doves</i> (<i>kept in coops</i>). <span class=\"citation\">Ḥull. 62ᵇ</span> <span dir=\"rtl\">צוצייני כ׳</span> ed. K. of Zeizûn(?); Ar. <span dir=\"rtl\">כּוּבְשָׁנֵי דצ׳</span> (v. <a href=\"#\" data-headword=\"כְּבַשׁ\">כְּבַשׁ</a>).</div>","alt":[]},"12219":{"h":"כּוֹפֶת","r":"K00357","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"כפי\">כָּפָה</a>, cmp. <span dir=\"rtl\">מטה כפויה</span> s. v. <a href=\"#\" data-headword=\"כפי\">כָּפָה</a>) [<i>an inverted vessel</i>,] <i>a low seat, a block with a concave top to sit upon; bolster, stool.</i> <span class=\"citation\">Kel. XXII, 9</span>. <span class=\"citation\">Tosef. Sabb. XIII</span> (<span class=\"citation\">XIV), 17</span> <span dir=\"rtl\">וכ׳ חקוק בין כ׳</span> (ed. Zuck. <span dir=\"rtl\">כרפ׳</span>, Var. <span dir=\"rtl\">כיפ׳</span>, corr. acc.) a block whether caved out &amp;c. <span class=\"citation\">Kel. XX, 5</span> <span dir=\"rtl\">כ׳ שקבעו וכ׳</span> if one put a stool in the rubble of a wall (v. <a href=\"#\" data-headword=\"נִדְבָּךְ\">נִדְבָּךְ</a>; <span class=\"citation\">Tosef. Kel. B. Mets. XI, 6</span> <span dir=\"rtl\">כסא … בבנין</span>). <span class=\"citation\">Tosef. Kel. B. Bath. II, 1</span> [read:] <span dir=\"rtl\">כ׳ חלקה שאין בה וכ׳</span> (v. R. S. to <span class=\"citation\">Kel. XXII, 9</span>; ed. Zuck. <span dir=\"rtl\">כיפת חלק</span>) a plain (not shaped) block which has not the height of &amp;c. Y. Pes. VII, 28ᵈ bot. <span dir=\"rtl\">בצק שעשאו כ׳</span> a mass of hardened dough which one made into a seating block. Ohol. XI, 3 <span dir=\"rtl\">וכ׳ עבה</span> a thick carpet-cover of a seating block (cmp. <span class=\"citation\">Tosef. Kel. B. Mets. XI, 10</span>). <span class=\"citation\">Y. Erub. VII, 24ᵇ</span> bot. <span dir=\"rtl\">כ׳ שהדריגוה</span> a seating block into which steps were cut. <span class=\"citation\">Tosef. Ohol. XII, 2</span> שתי … וכ׳ ע&quot;ג האבן R. S. to ib. XI, 3 (ed. Zuck. a. oth. <span dir=\"rtl\">וכי׳</span>) two stones above one another and a seating block on top &amp;c.; a. e.—Pl. <span dir=\"rtl\">כּוֹפְתִין</span>. Ib. in R. S. to Ohol l. c. (ed. Zuck. a. oth. <a href=\"#\" data-headword=\"כָּפִית\">כָּפִיתִין</a>).</div>","alt":[]},"12220":{"h":"כּוּפְתָּא I","r":"K00358","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"כּוֹפֶת\">same</a>. <span class=\"citation\">Sabb. 77ᵇ</span> (phon. etymol.) <span dir=\"rtl\">כ׳ כ̇וף̇ ות̇יב</span> invert and sit on it. invert and sit on it.</div><div class=\"sense\"><b>—2)</b> <i>prisoner’s stocks</i>. <span class=\"citation\">Targ. Jer. XX, 2</span> Ar. (h. text <span dir=\"rtl\">מהפכת</span>), v. <a href=\"#\" data-headword=\"כֵּיפְתָא\">כֵּיפְתָא</a>. [<span class=\"citation\">B. Bath. 73ᵇ</span>, v. <a href=\"#\" data-headword=\"כַּפּוּתָא\">כַּפּוּתָא</a>.]</div>","alt":[]},"12221":{"h":"כּוּפְתָּא II","r":"K00359","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"כְּפִיפָה\">כְּפִיפָה</a>, <i>basket</i>. <span class=\"citation\">Gitt. 32ᵃ</span> <span dir=\"rtl\">קניא בכ׳</span> the reed in the basket.</div>","alt":[]},"12222":{"h":"כּוּפְתָּא III","r":"K00360","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּפַת\">כְּפַת</a>) <i>being tied</i> on the altar (= h. <a href=\"#\" data-headword=\"עֲקֵדָה\">עֲקֵדָה</a>). <span class=\"citation\">Targ. Job. III, 18</span> (<span class=\"citation\">19</span>).</div>","alt":[]},"12223":{"h":"כְּוֵץ","r":"K00361","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"קָוַץ\">קָוַץ</a>, <a href=\"#\" data-headword=\"גָּוַע\">גָּוַע</a>) <i>to curl, shrink</i>. <span class=\"citation\">Sabb. 20ᵇ</span> <span dir=\"rtl\">צמר מִכְוַוץ כָּוֵויץ</span> wool (if used as a wick) curls. <span class=\"citation\">Nidd. 3ᵃ</span> <span dir=\"rtl\">מוך … מכוץ כויץ</span> the lint … shrinks (and leaves room for the blood to pass). <span class=\"citation\">Succ. 23ᵇ</span> <span dir=\"rtl\">כיון דמייתא כַּוְוצָא</span> when the animal is dead, the body shrinks. <span class=\"citation\">Ḥull. 43ᵇ</span> <span dir=\"rtl\">כל שחותכו וכויץ</span> that portion of the gullet which shrinks when you cut it. <span class=\"citation\">Ib. 46ᵇ</span>, v. infra.</div><div class=\"sense\"><b>Pa. כַּוֵּוץ</b> <div class=\"sense\"><i>to cause to shrink</i>. <span class=\"citation\">Sabb. 19ᵃ</span> <span dir=\"rtl\">וכַוְּוצֵיה</span> for he made it shrink (by using too hot water). <span class=\"citation\">Ḥull. 46ᵇ</span>; <span class=\"citation\">47ᵇ</span> [read:] <span dir=\"rtl\">בחמימי לא דמְכַוְּוצֵי</span> not in boiling water, for it causes the lungs to shrink (Ar. ed. Koh. <span dir=\"rtl\">בקרירי לא דכווצא</span> not in cold water, for it will contract, v. <a href=\"#\" data-headword=\"טְרַשׁ I\"><span dir=\"rtl\">טְרַשׁ</span> I</a>).</div></div>","alt":["כְּוֵיץ","כְּוַוץ"]},"12224":{"h":"כּוֹר","r":"K00362","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"כָּרָה\">כָּרָה</a>) [<i>a heap</i>,] <i>Khor</i>, a measure of capacity, <a href=\"#\" data-headword=\"כֵּיפֵי\">בֵּית כ׳</a> (or <a href=\"#\" data-headword=\"כ׳\">כ׳</a>, sub. <span dir=\"rtl\">בית</span>) <i>an area requiring a Khor of seed</i>. <span class=\"citation\">B. Mets. 105ᵇ</span> <span dir=\"rtl\">כ׳ זרע</span> a field requiring a <i>Khor</i> of seed; <span dir=\"rtl\">כ׳ תבואה</span> a field yielding a <i>Khor</i> of grain. Ib. <span dir=\"rtl\">ד׳ סאין לכ׳</span> four S’ah of seed for a Beth Khor of land, v. <a href=\"#\" data-headword=\"נְפִילָה\">נְפִילָה</a>. <span class=\"citation\">B. Bath. VII, 1</span>; <span class=\"citation\">2</span> <span dir=\"rtl\">בית כ׳</span>. <span class=\"citation\">Ib. 104ᵃ</span> <span dir=\"rtl\">נותן … לכל כ׳ וכ׳</span> we allow a surplus or deficit of seven Kab and a half for each Beth Khor; a. fr.—<i>Du.</i> <span dir=\"rtl\">כּוֹרַיִים</span>, <a href=\"#\" data-headword=\"כורים\">כּוֹרַיִם</a>. <span class=\"citation\">Ib.ᵇ</span>—Ohol. VIII, 3; <span class=\"citation\">Kel. XV, 1</span> <span dir=\"rtl\">ארבעים סאה בלח שהן כ׳ ביבש</span> forty S’ah in liquid measure which is equal to two Khor in dry measure.</div>","alt":[]},"12225":{"h":"כּוֹר ²","r":"K00363","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Lev. XXVII, 16</span> (h. text <span dir=\"rtl\">חֹמֶר</span>); a. fr.—<span class=\"citation\">B. Mets. 105ᵃ</span>, v. <a href=\"#\" data-headword=\"אַלְלָא\">אַלְלָא</a>.—Pl. <span dir=\"rtl\">כּוֹרִין</span>, <a href=\"#\" data-headword=\"כּוֹרֵם\">כּוֹרֵי</a>. [<span class=\"citation\">Targ. Y. Ex. VIII, 10</span> כורין Ar. <i>heaps</i>; ed. <a href=\"#\" data-headword=\"כַּרְוָון\">כַּרְוַון</a>, v. <a href=\"#\" data-headword=\"כַּרְיָא I\">כַּרְיָא</a>.]—<span class=\"citation\">Targ. I Kings V, 25</span>; a. fr.—B. Mets. l. c.—Y. ib. IV, 10ᶜ bot. <span class=\"citation\">Sabb. 35ᵃ</span>, v. <a href=\"#\" data-headword=\"חַלְתָּא\">חַלְתָּא</a>; a. fr.—[<span class=\"citation\">Ḥull. 62ᵇ</span> בי כודי Ar., Var. <a href=\"#\" data-headword=\"כירי\">כירי</a>, between <i>heaps</i> (ed. <a href=\"#\" data-headword=\"*כַּרְבֵּק\">כַּרְבֵּי</a>).]—V. <a href=\"#\" data-headword=\"כּוֹרִיתָא\">כּוֹרִיתָא</a>.</div>","alt":["כּוֹרָא"]},"12226":{"h":"כּוּר I","r":"K00364","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> מִלְּתָא דְּכ׳ <i>Fort of Khur</i>, a northern Palestinean border-town. <span class=\"citation\">Tosef. Shebi. IV, 11</span> Var. (ed. Zuck. <span dir=\"rtl\">מומתא דבור</span>); Y. ib. VI, 36ᶜ <span dir=\"rtl\">מילתא דביר</span>; <span class=\"citation\">Sifré Deut. 51</span> <span dir=\"rtl\">(<span dir=\"rtl\">במותה דביריין</span>) <span dir=\"rtl\">כמותה דכריין</span></span>; <span class=\"citation\">Yalk. Deut. 874</span> <span dir=\"rtl\">במתא דביריין</span>; <span class=\"citation\">Targ. Y. I Num. XXXIV, 9</span> <span dir=\"rtl\">כִּירַיָּיא דבית סכל</span> (v. <a href=\"#\" data-headword=\"כּוּרַיי\">כּוּרַיי</a>). V. Hildesh. Beitr. p. 20, sq.</div>","alt":[]},"12227":{"h":"כּוּר II","r":"K00365","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>smelting pot, smelting furnace</i>. <span class=\"citation\">Tosef. Kel. B. Kam. VI, 16</span>. <span class=\"citation\">Kel. VIII, 9</span> <span dir=\"rtl\">כ׳ … של עושה זכיכית</span> (Var. <span dir=\"rtl\">בור</span>) the glassmaker’s pot. <span class=\"citation\">Sabb. VIII, 4</span> <span dir=\"rtl\">כ׳ של צורפי זהב</span> the gold refiners’ pot. <span class=\"citation\">Midr. Till. to Ps. CXIV</span> <span dir=\"rtl\">כאדם … מתוך הכ׳ וכ׳</span> like a man that takes gold out of the smelting pot without tongs &amp;c. <span class=\"citation\">Pirké d’R. El. ch. XLVIII</span> <span dir=\"rtl\">כ׳ של אש</span> a burning furnace; a. e.</div>","alt":[]},"12228":{"h":"כּוּרָא I","r":"K00366","html":"<div class=\"sense\"><span class=\"citation\">Targ. O. Deut. IV, 20</span> (Y. <a href=\"#\" data-headword=\"גִּיר\">גִּיר</a>); a. e.</div>","alt":[]},"12229":{"h":"*כּוּרָא II","r":"K00367","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כּוּרָא I\">preced.</a>) (supposed to be a disguise for) <i>female pudenda</i>. <span class=\"citation\">Sabb. 140ᵇ</span>; v., however, <a href=\"#\" data-headword=\"בִּזְרָא\">בִּזְרָא</a>.</div>","alt":[]},"12230":{"h":"כּוֹרָא","r":"K00368","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוֹר\">כּוֹר</a> ch.</div>","alt":[]},"12231":{"h":"כַּוְרָא","r":"K00369","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּוְורָא\">כַּוְורָא</a></div>","alt":[]},"12232":{"h":"כּוֹרַבְלִין","r":"K00370","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (χοραύλης) <i>flute-players accompanying the chorus of dancers</i>. <span class=\"citation\">Gen. R. s. 23</span>; s. 50 (variously corrupted), v. <a href=\"#\" data-headword=\"אִדְרַבְלָא\">אִדְרַבְלָא</a>.</div>","alt":[]},"12233":{"h":"כורדקי","r":"K00371","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַכְוַנְגַּר\">אַכְוַנְגַּר</a></div>","alt":[]},"12234":{"h":"כּוּרְהָנָא","r":"K00372","html":"<div class=\"sense\">, v. <span dir=\"rtl\">כֻּרְהָ׳</span></div>","alt":[]},"12235":{"h":"כּוּרְוָון","r":"K00373","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּרְיָא I\">כַּרְיָא</a></div>","alt":[]},"12236":{"h":"*כורוסתי","r":"K00374","html":"<div class=\"sense\">, a corrupt. for <span dir=\"rtl\">כַּרִיזֶסְתִּי</span> (χαρίζεσθαι) <i>to do a favor</i>. <span class=\"citation\">Y. Ned. III, 38ᵃ</span>, v. <a href=\"#\" data-headword=\"בִּיָיא II\"><span dir=\"rtl\">בִּיָּיא</span> II</a>.</div>","alt":[]},"12237":{"h":"כּוֹרֵז","r":"K00375","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּרוֹז\">כָּרוֹז</a></div>","alt":[]},"12238":{"h":"כּוּרְזִילָא","r":"K00376","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּרְזִילָא\">כַּרְזִילָא</a></div>","alt":[]},"12239":{"h":"כּוֹרַח","r":"K00377","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"כדופסלא\">כֹּר׳</a>.</div>","alt":["כּוֹרְחָא"]},"12240":{"h":"כּוּרַיי","r":"K00378","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> כ׳ רכתא <i>Great Khuray</i>, a northern Palestinean border town. <span class=\"citation\">Tosef. Shebi. IV, 11</span> Var. (ed. Zuck. note <span dir=\"rtl\">כּוּרְיָן</span>, v. <a href=\"#\" data-headword=\"כּוּר I\"><span dir=\"rtl\">כּוּר</span> I</a>); Y. ib. VI, 36ᶜ <a href=\"#\" data-headword=\"בֵּירַיי\">בֵּירַיי</a>. (V. Hildesh. Beitr. p. 21).</div>","alt":[]},"12241":{"h":"כורים","r":"K00379","html":"<div class=\"sense\">, <span class=\"citation\">Kel. XII, 8</span> some ed., v. <a href=\"#\" data-headword=\"*כִּירִים\">כִּירִים</a></div>","alt":[]},"12242":{"h":"כּוֹרִיתָא","r":"K00380","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כּוֹר\">כּוֹר</a>) <i>a Khor-ful</i>. <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\"><a href=\"#\" data-headword=\"כ׳\">כ׳</a> (<a href=\"#\" data-headword=\"עוּר I\">העיר</a>) <span dir=\"rtl\">דדינרין</span></span> (some ed. <span dir=\"rtl\">כּוֹרְיָיתָא</span> <i>pl.</i>) a Khor-ful (Khor-fuls) of Denars.</div>","alt":[]},"12243":{"h":"*כּוֹרֶךְ","r":"K00381","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּרַךְ\">כָּרַךְ</a>; cmp. <a href=\"#\" data-headword=\"כְּרוֹכָא\">כְּרוּכָא</a>) <i>part of a plough containing a receptacle out of which the seed falls during the ploughing.</i> <span class=\"citation\">Kel. XXI, 2</span> R. Hai G.; v., however, <a href=\"#\" data-headword=\"בֶּרֶךְ\">בֶּרֶךְ</a>.</div>","alt":[]},"12244":{"h":"כּוּרְכָּא","r":"K00382","html":"<div class=\"sense\">= <a href=\"#\" data-headword=\"כְּרַךְ II\">כְּרַכָּא</a><i>fort</i>. <span class=\"citation\">Tosef. Shebi. IV, 8</span> כו׳ דבית חרב Fort Beth Ḥereb, in the district of Nivay; <span class=\"citation\">Y. Dem. II, 22ᵈ</span> top <span dir=\"rtl\">כרכה דבר הזרג</span>.</div>","alt":[]},"12245":{"h":"כּוּרְכְּיָא","r":"K00383","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (onomatop.; cmp. <a href=\"#\" data-headword=\"אַקְרוֹקְתָּא\">אַקְרוֹקְתָּא</a>) <i>crane</i>. <span class=\"citation\">Targ. Jer. VIII, 7</span> (h. text <a href=\"#\" data-headword=\"סוּס\">סוס</a>).—<span class=\"citation\">Kidd. 44ᵃ</span> צווה ר&quot;ל כי כ׳ Ar. (ed. <a href=\"#\" data-headword=\"כְּרוּכְיָא\">כְּרוּכְיָא</a>) Resh Lakish cried like a crane. [<span class=\"citation\">Y. Dem. II, 22ᶜ</span> top <span dir=\"rtl\">כהדא כ׳</span>, v. <a href=\"#\" data-headword=\"סִידְקִי\">סִידְקִי</a>.]</div>","alt":[]},"12246":{"h":"כּוּרְכָּם","r":"K00384","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>saffron</i>, v. <a href=\"#\" data-headword=\"כַּרְכּוֹם I\"><span dir=\"rtl\">כַּרְכּוֹם</span> I</a>.</div>","alt":[]},"12247":{"h":"כּוּרְכְּמָא","r":"K00385","html":"<div class=\"sense\"><span class=\"citation\">Targ. Prov. VII, 17</span> Levita (ed. <span dir=\"rtl\">כורק׳</span>, h. text <span dir=\"rtl\">אהלים</span>).—<span class=\"citation\">Sabb. 110ᵃ</span> <span dir=\"rtl\">כ׳ רישקא</span> garden crocus (Rashi; v. Löw Pfl. p. 216).</div>","alt":["כּוּרְקְמָא"]},"12248":{"h":"כּוֹרֵם","r":"K00386","html":"<div class=\"sense\"><i>vintager, gardener</i>.—Pl. <span dir=\"rtl\">כּוֹרְמִים</span>. Tanḥ. Bo 4; <span class=\"citation\">Yalk. Ex. 182</span> <span dir=\"rtl\">המה … כּוֹרְמֵיהֶן</span> they (the Egyptians) planned that they (the Israelites) should be their gardeners.</div>","alt":[]},"12249":{"h":"כּוּרְמֵיזָא","r":"K00387","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">כמז</span> with inserted <a href=\"#\" data-headword=\"ר\">ר</a>; cmp. h. <a href=\"#\" data-headword=\"קֹמֶץ\">קֹמֶץ</a>) <i>fist</i>. <span class=\"citation\">Targ. O. Ex. XXI, 18</span>. <span class=\"citation\">Targ. Is. LVIII, 4</span>.—<span class=\"citation\">Midr. Prov. to XXII, 6</span> (prov.) <span dir=\"rtl\">לחכימא ברמיזא ולשטיא בכ׳</span> to the wise man a hint, to the fool a fist.</div>","alt":[]},"12250":{"h":"כְּוַרְנַק","r":"K00388","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַכְוַרְנְקָא\">אַכְוַרְנְקָא</a></div>","alt":["כְּוַרְנְקֵי"]},"12251":{"h":"כּוּרְסֵא","r":"K00389","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּרְסַיָּא\">כּוּרְסַיָּא</a></div>","alt":[]},"12252":{"h":"כּוּרְסָאיֵי","r":"K00390","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (prob.) <i>people of Karsa </i>or<i> Karsana</i> (v. <a href=\"#\" data-headword=\"כַּרְסָנָא\">כַּרְסָנָא</a>). <span class=\"citation\">Y. M. Kat. III, 82ᶜ</span></div>","alt":[]},"12253":{"h":"כורסגניות","r":"K00391","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to II, 2</span> some ed., read: <span dir=\"rtl\">כְּרִיסַרְגְּרִיּוֹת</span>, v. <a href=\"#\" data-headword=\"כְּרִיסוֹ\">כְּרִיסוֹ</a></div>","alt":[]},"12254":{"h":"כורסון","r":"K00392","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹלוֹכְרוּסוֹן\">אוֹלוֹכְרוּסוֹן</a></div>","alt":["אולו כ׳","אולון כ׳"]},"12255":{"h":"כּוּרְסַיָּא","r":"K00393","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (used as sing.), constr. <a href=\"#\" data-headword=\"כּוּרְסֵא\">כּוּרְסֵי</a>, <a href=\"#\" data-headword=\"כָּרְסֵא\">כָּרְסֵא</a> (<a href=\"#\" data-headword=\"*כרס\">כרס</a>; cmp. <a href=\"#\" data-headword=\"כַּר\">כַּר</a>) <i>divan, upholstered chair, throne.</i> <span class=\"citation\">Dan. V, 20</span>; <span class=\"citation\">VII, 9</span>.—<span class=\"citation\">Targ. I Kings X, 19</span>. <span class=\"citation\">Targ. Ex. XVII, 16</span>; a. fr.—<span class=\"citation\">Ḥull. 59ᵇ</span> [read:] <span dir=\"rtl\">נפל מִכּוּרְסַיֵּיה וכ׳</span> he fell from his throne to the ground. <span class=\"citation\">Yeb. 118ᵇ</span>; <span class=\"citation\">Keth. 75ᵃ</span> <span dir=\"rtl\">דשומשנא גברא כּוּרְסְיָהּ … רמי לה</span> if her husband be (as small as) an ant, put up her seat among the women of nobility, i.e. a woman feels elevated by marriage. <span class=\"citation\">Yeb. 83ᵇ</span> <span dir=\"rtl\">אותבוה אבי כורסי׳</span> they put him on an operator’s chair. <span class=\"citation\">Ib. 110ᵃ</span> אותבוה אבי כ׳ ואהדרוה Ar. (ed. omit <span dir=\"rtl\">ואהדרוה</span>) they put her on a bridal chair (v. <a href=\"#\" data-headword=\"אַפִּרְיוֹן\">אַפִּרְיוֹן</a>) and carried her around in procession. <span class=\"citation\">Lev. R. s. 27</span> <span dir=\"rtl\">תחות כ׳ דאמהון</span> under their mothers’ chair (of delivery); <span class=\"citation\">Midr. Till. to Ps. II</span>; <span class=\"citation\">Yalk. Ex. 165</span>; Yalk. Esth. 1055 (only <span dir=\"rtl\">תחות כורסי</span>). <span class=\"citation\">Gitt. 35ᵃ</span> <span dir=\"rtl\">הפכוה לכוּרְסְיֵה</span> (<i>fem</i>.) turn his judicial chair over; <span dir=\"rtl\">הפכוה לכ׳ ותרצוה</span> (Rashi: <span dir=\"rtl\">הפכו</span>) they turned his chair over and set it up again; a. fr.—Pl. <a href=\"#\" data-headword=\"כָּרְסָוָון\">כּוּרְסָוָון</a>, <a href=\"#\" data-headword=\"כָּרְסָוָון\">כָּרְסָוָן</a>, <span dir=\"rtl\">כּוּרְסְוָתָא</span>. <span class=\"citation\">Dan. VII, 9</span> (cited <span class=\"citation\">Ḥag. 14ᵃ</span>; <span class=\"citation\">Snh. 38ᵇ</span>). <span class=\"citation\">Targ. Ps. CXXII, 5</span>.—<span class=\"citation\">Koh. R. to III, 9</span> <span dir=\"rtl\">אית דאייתי כ׳</span> some brought divans (for the banquet). <span class=\"citation\">Ib. to I, 8</span> (in Hebr. Dict.) <span dir=\"rtl\">יעשו כ׳ לרבים</span> (sub. <span dir=\"rtl\">בתי</span>) let them be made into <i>privies</i> for the public.</div>","alt":["כּוּרְסַיָּה","כּוּרְסְיָא"]},"12256":{"h":"כורסין","r":"K00394","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Neg. V, 14</span> ed., read: <a href=\"#\" data-headword=\"בּוּרְסִים\">בורסין</a>, v. <a href=\"#\" data-headword=\"בִּרְסִין\">בִּרְסִין</a></div>","alt":[]},"12257":{"h":"כּוּרְעָתָא","r":"K00395","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּרְעָא\">כַּרְעָא</a></div>","alt":[]},"12258":{"h":"כּוּרְקְמָא","r":"K00396","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּרְכְּמָא\">כּוּרְכְּמָא</a></div>","alt":[]},"12259":{"h":"כְּוֶרֶת","r":"K00397","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">כוור׳</span>.</div>","alt":["כְּוַרְתָּא"]},"12260":{"h":"כּוּשׁ I","r":"K00398","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"כּוֹס I\">כּוֹס</a>, <a href=\"#\" data-headword=\"כִּיס\">כִּיס</a>) [<i>something hollow</i>,] <i>reed</i>, esp. reed used as <i>spindle</i> (v. Ar. s. v.); also as <i>fork</i>. <span class=\"citation\">Yoma 82ᵃ</span> <span dir=\"rtl\">תוחבין לה כ׳ ברוטב</span> we put for her a reed into the juice (and let her suck it); Tosef. ib. V (IV), 4 (corr. acc.). <span class=\"citation\">Sabb. 123ᵃ</span>; Y. ib. XVII, 16ᵇ top, v. <a href=\"#\" data-headword=\"*כַּרְכָּר\">כַּרְכָּר</a>. <span class=\"citation\">Y. Erub. III, 20ᵈ</span> bot. <span dir=\"rtl\">לתחוב בכ׳ ובקיסם</span> to stick it on a reed or a chip. <span class=\"citation\">Kel. IX, 8</span> <span dir=\"rtl\">מלא כ׳</span> the size of a reed. <span class=\"citation\">Tosef. Kel. B. Mets. VI, 12</span> <span dir=\"rtl\">בכ׳ בכ׳ הבינוני</span> wherever the size of a reed (or spindle) is mentioned, a middle-sized reed is meant. <span class=\"citation\">Kel. IX, 7</span> <span dir=\"rtl\">כ׳ שבלע את הצנורא</span> a reed in which the iron hook has disappeared. <span class=\"citation\">Par. XII, 8</span>; <span class=\"citation\">Tosef. ib. XII</span> (<span class=\"citation\">XI), 16</span>, v. <a href=\"#\" data-headword=\"אָרְבָּן\">אָרְבָּן</a>; a. fr.—Pl. <a href=\"#\" data-headword=\"כּוּשִׁי\">כּוּשִׁין</a>. <span class=\"citation\">Y. Yeb. XII, 12ᵈ</span> bot. (in Chald. diction, in a disguised answer to a ritual question propounded to R. Akiba by a pretended street vendor) <span dir=\"rtl\">אית לך כ׳ אית לך כשר</span> hast thou spindles? hast thou ‘<i>Kasher</i>’? (play on <span dir=\"rtl\">כִּישׁוֹר</span>, v. <a href=\"#\" data-headword=\"כּוּנְשְׁרָא\">כּוּנְשְׁרָא</a>; intimating ‘It is legal’).</div>","alt":[]},"12261":{"h":"כּוּשׁ II","r":"K00399","html":"<div class=\"sense\"> (b. h.) pr. n. <i>Cush</i>, </div><div class=\"sense\"><b>1)</b>  son of Ham. <span class=\"citation\">Targ. Gen. X, 6</span>; a. e.—2) <i>the land of Cush, Aethiopia</i>. <span class=\"citation\">Targ. II Kings XIX, 9</span>. <span class=\"citation\">Targ. Y. Num. XII, 1</span>; a. e.—<span class=\"citation\">Yalk. Ex. 168</span>. <span class=\"citation\">Pes. 94ᵃ</span>; <span class=\"citation\">Taan. 10ᵃ</span> מצרים … בכ׳ Egypt is one sixtieth as large as Aethiopia. <span class=\"citation\">Y. Ber. I, 2ᶜ</span> bot. <span dir=\"rtl\">תמצית כ׳ וכ׳</span> the juice (moisture) of Aeth. is absorbed by Egypt; a. e.</div>","alt":[]},"12262":{"h":"כּוּשָׁא","r":"K00400","html":"<div class=\"sense\"><i>bunch</i>, v. <a href=\"#\" data-headword=\"כִּישָׁא\">כִּישָׁא</a>.</div>","alt":[]},"12263":{"h":"כּוּשָׁאָה","r":"K00401","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּשָׁיָיא\">כּוּשָׁיָיא</a></div>","alt":[]},"12264":{"h":"כּוּשִׁי","r":"K00402","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>Cushite, negro; Aethiopian</i>. <span class=\"citation\">Gen. R. s. 60</span>, beg.; <span class=\"citation\">Cant. R. to II, 8</span> (not <a href=\"#\" data-headword=\"כּוּתִי I\">כותי</a>), v. <a href=\"#\" data-headword=\"בַּרְבָּרִי\">בַּרְבָּרִי</a>. <span class=\"citation\">Gen. R. s. 73</span>, end; a. fr. [<span class=\"citation\">B. Kam. 113ᵇ</span>, a. e. in later ed. <a href=\"#\" data-headword=\"כּוּשִׁי\">כושי</a> for <a href=\"#\" data-headword=\"גּוֹי\">גּוֹי</a> or <a href=\"#\" data-headword=\"נָכְרִי\">נָכְרִי</a>.]—<span class=\"citation\">Succ. III, 6</span> <span dir=\"rtl\">אתרוג הכ׳</span>, expl. <span class=\"citation\">ib. 36ᵃ</span> <span dir=\"rtl\">דומה לכ׳</span> a Palestinean Ethrog resembling an Aethiopian one; (oth. opin.) a real importation from Aethiopia. Y. ib. 53ᵈ <span dir=\"rtl\">אתרוג הכ׳ פסול</span> the Aeth. Ethrog is ritually unfit; <span dir=\"rtl\">הבא מן הכ׳ כשר</span> one of Palestinean growth descended from an Aethiopian Ethrog is available for ritualistic use.—Trnsf. <i>abnormally dark-complexioned</i>. <span class=\"citation\">Bekh. VII, 6</span>. <span class=\"citation\">Ber. 58ᵇ</span>; Tosef. ib. VII (VI), 3; a. e.—<span dir=\"rtl\">עֵין כּוּשִׁי</span> pr. n. pl. <i>En Kushi</i>. <span class=\"citation\">Ab. Zar. 31ᵃ</span>; Y. ib. V, 44ᵈ <span dir=\"rtl\">ע׳ כושי׳</span>; Y. Shebi. V, 36ᵃ top <span dir=\"rtl\">ע׳ כּוּשִׁין</span>.</div>","alt":["כּוּשִׁית"]},"12265":{"h":"כּוּשָׁיָיא","r":"K00403","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. II, Num. XII, 1</span>. Pl. <span dir=\"rtl\">כּוּשָׁאֵי</span>. Targ. Y. I Num. l. c.—<span class=\"citation\">Succ. 53ᵃ</span>.—<i>Fem</i>. <span dir=\"rtl\">כּוּשְׁיָיתָא</span>, <span dir=\"rtl\">כּוּשַׁיְיתָא</span>. Targ. I, II, Num. l. c.</div>","alt":["כּוּשָׁאָה"]},"12266":{"h":"כּוּשִׁית","r":"K00404","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּשִׁי\">כּוּשִׁי</a></div>","alt":[]},"12267":{"h":"*כּוּשְׁפָּא","r":"K00405","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">כשף</span>, cmp. <span dir=\"rtl\">חשב</span>) <i>embroidery, design</i>.—Pl. <span dir=\"rtl\">כּוּשְׁפִּין</span>. <span class=\"citation\">Targ. Ez. XXVII, 24</span> כ׳ דוורדא וכ׳ Ar. (ed. Lag. <span dir=\"rtl\">דיורדא</span>, ed. <a href=\"#\" data-headword=\"אַרְזָא\">ארזא</a>) designs of roses (cedars) on purple cloaks (h. text <a href=\"#\" data-headword=\"רִקְמָה\">רקמה</a>).</div>","alt":[]},"12268":{"h":"כּוֹשְׁפָן","r":"K00406","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּשַׁף\">כָּשַׁף</a>) <i>a believer in sorcery or omens</i>. Y. R. Hash. III, end, 59ᵃ</div>","alt":[]},"12269":{"h":"כּוֹשֶׁר","r":"K00407","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּשֵׁר I\">כָּשֵׁר</a>) <i>fitness, legitimacy, being</i> <a href=\"#\" data-headword=\"כָּשֵׁר I\">כָּשֵׁר</a>. <span class=\"citation\">Pes. 83ᵃ</span> <span dir=\"rtl\">היתה לו שעת הכ׳</span> was at one time fit for use. <span class=\"citation\">Y. Yeb. VIII, 9ᵈ</span> top <span dir=\"rtl\">כל … החמה בכ׳ וכ׳</span> whom the light of the sun has never seen in a condition of sexual fitness, v. <a href=\"#\" data-headword=\"סָרִיס\">סָרִיס</a>. <span class=\"citation\">Y. Bets. III, 62ᵃ</span> top <span dir=\"rtl\">חזקת בני מעיים לכ׳</span> the presumption in the case of entrails is in favor of their being <a href=\"#\" data-headword=\"כָּשֵׁר I\">כָּשֵׁר</a>, v. <a href=\"#\" data-headword=\"חֲזָקָה\">חֲזָקָה</a>; <span class=\"citation\">Y. Ter. VIII, 46ᵃ</span> top (corr. acc.). <span class=\"citation\">Y. Succ. V, 55ᵇ</span> bot. (in Chald. dict.) <span dir=\"rtl\">עבדין בכ׳</span> behaving with propriety (during worship), opp. <span dir=\"rtl\">בפחז</span> irreverently; a. fr.</div>","alt":[]},"12270":{"h":"כּוּשְׁרָא I","r":"K00408","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּשַׁר\">כְּשַׁר</a>) <i>attachment</i>. <span class=\"citation\">B. Mets. 93ᵇ</span> <span dir=\"rtl\">כ׳ דח׳</span> the attachment which one has for one’s animal.</div>","alt":[]},"12271":{"h":"כּוּשְׁרָא II","r":"K00409","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּנְשְׁרָא\">כּוּנְשְׁרָא</a></div>","alt":[]},"12272":{"h":"כּוֹשָׁרוֹת","r":"K00410","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּשְׁרוּת\">כַּשְׁרוּת</a></div>","alt":[]},"12273":{"h":"כּוֹשְׁתְּ","r":"K00411","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>putchuck</i>, v. <a href=\"#\" data-headword=\"קוֹשְׁטְ\">קוֹשְׁטְ</a>.</div>","alt":[]},"12274":{"h":"כְּוָת","r":"K00412","html":"<div class=\"sense\">, constr. <a href=\"#\" data-headword=\"כְּוָת\">כְּוַת</a>, <a href=\"#\" data-headword=\"כְּוָות\">כְּוַות</a> (v. <a href=\"#\" data-headword=\"יַת\">יַת</a>) [<i>likeness</i>,] <i>like, in agreement with</i>. <span class=\"citation\">Targ. Y. II, Gen. XLIV, 18</span>. <span class=\"citation\">Targ. Y. II, Num. XII, 7</span>; a. e.—With pron. suffix: <a href=\"#\" data-headword=\"כּוּתִי I\">כְּוָתִי</a>, <span dir=\"rtl\">כְּוָתָךְ</span>, <span dir=\"rtl\">כְּוָתִיךְ</span>, <span dir=\"rtl\">כְּוָתֵיה</span> &amp;c. <i>like me</i> &amp;c. <span class=\"citation\">Targ. Ps. CXIII, 5</span>. <span class=\"citation\">Targ. Y. Ex. XV, 11</span>; a. v. fr.—With prefix <span dir=\"rtl\">דִּ</span>, v. <a href=\"#\" data-headword=\"דִּכְוָת־\">דִּכְוָת־</a>.—<span class=\"citation\">Ber. 36ᵃ</span>, a. fr. <span dir=\"rtl\">הלכתא כותיה ד־</span> the practice is in agreement with the opinion of—(v. <a href=\"#\" data-headword=\"הֲלָכָה\">הֲלָכָה</a>). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">קיימי כותיה</span> agree with him. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כותך מסתברא</span> reason agrees with thee. <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">כותיה דרב כהנא וכ׳</span> reason is in favor of R. Kahana’s opinion. <span class=\"citation\">B. Bath. 65ᵃ</span> <span dir=\"rtl\">הילכתא כְּוָותִין או … כְּוָתַיְיכוּ</span> must the rule be adopted agreeably to our opinion or to yours? (Ms. M. <span dir=\"rtl\">כְּוָתֵיךְ … כְּוָתִין</span>); <span class=\"citation\">ib. 142ᵇ</span>. <span class=\"citation\">Y. Ber. I, 3ᵃ</span> top <span dir=\"rtl\">עבד עובדא כוותיה</span> acted in accordance with his own opinion; a. fr.</div>","alt":["כְּוָות"]},"12275":{"h":"כּוּת","r":"K00413","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Cuth, Cuthah</i>, a Babylonian town whence Assyrian colonists were introduced into Samaria (v. Schr. KAT<sup>2</sup>, p. 278). <span class=\"citation\">Targ. II Kings XVII, 24</span>; <span class=\"citation\">30</span>. [<span class=\"citation\">Targ. Is. XXXIV, 9</span> <a href=\"#\" data-headword=\"דִּכְוָת־\">דכות</a> some ed. (ed. Lag. <a href=\"#\" data-headword=\"דְּרוֹמִי\">דרומי</a>; missing in ed. Wil.)—an inserted gloss, v. Lag. Prophetae I, p. XXX<sup>33</sup>.]—v. <a href=\"#\" data-headword=\"כּוּתִי I\">כּוּתִי</a>.</div>","alt":["כּוּתָה"]},"12276":{"h":"כּוּתָא","r":"K00414","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּתִי I\"><span dir=\"rtl\">כּוּתִי</span> I</a></div>","alt":[]},"12277":{"h":"כּוּתָּא","r":"K00415","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּתַּח\">כּוּתְּחָא</a></div>","alt":[]},"12278":{"h":"כַּוְתָא","r":"K00416","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>owl</i>, v. <a href=\"#\" data-headword=\"בָּאוָת\">בָּאוָת</a>.</div>","alt":[]},"12279":{"h":"כּוּתָאָה","r":"K00417","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּתַיי\">כּוּתַיי</a></div>","alt":[]},"12280":{"h":"כּוֹתֵב","r":"K00418","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּתַב I\">כְּתַב</a>) </div><div class=\"sense\"><b>1)</b> <i>writing, writer</i>, v. <a href=\"#\" data-headword=\"כָּתַב\">כָּתַב</a>.</div><div class=\"sense\"><b>—2)</b> <i>the pointed end</i> of the writing instrument (stilus), contrad. to <a href=\"#\" data-headword=\"מוֹחֵק\">מוחק</a> the flat end for erasing. <span class=\"citation\">Kel. XIII, 2</span>; <span class=\"citation\">Tosef. Kel. B. Mets. III, 4</span>; <span class=\"citation\">Y. Sabb. VIII, 11ᵇ</span> bot.</div>","alt":[]},"12281":{"h":"כּוֹתְבָן","r":"K00419","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כּוֹתֵב\">preced.</a>) <i>writer, calligrapher</i>.—Pl. <span dir=\"rtl\">כּוֹתְבָנִים</span>. <span class=\"citation\">Y. Meg. I, 71ᵈ</span> bot. <span dir=\"rtl\">כ׳ אומנים</span> professional writers of Biblical books.</div>","alt":[]},"12282":{"h":"כּוֹתֶבֶת","r":"K00420","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"קִשְׁבָּא\">קִשְׁבָּא</a>) <i>date</i> of a certain species, <i>kothebeth</i>, used as a measure of size <a href=\"#\" data-headword=\"כּוֹכָב ²\">כַּכֹּ׳</a> (cmp. <a href=\"#\" data-headword=\"זַיִת\">זַיִת</a>). <span class=\"citation\">Yoma VIII, 2</span>. <span class=\"citation\">Bets. I, 1</span> <span dir=\"rtl\">חמץ בְּכַכֹּ׳</span> the standard for leavened bread (on Passover, as for being guilty of a transgression) is the size of a <i>kothebeth</i> (less than an olive); a. fr.—Pl. <span dir=\"rtl\">כּוֹתָבוֹת</span>. <span class=\"citation\">Succ. II, 5</span> (<span class=\"citation\">26ᵇ</span>) <span dir=\"rtl\">שתי כ׳</span> Ms. M. (ed. <a href=\"#\" data-headword=\"שני\">שני</a>) two dates.</div>","alt":[]},"12283":{"h":"כּוּתָה","r":"K00421","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוּת\">כּוּת</a></div>","alt":[]},"12284":{"h":"כּוּתָּח","r":"K00422","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Pers. <i>kataḫ</i>, v. Perl. Et. St. p. 85, note; Fl. to Levy Talm. Dict. II, p. 459ᵇ) <i>a preserve consisting of sour milk, bread-crusts and salt</i>. <span class=\"citation\">Pes. III, 1</span> <span dir=\"rtl\">כ׳ הבבלי</span> the Babylonian <i>k.</i>, described <span class=\"citation\">ib. 42ᵃ</span>, v. <a href=\"#\" data-headword=\"*אוּמָא\">אוּמָא</a> a. <a href=\"#\" data-headword=\"נַסְיוּבֵי\">נַסְיוּבֵי</a>.</div>","alt":[]},"12285":{"h":"כּוּתַּח","r":"K00423","html":"<div class=\"sense\"> <span class=\"citation\">Keth. 60ᵇ</span>; <span class=\"citation\">Erub. 62ᵇ</span> <span dir=\"rtl\">אפי׳ ביעתא בכ׳ וכ׳</span> even as plain a case as the question about an egg that fell into <i>k.</i>, a student must not decide in the presence of his teacher. <span class=\"citation\">Kerith. 6ᵃ</span> <span dir=\"rtl\">מכ׳ דרמי כיפי</span> than a <i>k</i>. which is hard enough to break rocks; <span class=\"citation\">Hor. 12ᵃ</span> (Ms. M. <a href=\"#\" data-headword=\"כָּמְכָא\">כמכא</a>, v. Rabb. D. S. a. l. note). <span class=\"citation\">Erub. 65ᵃ</span> <span dir=\"rtl\">קריב לי כ׳</span> (Ar. <a href=\"#\" data-headword=\"כּוּתָּא\">כּוּתָּא</a>) hand me the <i>k</i>. <span class=\"citation\">Sabb. 145ᵇ</span> <span dir=\"rtl\">רייק מכ׳ דבבלאי</span> (Ar. <a href=\"#\" data-headword=\"מָכוּתָא\">מכותא</a>) spat out when thinking of the <i>k</i>. of the Babylonians.</div>","alt":["כּוּתְּחָא"]},"12286":{"h":"כּוּתִי I","r":"K00424","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כּוּת\">כּוּת</a>) <i>Kuthi</i>, a Babylonian town. <span class=\"citation\">B. Bath. 91ᵃ</span> Abraham was imprisoned <span dir=\"rtl\">שלש בכ׳ וכ׳</span> (v. Rabb. D. S. a. l. note, a. Koh. Ar. Compl. s. v. <a href=\"#\" data-headword=\"כַּרְדּוּ\">כרדו</a>) three years in Kuthi &amp;c.; <span class=\"citation\">Pirké d’R. El. ch. XXVI</span> <span dir=\"rtl\">כותא</span>.</div>","alt":[]},"12287":{"h":"כּוּתִי II","r":"K00425","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כּוּת\">כּוּת</a>) <i>Cuthean, a member of the sect of Samaritans</i>. [In editions published under censorial influences our w. frequently takes the place of <a href=\"#\" data-headword=\"גּוֹי\">גוי</a>, <span dir=\"rtl\">עכו&quot;ם</span>, <a href=\"#\" data-headword=\"מִן ²\">מין</a> &amp;c., a. vice versa.] <span class=\"citation\">Ḥull. 3ᵇ</span>. <span class=\"citation\">Tosef. Ab. Zar. III, 5</span> (distinction between <a href=\"#\" data-headword=\"כ׳\">כ׳</a> a. <a href=\"#\" data-headword=\"גּוֹי\">גוי</a>). Ib. 13ᵃ. <span class=\"citation\">Y. Keth. III, beg. 27ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">כּוּתִים</span>, <span dir=\"rtl\">כּוּתִיִּים</span>, <span dir=\"rtl\">כּוּתִין</span>. <span class=\"citation\">Y. Yeb. VII, 8ᵇ</span> bot. <span class=\"citation\">Ḥull. 3ᵇ</span> <span class=\"citation\">Sot. 33ᵇ</span> <span dir=\"rtl\">ספרי כ׳</span> the books of the Samaritans, v. <a href=\"#\" data-headword=\"זוּף I\"><span dir=\"rtl\">זוּף</span> I</a>; <span class=\"citation\">Snh. 90ᵇ</span> <span dir=\"rtl\">צדוקים</span> ed. (Ms. M. <a href=\"#\" data-headword=\"כ׳\">כ׳</a>, v. Rabb. D. S. a. l. note); a. fr.—<i>Fem</i>. <span dir=\"rtl\">כּוּתִית</span>. <span class=\"citation\">Keth. III, 1</span>. Tosef. Oh. XVIII, 6; a. fr.—Pl. <span dir=\"rtl\">כּוּתִיּוֹת</span>. <span class=\"citation\">Nidd. IV, 2</span>; <span class=\"citation\">Tosef. ib. V, 2</span>; a. e.</div>","alt":[]},"12288":{"h":"כּוּתַיי","r":"K00426","html":"<div class=\"sense\"> . <span class=\"citation\">Y. M. Kat. III, 83ᵇ</span>. <span class=\"citation\">Y. Taan. IV, 68ᵈ</span> bot.; a. e.—Pl. <span dir=\"rtl\">כּוּתָאֵי</span>, <a href=\"#\" data-headword=\"כּוּתַיי\">כּוּתָיֵיא</a>. <span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span>. <span class=\"citation\">Ḥull. 6ᵃ</span>; a. fr.</div>","alt":["כּוּתָיָיא","כּוּתָאָה"]},"12289":{"h":"כְּוָתִירִין","r":"K00427","html":"<div class=\"sense\"> (?) pr. n. pl. <i>K’vathirin</i>, <span class=\"citation\">Targ. Y. Deut. IV, 43</span> (h. text <a href=\"#\" data-headword=\"בֶּצֶר\">בֶּצֶר</a>).</div>","alt":[]},"12290":{"h":"כּוֹתָל","r":"K00428","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"כֹּתֶל\">כֹּתֶל</a>; <a href=\"#\" data-headword=\"כֹּתֶל\">כתל</a> <i>to press together</i>,  [<i>something solid</i>, cmp. <span dir=\"rtl\">אָטוּם</span>, <a href=\"#\" data-headword=\"אוֹטֶם\">אוֹטֶם</a>,] <i>wall</i>. <span class=\"citation\">Gen. R. s. 68</span> (ref. to <span class=\"citation\">Gen. XXVIII, 11</span> ‘he struck’) <span dir=\"rtl\">נעשה … כמין כ׳ וכ׳</span> the whole world was before him blocked as by a wall. Ohol. VI, 3 <span dir=\"rtl\">כ׳ שהוא לאויר</span> a wall which faces the air (which is continued above the roofing, or faces the court yard). Ib. <span dir=\"rtl\">כ׳ המשמש את הבית</span> a wall made for forming an enclosure, contrad. to ib. 6 <span dir=\"rtl\">בית המשמש את הכ׳</span> a wall formed by digging two cavities next to each other. <span class=\"citation\">B. Bath. I, 1</span>; a. fr.—Pl. <span dir=\"rtl\">כּוֹתָלִים</span>, <span dir=\"rtl\">כּוֹתָלִין</span>, <span dir=\"rtl\">כְּתָלִ׳</span>. <span class=\"citation\">Y. Shek. IV, 48ᵃ</span> bot. <span dir=\"rtl\">כתלין</span> (Bab. ed. <span dir=\"rtl\">כתלים</span>, Ms. M. <a href=\"#\" data-headword=\"כּוֹתָל\">כותל</a>). <span class=\"citation\">Gen. R. s. 18</span>, beg. <span dir=\"rtl\">כ׳ של זהב</span> golden partitions (of Adam’s tent). <span class=\"citation\">B. Mets. 59ᵇ</span> <span dir=\"rtl\">כּוֹתְלֵי בה&quot;מ וכ׳</span> let the walls of the school house decide. <span class=\"citation\">Nidd. 3ᵃ</span> <span dir=\"rtl\">כותלי בית הרחם</span> the enclosures of the womb; a. fr.</div>","alt":["(כּוֹתֶל)"]},"12291":{"h":"כּוֹתְלָא","r":"K00429","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Sam. XX, 25</span>. <span class=\"citation\">Targ. II Kings IV, 10</span>; a. fr.—<span class=\"citation\">Sabb. 80ᵇ</span>. <span class=\"citation\">Y. Kil. I, 27ᵃ</span> top; a. e.—[<span class=\"citation\">Ber. 58ᵇ</span> נפל כתלא Ar., ed. <span dir=\"rtl\">בתלא</span>, v. <a href=\"#\" data-headword=\"תֵּל ²\">תַּלָּא</a>.]—Pl. <a href=\"#\" data-headword=\"כּוֹבְלִין\">כּוֹתְלִין</a>, <span dir=\"rtl\">כּוֹתְלַיָּא</span>, <span dir=\"rtl\">כּוֹתְלֵי</span>, <a href=\"#\" data-headword=\"כְּתַב II\">כָּתְ׳</a>. [Esra V, 8 <span dir=\"rtl\">כֻּתְלַ׳</span>.] <span class=\"citation\">Targ. Lev. XIV, 37</span>; a. fr.—<span class=\"citation\">Yoma 28ᵇ</span> <span dir=\"rtl\">מכי משחרי כ׳</span> from the time the walls throw a shadow (in the afternoon); a. fr.—<span dir=\"rtl\">כותלי דחזירי</span> (<span dir=\"rtl\">כת׳</span>) <i>bacon</i> (cmp. <a href=\"#\" data-headword=\"אַטְמָא\">אַטְמָא</a>). <span class=\"citation\">Ḥull. 17ᵃ</span> <span dir=\"rtl\">כת׳</span> (Ar. <a href=\"#\" data-headword=\"כּוֹתְנִיאָס\">כות׳</a>). <span class=\"citation\">Meg. 13ᵃ</span> Ms. M. a. Rashi (ed. <span dir=\"rtl\">קדלי</span>).</div>","alt":["כָּתְלָא"]},"12292":{"h":"כותנאי","r":"K00430","html":"<div class=\"sense\">, <span class=\"citation\">Y. Peah I, 16ᵃ</span>, read: <span dir=\"rtl\">בּוּתְנַאי</span>, v. <a href=\"#\" data-headword=\"בּוֹתְנַיֵּי\">בּוּתְנַיֵּי</a>. [Comment. <a href=\"#\" data-headword=\"כותנאי\">כּוּתָּנָאֵי</a> <i>dealers in linen</i>, v. <a href=\"#\" data-headword=\"כִּיתַּן\">כִּיתַּן</a>.]</div>","alt":[]},"12293":{"h":"כּוֹתְנִיאָס","r":"K00431","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בּוֹתְנִיאָס\">בּוֹתְנִיאָס</a></div>","alt":["כּוֹתְנְיָיס","כּוֹתַ׳"]},"12294":{"h":"כותניין","r":"K00432","html":"<div class=\"sense\">, Y. Maas. Sh. IV, beg. 54ᵈ, read: <a href=\"#\" data-headword=\"בּוֹתְנַיֵּי\">בּוֹתְנְיִין</a>.</div>","alt":[]},"12295":{"h":"כּוֹתְנְיָיס","r":"K00433","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוֹתְנִיאָס\">כּוֹתְנִיאָס</a></div>","alt":[]},"12296":{"h":"כּוּתְרָא","r":"K00434","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּתַר ²\">כִּתְרָא</a></div>","alt":[]},"12297":{"h":"כּוֹתְרָן","r":"K00435","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוֹתַרְתָּא\">כּוֹתַרְתָּא</a></div>","alt":[]},"12298":{"h":"כּוֹתֶרֶת","r":"K00436","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>crown, capital</i>. Tanḥ. B’har 1 <span dir=\"rtl\">כ׳ מלמעלן ובסיס וכ׳</span> a capital above and a pedestal beneath; <span class=\"citation\">Yalk. Cant. 990</span>; (<span class=\"citation\">Cant. R. to V, 15</span> <span dir=\"rtl\">קיפלורוסים</span>).</div>","alt":[]},"12299":{"h":"כּוֹתַרְתָּא","r":"K00437","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ez. XLI, 18</span>, sq. (h. text <span dir=\"rtl\">תמרה</span>).—Pl. <a href=\"#\" data-headword=\"כּוֹתְרָן\">כּוֹתְרָן</a>, <a href=\"#\" data-headword=\"כּוֹתַרְתָּא\">כִּוֹתְרָתָא</a>. <span class=\"citation\">Ib. 20</span>. <span class=\"citation\">Ib. XL, 16</span>; <span class=\"citation\">22</span> (ed. Wil. sing.); a. e.</div>","alt":[]},"12300":{"h":"כּוֹתֶשׁ","r":"K00438","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּתַשׁ\">כָּתַשׁ</a>) <i>a vessel for olives</i>, v. <a href=\"#\" data-headword=\"*כּוֹפֶשׁ\">כּוֹפֶשׁ</a>. [<span dir=\"rtl\">שער כותש</span>, v. <a href=\"#\" data-headword=\"כָּתַשׁ\">כָּתַשׁ</a>.]</div>","alt":[]},"12301":{"h":"כָּזַב","r":"K00439","html":"<div class=\"sense\"> [<i>to shrink</i>, cmp. <a href=\"#\" data-headword=\"כָּחַשׁ\">כָּחַשׁ</a>,] <i>to fail, dry up</i> (of watercourses); <i>to be false, to lie; to flatter</i>. <span class=\"citation\">Tosef. Par. IX</span> (<span class=\"citation\">VIII), 2</span> <span dir=\"rtl\">מפני שכָּזְבָה וכ׳</span> because it gave out during the war.—<span class=\"citation\">Snh. 82ᵇ</span> (play on <span dir=\"rtl\">כזבי</span>, <span class=\"citation\">Num. XXV, 15</span>) <span dir=\"rtl\">כזבה באביה</span> she was false to her father (in disobeying his instructions). Tanḥ. Sh’laḥ 5 לא כָזַבְתִּי לך I did not tell thee a falsehood; a. e.</div><div class=\"sense\"><b>Pi. כִּיזֵּב</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"כּוֹתֶשׁ\">same</a>. <span class=\"citation\">Par. VIII, 9</span> <span dir=\"rtl\">המים המְכַזְּבִים</span> waters which fail at certain times. Y. Taan. II, 65ᵇ bot. (ref. to <span class=\"citation\">Num. XXIII, 19</span>) <span dir=\"rtl\">אם יאמר … מְכַזֵּב הוא</span> if a man says, I am a God, he is a deceiver. <span class=\"citation\">Num. R. s. 23</span> (ref. to Num. l. c.) <span dir=\"rtl\">איש עושה לאל שיְכַזֵּב</span> a man (through his prayer) may cause God to fail (to execute his evil decrees); Tanḥ. Masé 7 <span dir=\"rtl\">לא איש עושה לאל שיכ׳</span> does not a man cause God &amp;c.?—<span class=\"citation\">Yoma 69ᵇ</span> לא כִיזְּבוּ לו Ms. M. (ed. <a href=\"#\" data-headword=\"בּוֹ\">בו</a>) they would not be false in His praise (flatter); a. fr.—<i>Part. pass</i>. <span dir=\"rtl\">מְכוּזָּב</span>, pl. <span dir=\"rtl\">מְכוּזָּבִים</span> <i>reduced</i>. Ruth. R. to I, 1 (play on <span dir=\"rtl\">כזבה</span>, <span class=\"citation\">I Chr. IV, 22</span>) <span dir=\"rtl\">אלו בניו שהיו מכ׳</span> that refers to his (Elimelech’s) sons who were reduced (died).</div></div>","alt":[]},"12302":{"h":"כְּזַב","r":"K00440","html":"<div class=\"sense\"><b>,</b><i>Pa</i>. <span dir=\"rtl\">כַּזֵּב</span> same. <span class=\"citation\">Targ. Job VI, 28</span> (Ms. <a href=\"#\" data-headword=\"כַּדְבָא\">כד׳</a>). <span class=\"citation\">Targ. Prov. XIV, 5</span> (ed. Lag. <span dir=\"rtl\">מכדב</span>); v. <a href=\"#\" data-headword=\"כְּדַב\">כְּדב</a>.</div>","alt":[]},"12303":{"h":"כָּזָב","r":"K00441","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"כְּזַב\">preced.</a>) <i>falsehood</i>.—Pl. <span dir=\"rtl\">כְּזָבִים</span>. Pesik. Baḥod., p. 154ᵃ; <span class=\"citation\">Lev. R. s. 29</span> <span dir=\"rtl\">הבלים וכ׳</span> vain and false things. <span class=\"citation\">Cant. R. to II, 13</span> (play on <a href=\"#\" data-headword=\"סְתָו\">סתו</a>, <span class=\"citation\">ib. 11</span>) that is the wicked (Roman) government <span dir=\"rtl\">שמסיתה … בכְזָבֶיהָ</span> which entices the world and leads it astray with its falsehoods. <span class=\"citation\">Pesik. R. s. 40</span> <span dir=\"rtl\">כ׳ שישראל מכזבים וכ׳</span> the falsehoods which the Israelites commit during the whole year.—[<span class=\"citation\">Ex. R. s. 42</span> <span dir=\"rtl\">כזבים</span>, v. <a href=\"#\" data-headword=\"כּוּב\">כּוּב</a>.]—[<span dir=\"rtl\">מדבר כזב</span>, v. <a href=\"#\" data-headword=\"כּוּב\">כּוּב</a>.]</div>","alt":[]},"12304":{"h":"כַּזְבָּן","r":"K00442","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּזָב\">preced.</a>) <i>liar</i>. Tanḥ. Masé 5 אתחשב כ׳ I shall he considered a liar; <span class=\"citation\">Num. R. s. 23</span>.</div>","alt":[]},"12305":{"h":"כַּזְבָּנָא","r":"K00443","html":"<div class=\"sense\"><span class=\"citation\">Gen. R. s. 47</span>.</div>","alt":[]},"12306":{"h":"*כְּזַז","r":"K00444","html":"<div class=\"sense\"> (v. P. Sm. 1691 s. v. <a href=\"#\" data-headword=\"כּוּז\">כוז</a>), [<i>to shrink</i>,] <i>to be shy, bashful</i>. Part. <span dir=\"rtl\">כָּזִיז</span>. <span class=\"citation\">Pes. 72ᵇ</span> כ׳ מינה Ar. a. Ms. O. (v. Rabb. D. S. a. l. note, ed. <span dir=\"rtl\">בזיז</span>) he is reserved towards her (not yet intimate). <span class=\"citation\">Yeb. 26ᵃ</span> דכ׳ בניה מיניה Ar. (ed. <span dir=\"rtl\">דב׳</span>) before him his son is shy. Ib. 112ᵃ top <span dir=\"rtl\">מִיכְזַז כ׳ מינה</span> Ar. (ed. <span dir=\"rtl\">מיב׳ ב׳</span>), opp. <a href=\"#\" data-headword=\"גֵּיס\">גיס</a>, v. <a href=\"#\" data-headword=\"גִּיס II\"><span dir=\"rtl\">גִּיס</span> I</a>. <span class=\"citation\">Nidd. 15ᵇ</span> <span dir=\"rtl\">ילדה דכְזִיזָא למיטבל</span> (ed. <span dir=\"rtl\">דב׳</span>) a young woman who is ashamed to go to the bath-house.</div>","alt":[]},"12307":{"h":"כְּזִיב","r":"K00445","html":"<div class=\"sense\"> (b. h.) pr. n. pl. <i>Chezib</i>, v. <a href=\"#\" data-headword=\"אַכְזִיב\">אַכְזִיב</a>. <span class=\"citation\">Ḥall. IV, 8</span> (Y. ed. <a href=\"#\" data-headword=\"גְּזִיב\">גְּזִיב</a>). <span class=\"citation\">Dem. I, 3</span> (Y. ed. <a href=\"#\" data-headword=\"ג׳\">ג׳</a>, Ms. M. <span dir=\"rtl\">גויב</span>, corr. acc.); a. fr.</div>","alt":[]},"12308":{"h":"כַּזַּיִת","r":"K00446","html":"<div class=\"sense\"><b>,</b> v. <a href=\"#\" data-headword=\"זַיִת\">זַיִת</a></div>","alt":[]},"12309":{"h":"כזניתא","r":"K00447","html":"<div class=\"sense\">, Y. Kidd. I, 60ᵇ top, v. <a href=\"#\" data-headword=\"*זַגִּיתָא\">זַגִּיתָא</a></div>","alt":[]},"12310":{"h":"כְּזַר","r":"K00448","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"*כְּזַז\">כזז</a>) <i>to shrink; to be hard</i> (v. <a href=\"#\" data-headword=\"אַכְזָר\">אַכְזָר</a> a. denom.).</div><div class=\"sense\"><b>Ithpe. אִתְכְּזַר</b> <div class=\"sense\"><i>to loathe</i>. <span class=\"citation\">Targ. Job. X, 1</span> אִתְכַּזְרִית וכ׳ Ms. (Var. <span dir=\"rtl\">אתבזיית</span>, ed. <span dir=\"rtl\">אתגזרַת</span>) I myself loathe my life.</div></div>","alt":[]},"12311":{"h":"כָּח","r":"K00449","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּחַח\">כָּחַח</a></div>","alt":[]},"12312":{"h":"כֹּחַ","r":"K00450","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"יָכַח\">יָכַח</a>) <i>firmness, strength, power</i>. <span class=\"citation\">Hor. 9ᵃ</span> <span dir=\"rtl\">בנוי בכ׳ וכ׳</span> in beauty, in physical strength, &amp;c. <span class=\"citation\">Ḥag. 12ᵃ</span>. <span class=\"citation\">Snh. 96ᵃ</span> <span dir=\"rtl\">תשש כֹּחוֹ</span> his strength failed him. <span class=\"citation\">Ber. 63ᵃ</span> <span dir=\"rtl\">כל … אין בו כח וכ׳</span> he who is careless about the study of the Law, will have no strength to endure on the day of trouble; a. v. fr.—<span class=\"citation\">Bets. 2ᵇ</span>, a. fr. (mixed diction) <span dir=\"rtl\">להוריעך … כֹּחָן</span> to show the power of …, i.e. how far-reaching are the consequences of the opinion of … Ib., a. fr. <span dir=\"rtl\">כח דהיתרא עדיף</span> showing the power of the more lenient opinion is preferred (as an evidence of courage of conviction, while the more rigid opinion may be the outcome of doubt).—כח כֹּחוֹ <i>indirect action</i>, opp. <span dir=\"rtl\">כֹּחוֹ</span> direct action. <span class=\"citation\">B. Kam. 18ᵃ</span> שאני … בין נזק כחו לכח כחו S. distinguishes between direct and indirect injury. <span class=\"citation\">Ib. 19ᵃ</span>. <span class=\"citation\">Macc. 8ᵃ</span>.—<span class=\"citation\">Ab. Zar. 60ᵃ</span> <span dir=\"rtl\">כ׳ כ׳</span> pressing wine by turning a wheel. <span class=\"citation\">B. Kam. 10ᵇ</span>, v. <a href=\"#\" data-headword=\"לַאו\">לַאו</a>.—<span class=\"citation\">Snh. 77ᵇ</span> <span dir=\"rtl\">כ׳ ראשון</span> direct agency, <span dir=\"rtl\">כ׳ שני</span> indirect agency.—<span class=\"citation\">Shebu. 48ᵃ</span>, a. fr. <span dir=\"rtl\">יפה כ׳</span>, v. <a href=\"#\" data-headword=\"יָפֶה\">יָפֶה</a>.—Ohol. XVIII, 6 <span dir=\"rtl\">שכֹּחָן יפה</span> who (which) can endure pressure without shaking, opp. <span dir=\"rtl\">כחן רע</span>; <span class=\"citation\">Zab. III, 1</span>; <span class=\"citation\">B. Mets. 105ᵇ</span>; a. e.—<span class=\"citation\">Gen. R. s. 98</span>, v. <a href=\"#\" data-headword=\"לִיבְדְּקוֹס\">לִיבְדְּקוֹס</a>. Y. Pes. I, 27ᶜ bot. <span dir=\"rtl\">ל&quot;ת שבא מכח עשה</span> a prohibition derived from a positive law, v. <a href=\"#\" data-headword=\"לַאו\">לַאו</a>; a. fr.—Trnsf. <i>coition</i>. <span class=\"citation\">Yeb. 34ᵃ</span></div>","alt":["כּוֹחַ"]},"12313":{"h":"כֹּחַ ²","r":"K00451","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"כֹּחַ\">same</a>. <span class=\"citation\">Targ. Lam. I, 6</span>.—<span class=\"citation\">Bets. 2ᵇ</span>, a. fr. (mostly in Hebrew form), v. supra.</div><div class=\"sense\"><b>—2)</b>  name of a <i>lizzard</i>. <span class=\"citation\">Targ. Lev. XI, 30</span> (h. text <span dir=\"rtl\">כח</span>).</div><div class=\"sense\"><b>—3)</b>  <span dir=\"rtl\">בַּר כּוֹחָא</span> pr. n. m. <i>Bar-Koḥa</i>. Y. Sabb. XIV, 14ᵈ bot.</div>","alt":["כֹּחָא","כּוֹ׳"]},"12314":{"h":"כָּחַד","r":"K00452","html":"<div class=\"sense\"><i>to diminish</i>.</div><div class=\"sense\"><b>Pi. כִּיחֵד</b> <div class=\"sense\"><i>to withhold, deny</i>. <span class=\"citation\">Num. R. s. 13</span> <span dir=\"rtl\">לא כ׳ מיעקב</span></div></div><div class=\"sense\"><b>Hif. הִכְחִיד</b> <div class=\"sense\"><i>to destroy</i>. <span class=\"citation\">Num. R. s. 20</span> <span dir=\"rtl\">לקללן ולהַכְחִידָן</span> to curse and destroy them. <span class=\"citation\">Ex. R. s. 12</span>; a. e.</div></div><div class=\"sense\"><b>Nif. נִכְחָד</b> <div class=\"sense\"><i>to be destroyed</i>. Ib. <span dir=\"rtl\">היית נ׳ מן וכ׳</span> thou wouldst have been wiped out from the earth.</div></div>","alt":[]},"12315":{"h":"כְּחַד","r":"K00453","html":"<div class=\"sense\">[Y. Sabb. VII, 10ᵃ bot. <span dir=\"rtl\">מכחד</span>, v. <a href=\"#\" data-headword=\"בְּחַר\">בְּחַר</a>.]</div><div class=\"sense\"><b>Ithpa. אִתְכַּחַד</b> <div class=\"sense\"><i>to be destroyed</i>. <span class=\"citation\">Targ. Job IV, 7</span>.</div></div>","alt":[]},"12316":{"h":"כַּחַד","r":"K00454","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> constr. (<a href=\"#\" data-headword=\"כְּחַד\">preced.</a>) <i>missing, being missed</i>. <span class=\"citation\">Targ. Ps. CXXXIX, 16</span> (ed. Lag. a. oth. <span dir=\"rtl\">בחד</span>, Var. <a href=\"#\" data-headword=\"כ׳\">כ׳</a>).</div>","alt":[]},"12317":{"h":"כַּחֲדָא","r":"K00455","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חֲדָא I\"><span dir=\"rtl\">חֲדָא</span> I</a></div>","alt":[]},"12318":{"h":"כָּחַהּ","r":"K00456","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כָּחַח\">כָּחַח</a></div>","alt":[]},"12319":{"h":"כְּחוֹל","r":"K00457","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוֹחָל\">כּוֹחָל</a></div>","alt":[]},"12320":{"h":"כָּחוּשׁ","r":"K00458","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <a href=\"#\" data-headword=\"כָּפוּרְתָּא\">כְּחוּשָׁה</a> f. <i>lean, weak</i>, v. <a href=\"#\" data-headword=\"כָּחַשׁ\">כָּחַשׁ</a>.</div>","alt":[]},"12321":{"h":"כָּחַח","r":"K00459","html":"<div class=\"sense\"> (onomatop., cmp. <a href=\"#\" data-headword=\"חָכַךְ II\"><span dir=\"rtl\">חָכַךְ</span> II</a>) [<i>to scratch</i>,] <i>to cough, to bring up mucus</i>. <span class=\"citation\">Erub. 99ᵃ</span> <span dir=\"rtl\">כָּח בפני רבו</span> (not <a href=\"#\" data-headword=\"כִּיחַ\">כיח</a>, v. Rabb. D. S. a. l. note 16) he who coughs in sight of his teacher, expl. ib. <span dir=\"rtl\">כח ורק</span> (not <a href=\"#\" data-headword=\"כִּיחַ\">כיח</a>) when he coughs and spits out. Tosef. ib. XI (VIII), 8 <span dir=\"rtl\">הכּוֹחֶה וכ׳</span> (fr. <a href=\"#\" data-headword=\"כָּחַהּ\">כָּחַהּ</a>) he who coughs (brings mucus up in his mouth) in the street. Tanḥ. Noah 9 <span dir=\"rtl\">גונח וכוֹהֶה דם</span> coughing and spitting blood; (Tanḥ. ed. Bub. ib. 14 <span dir=\"rtl\">גונח מלבו</span>), v. <a href=\"#\" data-headword=\"גָּנַח\">גָּנַח</a>.</div>","alt":[]},"12322":{"h":"כָּחִישׁ","r":"K00460","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּחַשׁ\">כְּחַשׁ</a>) <i>lean, weak</i>. <span class=\"citation\">Kidd. 24ᵇ</span> <span dir=\"rtl\">נהורא כ׳</span> feeble eye-sight, opp. <span dir=\"rtl\">בריא</span> normal. <span class=\"citation\">B. Bath. 155ᵇ</span> <span dir=\"rtl\">אי כ׳ … ליברי</span> if he is lean, we let him be fattened. <span class=\"citation\">B. Mets. 105ᵇ</span> <span dir=\"rtl\">הוה כ׳ ארעא</span> the soil was exhausted, opp. <span dir=\"rtl\">שמינא</span>.—Pl. <span dir=\"rtl\">כְּחִישִׁין</span>, f. <a href=\"#\" data-headword=\"כָּחִישׁ\">כְּחִישָׁתָא</a>. <span class=\"citation\">Targ. Y. Gen. XLI, 27</span>.—<span class=\"citation\">B. Kam. 118ᵇ</span>, opp. <span dir=\"rtl\">ברייתא</span>.</div>","alt":["כְּחִישָׁא","כְּחִישָׁא","כְּחִישְׁתָּא"]},"12323":{"h":"כְּחִישׁוּתָא","r":"K00461","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּחִישׁ\">preced.</a>) <i>reduction, weakness, leanness</i>. <span class=\"citation\">Targ. Koh. XII, 5</span>.—<span class=\"citation\">Yeb. 79ᵇ</span> <span dir=\"rtl\">כ׳ דאתחילא ביה</span> it was weakness that befell him (but no organic defect). <span class=\"citation\">Bekh. 45ᵇ</span> <span dir=\"rtl\">כ׳ אתחלא וכ׳</span> it is a weakness of the right hand, v. <a href=\"#\" data-headword=\"בְּרִיאוּתָא\">בְּרִיאוּתָא</a>. <span class=\"citation\">B. Bath. 155ᵇ</span>; a. e.</div>","alt":[]},"12324":{"h":"כֹּחָל","r":"K00462","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כּוֹתָל\">כּוֹתָל</a></div>","alt":[]},"12325":{"h":"כָּחַל","r":"K00463","html":"<div class=\"sense\"><i>to paint the eyelids</i> (for medical or for cosmetic purposes). <span class=\"citation\">Sabb. VIII, 3</span> (<span class=\"citation\">78ᵇ</span>) <span dir=\"rtl\">כדי לִכְחוֹל וכ׳</span> a quantity sufficient for painting one eye. <span class=\"citation\">Sabb. 80ᵃ</span> <span dir=\"rtl\">צנועות כּוֹחֲלוֹת וכ׳</span> chaste (veiled) women paint only one eye. <span class=\"citation\">Ib. X, 6</span> <span dir=\"rtl\">הכּוֹחֶלֶת</span> she who paints her eyes (on the Sabbath); a. fr.—Part. pass. <span dir=\"rtl\">כָּחוּל</span>; f. <span dir=\"rtl\">כְּחוּלָה</span>, pl. <a href=\"#\" data-headword=\"כְּפוּלוֹת\">כְּחוּלוֹת</a>. <span class=\"citation\">Gen. R. s. 98</span> (play on <span dir=\"rtl\">ח̇כ̇ל̇ילי</span>, <span class=\"citation\">Gen. XLIX, 12</span>) <span dir=\"rtl\">שעיניהם כ̇ח̇ול̇ות וכ̇ח̇ם יפה וכ׳</span> whose eyes are bright as if painted, and whose abilities for study are fine. [Y. Sabb. VII, 10ᵃ top <span dir=\"rtl\">להכחיל</span>, <span dir=\"rtl\">מכחיל</span>, v. <a href=\"#\" data-headword=\"בָּחַל II\"><span dir=\"rtl\">בָּחַל</span> II</a>.]</div>","alt":[]},"12326":{"h":"כְּחַל I","r":"K00464","html":"<div class=\"sense\"></div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"כָּחַל\">same</a>. <span class=\"citation\">Targ. II Kings IX, 30</span>; a. e.—<span class=\"citation\">Sabb. 80ᵃ</span> <span dir=\"rtl\">עין … הא לא כַחֲלֵי</span> but people never paint one eye only!</div><div class=\"sense\"><b>—2)</b>  (ironically, v. infra) <i>to blind the eyes</i>. <span class=\"citation\">Ber. 58ᵃ</span> <span dir=\"rtl\">חברוהי כַחְלִינְהוּ וכ׳</span> his associates put his eyes out, v. <a href=\"#\" data-headword=\"כְּבִי\">כְּבִי</a>.—[<span class=\"citation\">Y. Ab. Zar. II, 40ᵈ</span> top <span dir=\"rtl\">כחל לה</span>, read in one w., v. <a href=\"#\" data-headword=\"חֲלָלָא\">חֲלָלָא</a>.]</div><div class=\"sense\"><b>Ithpe. אִיכְּחַל</b> <div class=\"sense\"><i>to be painted</i>. <span class=\"citation\">Nidd. 55ᵇ</span> if one desires to become blind, <span dir=\"rtl\">לִיכְּחוֹל מארמאי</span> (<span dir=\"rtl\">מעכ&quot;ום</span>) let him have his eyes painted by gentiles; Y. Ab. Zar. l. c. <span dir=\"rtl\">מִיכְּחוּל מינהון</span>.</div></div>","alt":[]},"12327":{"h":"כָּחָל","r":"K00465","html":"<div class=\"sense\"> (tradit. pronunc. <a href=\"#\" data-headword=\"כְּחַל I\">כְּחַל</a>) m. (prob. from its reddish color, v. <a href=\"#\" data-headword=\"כַּחֲלֵי\">כַּחֲלֵי</a>) <i>udder, bag</i>. <span class=\"citation\">Ḥull. VIII, 3</span>. <span class=\"citation\">Tosef. ib. VIII, 8</span> <span dir=\"rtl\">כ׳ של מניקה</span> the bag of a milk-cow; a. fr.</div>","alt":[]},"12328":{"h":"כְּחַל II","r":"K00466","html":"<div class=\"sense\"> [<span class=\"citation\">Targ. Ps. LXXIV, 6</span> some ed., read <a href=\"#\" data-headword=\"כְּחַל II\">כַּחֲרָא</a>.]—<span class=\"citation\">Ḥull. 110ᵃ</span> תבשילא דכחלא Ar. (ed. <span dir=\"rtl\">דכחל</span>) a dish made of udder.—Pl. <a href=\"#\" data-headword=\"כַּחֲלֵי\">כַּחֲלֵי</a>. Ib. <span dir=\"rtl\">בסורא … כ׳</span> in Sura they do not eat udders. Ib. <span dir=\"rtl\">אפקינהו כ&quot;ע לכַחְלַיְיהוּ</span> (not <span dir=\"rtl\">לכחלינהו</span>) all of them brought out the udders they were about to cook.</div>","alt":["כַּחֲלָא"]},"12329":{"h":"כַּחֲלֵי","r":"K00467","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"כּוֹחֲלִין\">כּוֹחֲלִין</a>, <i>carbuncle</i>. <span class=\"citation\">Targ. Cant. V, 14</span> (corresp. to <a href=\"#\" data-headword=\"נֹפֶךְ\">נֹפֶךְ</a>, <span class=\"citation\">Ex. XXVIII, 13</span>).</div>","alt":[]},"12330":{"h":"כחלינהו","r":"K00468","html":"<div class=\"sense\"><b>,</b> <span class=\"citation\">Ḥull. 110ᵃ</span>, v. <a href=\"#\" data-headword=\"כְּחַל II\"><span dir=\"rtl\">כְּחַל</span> II</a></div>","alt":[]},"12331":{"h":"כָּחַשׁ","r":"K00469","html":"<div class=\"sense\"><b>1)</b> <i>to fail, be reduced, be lean</i>, opp. <span dir=\"rtl\">בריא</span>, <a href=\"#\" data-headword=\"שָׁמֵן I\">שמן</a>. <span class=\"citation\">B. Kam. 34ᵃ</span> <span dir=\"rtl\">כ׳ כשעת וכ׳</span> if the injured ox became reduced after being wounded, damage is assessed according to the value at the time of standing before court; Y. ib. III, end, 3ᵈ <a href=\"#\" data-headword=\"כָּחַשׁ\">הִכְחִישׁ</a>. <span class=\"citation\">Gen. R. s. 53</span> (ref. to <span class=\"citation\">Hab. III, 17</span>) <span dir=\"rtl\">כּוֹחֲשִׁים היו</span> (Sarah’s face) was haggard (and the announcement of the angels made it shine like olive oil); Yalk. Hab. 565 <span dir=\"rtl\">כְּחוּשִׁים</span>; [oth. interpret., v. infra].—<i>Part. pass</i>. <a href=\"#\" data-headword=\"כָּחוּשׁ\">כָּחוּשׁ</a>, f. <span dir=\"rtl\">כְּחוּשָה</span>; pl. <span dir=\"rtl\">כְּחוּשִׁים</span>, <span dir=\"rtl\">כְּחוּשׁוֹת</span> <i>lean, reduced, weak</i>. <span class=\"citation\">Snh. 78ᵃ</span> <span dir=\"rtl\">כח כ׳</span> a weak force. <span class=\"citation\">Ḥull. 97ᵃ</span> (in Chald. diction). <span class=\"citation\">B. Kam. 6ᵇ</span> <span dir=\"rtl\">אכל כ׳</span> if he ate fruits of a garden-bed with scanty fruits; <span class=\"citation\">Gitt. 48ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"כָּזַב\">כָּזַב</a>) <i>to be false</i>. Gen. R. l. c. <span dir=\"rtl\">כּוֹחֲשִׁים היו</span> were they (the angels) false (deceiving)?—</div><div class=\"sense\"><b>Hif. הִכְחִישׁ</b> <div class=\"sense\"><b>1)</b> <i>to be reduced, fail, deteriorate</i>. Y. B. Kam. l. c., v. supra.—<span class=\"citation\">Meïl. 17ᵃ</span> <span dir=\"rtl\">מי שיש … יַכְחִישׁ וכ׳</span> if you have an enemy, do you desire him to be weak or strong? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ימולו … ויַכְחִישׁוּ</span> let their children be circumcised …, and they will become weak. <span class=\"citation\">Yeb. 34ᵇ</span> <span dir=\"rtl\">ויַכְחִישׁ יופיה</span> her beauty may be ruined. Y. M. Kat. I, beg. 80ᵃ <span dir=\"rtl\">עמדה מלהַכְחִישׁ</span> if the field ceased to deteriorate; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to lessen, reduce, ruin, weaken</i>. <span class=\"citation\">Gitt. 70ᵃ</span> <span dir=\"rtl\">ג׳ … מַכְחִישִׁים כחו וכ׳</span> three things lessen a man’s energies. <span class=\"citation\">Snh. 84ᵇ</span> <span dir=\"rtl\">הִכְחִישָׁחּ באבנים</span> he ruined the animal by loading stones upon her (without causing a wound). Y. B. Kam. l. c. <span dir=\"rtl\">הִכְחִישׁוֹ חמשים וכ׳</span> he lessened his (the ox’s) value by fifty Zuz. <span class=\"citation\">Esth. R. to I, 1</span> (play on <span dir=\"rtl\">אח̇ש̇ור̇ש̇</span>) <span dir=\"rtl\">שהכח̇יש̇ ר̇אש̇ן וכ׳</span> he caused haggardness to the heads of &amp;c. <span class=\"citation\">Sabb. 22ᵃ</span> <span dir=\"rtl\">מַכְחִישׁ מצוה</span> he impairs the religious act (lessens the brightness of the Ḥănuckah lights). <span class=\"citation\">Snh. 67ᵇ</span>; <span class=\"citation\">Ḥull. 7ᵇ</span>, v. <span dir=\"rtl\">כְּשָׁפִים</span>; a. fr.—[<span class=\"citation\">Yalk. Ps. 627</span> <a href=\"#\" data-headword=\"כְּנַשׁ\">אַכְחֵישׁ</a>, v. <a href=\"#\" data-headword=\"כָּעַס\">כָּעַס</a>.]</div><div class=\"sense\"><b>—3)</b> <i>to declare false, deny, contradict</i>, v. <a href=\"#\" data-headword=\"הַכְחָשָׁה\">הַכְחָשָׁה</a>. <span class=\"citation\">Keth. 20ᵃ</span> <span dir=\"rtl\">כשם שאין מזימין … אין מַכְחִישִׁין וכ׳</span> as an evidence of alibi cannot be taken up except by confrontation, so cannot contradictory evidence &amp;c. <span class=\"citation\">Ber. 27ᵇ</span> <span dir=\"rtl\">יכול החי להַבְחִישׁ וכ׳</span> can the living contradict the living? <span class=\"citation\">Gen. R. s. 48</span>, beg. <span dir=\"rtl\">מפני מה אתה מַכְחִישֵׁנִי וכ׳</span> why dost thou contradict me (declare me wrong) in the presence of my servant?—Sifra introd., v. <a href=\"#\" data-headword=\"כָּרַע\">כָּרַע</a>; a. fr.</div></div><div class=\"sense\"><b>Pi. כִּיחֵשׁ</b> <div class=\"sense\"><i>to be false; to flatter</i>. <span class=\"citation\">Sifré Deut. 356</span> <span dir=\"rtl\">בשעת מְכַחֲשִׁים להם …</span> when the Israelites prosper, the nations flatter them; Yalk. Deut. 967.</div></div><div class=\"sense\"><b>Hof. הוּכְחָשׁ</b> <div class=\"sense\"><i>to be contradicted, rebutted</i>. <span class=\"citation\">B. Kam. 74ᵇ</span> <span dir=\"rtl\">עדים שהוּכְחֲשׁוּ בנפש</span> witnesses that have been contradicted in a capital case.—<span class=\"citation\">Ib.</span> <span dir=\"rtl\">מוּכְחָשִׁין</span> witnesses whose evidence has been contradicted (but not rebutted through an alibi). Keth. l. c. <span dir=\"rtl\">עדות מוּכְחֶשֶׁת</span> a rebutted evidence; a. fr.</div></div><div class=\"sense\"><b>Hithpa. הִתְכַּחֵשׁ</b> <div class=\"sense\"><i>to contradict each other</i>. <span class=\"citation\">Sifré Deut. 37</span> <span dir=\"rtl\">מִתְכַּחֲשׁוֹת</span>; v., however, <a href=\"#\" data-headword=\"כָּתַשׁ\">כָּתַשׁ</a>.</div></div>","alt":[]},"12332":{"h":"כְּחַשׁ","r":"K00470","html":"<div class=\"sense\">, <i>to be lean, weak</i>; v. <a href=\"#\" data-headword=\"כָּחִישׁ\">כָּחִישׁ</a>.—<span class=\"citation\">Snh. 95ᵃ</span> <span dir=\"rtl\">כ׳ חיליה</span> his strength failed him. <span class=\"citation\">B. Mets. 104ᵇ</span> (prov.) <span dir=\"rtl\">תִּכְחוֹשׁ ארעא ולא לִיכְּחוּשׁ מרה</span> Ms. M. (ed. <a href=\"#\" data-headword=\"כַּחֲשָׁא\">כחשא</a>) let the land deteriorate (exhausted by strong seeds) rather than that its owner become reduced (by reduced income); a. e.</div><div class=\"sense\"><b>Af. אַכְחַשׁ</b> <div class=\"sense\"><b>1)</b> <i>to reduce, weaken, impair</i>. <span class=\"citation\">Nidd. 47ᵇ</span>; <span class=\"citation\">Yeb. 97ᵃ</span> <span dir=\"rtl\">אַכְחֲשׁוּהוּ</span> reduce him (by scanty food); <span class=\"citation\">B. Bath. 155ᵇ</span> אכחשיה Ms. M. (corr. acc., ed. <span dir=\"rtl\">ליכחוש</span>, v. infra). <span class=\"citation\">B. Kam. 34ᵃ</span> <span dir=\"rtl\">את מַכְחֲשָׁהּ ואנא וכ׳</span> thou didst ruin her (by neglect), and I should pay for it?</div><div class=\"sense\"><b>—2)</b> <i>to contradict</i>. <span class=\"citation\">Gen. R. s. 48</span>, beg. <span dir=\"rtl\">אַכְחֲשָׁהּ קדמה</span> he contradicted her (his wife) in her (the servant’s) presence.</div></div><div class=\"sense\"><b>Ithpe. אִתְכְּחִישׁ  אִיכְּחוּשׁ</b> <div class=\"sense\"><b>1)</b> <i>to reduce one’s self, to be reduced</i>. B. Bath. l. c. <span dir=\"rtl\">לִיכְּחוּשׁ</span> let him reduce himself. B. Mets. l. c., v. supra.</div><div class=\"sense\"><b>—2)</b> <i>to be contradicted, rebutted</i>. <span class=\"citation\">B. Kam. 74ᵃ</span> <span dir=\"rtl\">מִתְכַּחֲשֵׁי</span> are contradicted, contrad. to <span dir=\"rtl\">מיתזמי</span>, v. <a href=\"#\" data-headword=\"זְמַם I\"><span dir=\"rtl\">זְמַם</span> I</a>.—<span class=\"citation\">Snh. 81ᵇ</span> <span dir=\"rtl\">אִתְכְּחוּשׁ בבדיקות</span> they contradicted each other in cross-examinations, v. <a href=\"#\" data-headword=\"בְּדִיקָה\">בְּדִיקָה</a>.</div></div>","alt":[]},"12333":{"h":"כַּחֲשָׁא","r":"K00471","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כְּחַשׁ\">preced.</a>) <i>reduction, deterioration</i>. <span class=\"citation\">B. Kam. 59ᵃ</span> <span dir=\"rtl\">כַּחַשׁ גופנא</span> the weakening of the vine (by allowing the grapes to remain on it until they are ripe). <span class=\"citation\">B. Mets. 101ᵇ</span> <span dir=\"rtl\">משום כ׳ דארעא</span> because he exhausted the soil by planting trees. <span class=\"citation\">Ib. 104ᵇ</span> <span dir=\"rtl\">מנכי ליה כ׳ דארעא</span> he must allow him a reduction of his rent in consideration of the lesser exhaustion of the soil (by having planted wheat in place of poppy).</div>","alt":[]},"12334":{"h":"כטספטייס","r":"K00472","html":"<div class=\"sense\">, <span class=\"citation\">Ab. Zar. 39ᵃ</span> ed., Ms. M. <span dir=\"rtl\">כספטייס</span>, <span class=\"citation\">Ḥull. 66ᵇ</span>; <span class=\"citation\">Tosef. ib. III</span> (<span class=\"citation\">IV), 27</span> <a href=\"#\" data-headword=\"כספתיאס\">כספתיאס</a>, a corrupt. of <span dir=\"rtl\">כְּסִיפְיָיס</span>, <span dir=\"rtl\">כְּסִיפְיָאס</span> (ξίφιας) <i>sword-fish</i>, v. <a href=\"#\" data-headword=\"*אכספטיאס\">אכספטיאס</a>.</div>","alt":[]},"12335":{"h":"כי","r":"K00473","html":"<div class=\"sense\"><i>the Greek letter Chi</i> (χ). <span class=\"citation\">Men. VI, 3</span> <span dir=\"rtl\">כמין כי</span>, expl. <span class=\"citation\">ib. 75ᵃ</span> <span dir=\"rtl\">כמין כי יוני</span> (Ar. <a href=\"#\" data-headword=\"יְוָנִי\">יונית</a>) drawing the figure of a Greek Chi; Tosef. ib. VIII, 8; 10; <span class=\"citation\">Ker. 5ᵇ</span>; <span class=\"citation\">Hor. 12ᵃ</span>, expl. <span dir=\"rtl\">כמין כף יוני</span> ed. (Ms. M. <a href=\"#\" data-headword=\"כי\">כי</a>). <span class=\"citation\">Kel. XX, 7</span>.</div>","alt":["כ\"י"]},"12336":{"h":"כֵּי","r":"K00474","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"כְּאֵי\">כְּאֵי</a>, v. <a href=\"#\" data-headword=\"אֵי III\"><span dir=\"rtl\">אֵי</span> III</a>) <i>like which?</i>; <span dir=\"rtl\">כֵּי זֶה צַד</span>, <span dir=\"rtl\">כֵּיזֶה צד</span> <i>how?</i>, <i>in what manner?</i> <span class=\"citation\">Tosef. B. Kam. III, 4</span>. <span class=\"citation\">Tosef. Ter. I, 5</span>; a. fr. ed. Zuck. (ed. usu. <a href=\"#\" data-headword=\"כֵּיצַד\">כֵּיצַד</a>).</div>","alt":[]},"12337":{"h":"כִּי","r":"K00475","html":"<div class=\"sense\"> v. <span dir=\"rtl\">כּ־</span>) </div><div class=\"sense\"><b>1)</b> <i>like</i>. <span class=\"citation\">Sot. 35ᵇ</span> <span dir=\"rtl\">כי סיד</span> like lime. Y. Yeb. XVI, end, 16ᵃ <span dir=\"rtl\">כי חיה</span> like a lying-in woman; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>when</i>. <span class=\"citation\">Ex. R. s. 9</span>, beg. (ref. to <span class=\"citation\">Ex. VII, 9</span>) … <span dir=\"rtl\">אם ידבר אלא כי וכ׳</span> it does not read, ‘<i>if</i> Pharaoh …, but <i>when</i> …; he <i>will</i> say so. <span class=\"citation\">R. Hash. 3ᵃ</span>, v. <a href=\"#\" data-headword=\"אִי II\"><span dir=\"rtl\">אִי</span> II</a>.</div><div class=\"sense\"><b>—3)</b>  so, <i>thus</i>. <span class=\"citation\">Y. Ḥag. III, 77ᵇ</span> <span dir=\"rtl\">וכי היה המעשה</span> and thus it came to pass. <span class=\"citation\">Yeb. VIII, 3</span> <span dir=\"rtl\">לא כי הלכה וכ׳</span> (some ed. <span dir=\"rtl\">לא כי אלא וכ׳</span>) it is not so; I am reciting a Halakhah. <span class=\"citation\">Shek. I, 4</span> <span dir=\"rtl\">לא כי אלא וכ׳</span> it is not so, but &amp;c. <span class=\"citation\">B. Kam. 25ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—4)</b> <i>for</i>. <span class=\"citation\">Yoma 87ᵇ</span> (quoting from a prayer) <span dir=\"rtl\">כי עונותינו וכ׳</span></div><div class=\"sense\"><b>—5)</b>  <span dir=\"rtl\">וְכִי</span> (introducing a question to which a negative answer is expected) <i>is it really so that?</i> <span class=\"citation\">R. Hash. 9ᵃ</span> <span dir=\"rtl\">וכי בתשעה … והלא וכ׳</span> do we fast on the ninth? Is it not the tenth &amp;c.? <span class=\"citation\">Sabb. 4ᵃ</span> <span dir=\"rtl\">וכי אומרים וכ׳</span> dare we say to a man &amp;c.?; <span class=\"citation\">Men. 48ᵃ</span>. <span class=\"citation\">Yoma 7ᵃ</span>; a. v. fr.</div>","alt":[]},"12338":{"h":"כִּי ²","r":"K00476","html":"<div class=\"sense\"><b>1)</b> <i>as, like</i>. <span class=\"citation\">Targ. Is. XIV, 19</span>, v. <a href=\"#\" data-headword=\"יְחַט\">יְחַט</a>; a. fr., v. <a href=\"#\" data-headword=\"כְּ־\">כְּ־</a>.—<span class=\"citation\">M. Kat. 28ᵇ</span> <span dir=\"rtl\">מותא כי מותא וכ׳</span> death like death, i.e. death must naturally ensue, v. <a href=\"#\" data-headword=\"חֲבוּלְיָא\">חֲבוּלְיָא</a>. <span class=\"citation\">Sabb. 140ᵇ</span>. v. <a href=\"#\" data-headword=\"אוּרְכָּא\">אוּרְכָּא</a>.—<span class=\"citation\">Kidd. 81ᵃ</span> <span dir=\"rtl\">יומא כי האידנא</span> on a day like this.—<span dir=\"rtl\">כי הא ד־</span> as that which is told of &amp;c. <span class=\"citation\">Pes. 117ᵃ</span>; a. fr.—<span class=\"citation\">Ḥag. 2ᵃ</span>, a. fr. <span dir=\"rtl\">דלא כי האי תנא</span> which is not in agreement with the opinion of &amp;c.—<span class=\"citation\">B. Kam. 46ᵃ</span> <span dir=\"rtl\">לְכִי הא דאיתמר</span> for a case like the one that is told.—<span class=\"citation\">Ned. 49ᵃ</span>, a. fr. <span dir=\"rtl\">כי אתריה</span>, v. <a href=\"#\" data-headword=\"אָתַר\">אֲתַר</a>.—<span class=\"citation\">Hor. 13ᵇ</span> <span dir=\"rtl\">נתקין … כי לדידן</span> let us institute something like that which has been done concerning ourselves; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>when</i>. <span class=\"citation\">Targ. Y. II, Lev. XXVI, 44</span>; a. fr.—<span class=\"citation\">Ḥull. 110ᵃ</span>; <span class=\"citation\">B. Bath. 87ᵃ</span> <span dir=\"rtl\">כי סליק וכ׳</span> when R. El. went to Palestine. <span class=\"citation\">Snh. 74ᵃ</span>, a. fr. <span dir=\"rtl\">כי אתא וכ׳</span> when R. … came (from Palestine).—<span dir=\"rtl\">וכי תימא</span> (abbr. <span dir=\"rtl\">וכ&quot;ת</span>), v. <a href=\"#\" data-headword=\"אֲמָא II\"><span dir=\"rtl\">אֲמָא</span> II</a>.—<span class=\"citation\">Y. Snh. VII, end, 25ᵈ</span> <span dir=\"rtl\">כי יתבון וכ׳</span> (not <a href=\"#\" data-headword=\"כַּיי\">כיי</a>) when they sat down to eat; a. v. fr.—<span dir=\"rtl\">כי היכי</span> a) <i>in order that</i>, v. <a href=\"#\" data-headword=\"הֵיכִי\">הֵיכִי</a>.—b) <i>as well as, in the same way as</i>. <span class=\"citation\">Taan. 9ᵇ</span> <span dir=\"rtl\">כי ה׳ … הכי וכ׳</span> as the Babylonians are deceitful, so are their rains; a. fr.—[<span dir=\"rtl\">כַּי</span>, v. <a href=\"#\" data-headword=\"כַּיי\">כַּיי</a>.]</div>","alt":[]},"12339":{"h":"*כִּיאוּרָא","r":"K00477","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"כָּאַר\">כָּאַר</a>) <i>ugliness</i>. <span class=\"citation\">Sabb. 62ᵇ</span> Ms. M., v. <a href=\"#\" data-headword=\"כֵּיבָא\">כֵּיבָא</a>.</div>","alt":[]},"12340":{"h":"כיארי","r":"K00478","html":"<div class=\"sense\">, Y. Dem. II, beg. 22ᵇ (R. S. to ib. II, 1 <span dir=\"rtl\">בראי׳</span>) prob. to be read: <a href=\"#\" data-headword=\"בְּאֵרַי\">בְּאֵרַיי</a> or <a href=\"#\" data-headword=\"בֵּירַאי\">בֵּירַאי</a>.</div>","alt":[]},"12341":{"h":"כֵּיב","r":"K00479","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּאֵב I\"><span dir=\"rtl\">כְּאֵב</span> I</a></div>","alt":[]},"12342":{"h":"כֵּיבָא","r":"K00480","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כֵּיב\">preced.</a>) <i>pain, sore</i>, v. <a href=\"#\" data-headword=\"כְּאֵבָא\">כְּאֵבָא</a>. <span class=\"citation\">Targ. Job V, 18</span>; a. e.—<span class=\"citation\">B. Kam. 46ᵇ</span>, v. <a href=\"#\" data-headword=\"כְּאֵב I\"><span dir=\"rtl\">כְּאֵב</span> I</a>. <span class=\"citation\">Lam. R. to II, 1</span> <span dir=\"rtl\">אית … לכ׳ עייבא</span> there is a place where they call a sore ͑<i>ayba</i> (heaviness), v. <a href=\"#\" data-headword=\"כְּאֵב I\">כְּאֵב</a> I <i>Pa</i>.—Esp. <i>ulcer, ulceration</i> (mostly as a collective noun). <span class=\"citation\">Sabb. 62ᵇ</span> (ref. to <span class=\"citation\">Is. III, 24</span>) <span dir=\"rtl\">חלף שופרי כ׳</span> instead of beauty ulcers; [Kimḥi quotes <a href=\"#\" data-headword=\"כְּוָאָה\">כְּוָאָה</a>; Ms. M. <span dir=\"rtl\">כיבא כיאורא</span>, combining two versions]. <span class=\"citation\">Kidd. 39ᵇ</span> <span dir=\"rtl\">שיחנא וכ׳</span> scabs and ulcers. <span class=\"citation\">Ib. 81ᵃ</span> [read:] <span dir=\"rtl\">יתיב עליה מלא נפשיה שיחנא וכ׳</span> he sat down before it (the tray), his body being full of &amp;c.—<span class=\"citation\">Sabb. 67ᵃ</span> לכ׳ לימא הכי Ar. (ed. <a href=\"#\" data-headword=\"כִּיפְתָא\">כיפא</a>, Ar. s. v. <a href=\"#\" data-headword=\"כס\">כס</a> :<span dir=\"rtl\">כיסא</span>) against ulcers say the following charm.—Pl. <span dir=\"rtl\">כֵּיבִין</span>. Ib. <span dir=\"rtl\">שיחנין וכ׳</span> Ms. M. (ed. <span dir=\"rtl\">שחינ׳ כְּאֵיבִין</span>, read <span dir=\"rtl\">ש׳ וכ׳</span>).—[<span class=\"citation\">Koh. R. to I, 2</span>, v. <a href=\"#\" data-headword=\"בִּיב\">בִּיב</a>.]</div>","alt":[]},"12343":{"h":"כִּיבָּא","r":"K00481","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"*כְּבַב\">כְּבַב</a>) <i>roast over thorn-fire</i>. <span class=\"citation\">Snh. 70ᵃ</span> <span dir=\"rtl\">כבשר כ׳ וכ׳</span> (Ar. <a href=\"#\" data-headword=\"כָּבַל\">כִּיבֵּי</a> <i>pl.</i>) like the meat roasted over a thorn-fire which thieves eat.</div>","alt":[]},"12344":{"h":"כִּיבּוּד","r":"K00482","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּבֵד I\">כָּבֵד</a>) </div><div class=\"sense\"><b>1)</b> <i>doing honor to; respect, reverence</i>. <span class=\"citation\">Peah I, 1</span> <span dir=\"rtl\">כ׳ אב ואם</span> filial respect. Sifra K’dosh. beg.; <span class=\"citation\">Kidd. 31ᵇ</span>, a. e. (ref. to <span class=\"citation\">Lev. XIX, 3</span>, a. <span class=\"citation\">Ex. XX, 12</span>) <span dir=\"rtl\">איזהו מורא ואיזהו כ׳</span> what constitutes filial fear (reverence), and what filial respect?—<span class=\"citation\">Pesik. R. s. 23—24</span>; <span class=\"citation\">Y. Kidd. I, 61ᵇ</span> top <span dir=\"rtl\">אדיין לחצי הכ׳ וכ׳</span> he has not come up yet to half of the filial duties which the Law implies; a. fr.—2) <i>sweeping, cleansing</i>. <span class=\"citation\">Nidd. VII, 2</span> (<span class=\"citation\">56ᵃ</span>) <span dir=\"rtl\">עד שעת כִּבּוּד</span> up to the time of sweeping; <span class=\"citation\">Nidd. 3ᵃ</span> <span dir=\"rtl\">עד שעת הכי׳</span>. <span class=\"citation\">Treat. S’maḥ. ch. XI</span>; a. e.—Pl. <span dir=\"rtl\">כִּיבּוּדִים</span>, <span dir=\"rtl\">כִּבּ׳</span>. <span class=\"citation\">Nidd. 56ᵇ</span> <span dir=\"rtl\">בשעת כִּבּוּדֵיהֶם</span> when they are being swept.</div>","alt":[]},"12345":{"h":"כִּיבּוּי","r":"K00483","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּבָה\">כָּבָה</a>) <i>extinguishing</i>. <span class=\"citation\">Sabb. 120ᵇ</span> <span dir=\"rtl\">גרם כ׳</span> causing extinction indirectly. Y. ib. XVII, end, 15ᵈ [read:] <span dir=\"rtl\">יש לו צורך בכ׳</span> he has use for (profits by) the extinction.</div>","alt":[]},"12346":{"h":"כיבוי","r":"K00484","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Prov. XXX, 14</span>, some ed., read: <span dir=\"rtl\">נִיבוֹי</span>, v. <a href=\"#\" data-headword=\"נִיבָא I\">נִיבָא</a>.</div>","alt":[]},"12347":{"h":"כִּיבּוּס","r":"K00485","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּבַס\">כָּבַס</a>) <i>washing</i>. <span class=\"citation\">Zeb. XI, 3</span>. <span class=\"citation\">Ib. 94ᵇ</span>, v. <a href=\"#\" data-headword=\"כִּסְכּוּס\">כִּסְכּוּס</a>; a. fr.—Pl. <span dir=\"rtl\">כִּיבּוּסִים</span>, <span dir=\"rtl\">כִּבּ׳</span>. <span class=\"citation\">Nidd. 56ᵇ</span> <span dir=\"rtl\">בשעת כִּבּוּסֵיהֶן</span> when they are being washed.</div>","alt":["כִּבּוּס"]},"12348":{"h":"כִּיבּוּשׁ","r":"K00486","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּבַשׁ\">כָּבַשׁ</a>) </div><div class=\"sense\"><b>1)</b> <i>conquest, dominion</i>. <span class=\"citation\">Y. Hor. III, 48ᶜ</span> top <span dir=\"rtl\">בכ׳ הארץ</span> for the conquest of Palestine. <span class=\"citation\">Gitt. 8ᵇ</span> (ref. to Syria) <span dir=\"rtl\">כ׳ יחיד … כ׳</span> the conquest of an individual (David) is not called a (national) conquest (so as to give the land the sacred character of Palestine); <span class=\"citation\">ib. 47ᵃ</span>, a. fr.—[<span class=\"citation\">Gen. R. s. 17</span> <span dir=\"rtl\">לכבוש</span>, v. <a href=\"#\" data-headword=\"כִּינּוּס\">כִּינּוּס</a>.]</div><div class=\"sense\"><b>—2)</b>  = <a href=\"#\" data-headword=\"כֶּבֶשׁ\">כֶּבֶשׁ</a> 2, <i>ascent, grade</i>. Y. Erub. II, 24ᵇ bot. [read:] <span dir=\"rtl\">כל כִּיבּוּשֵׁי כבשים … מכִּי בּוּשׁוֹ וכ׳</span> all grades of ascents in the Temple …, with the exception of the grade of the altar-bridge which was at the rate of about ten handbreadths to three handbreadths and one third of a finger’s width (of vertical height; i.e. 10 to 3 <sup>1</sup>/<sub>12</sub>), v. <a href=\"#\" data-headword=\"כֶּבֶשׁ\">כֶּבֶשׁ</a>.—Pl. <span dir=\"rtl\">כִּיבּוּשִׁים</span>, <span dir=\"rtl\">כִּיבּוּשִׁין</span>, constr. <a href=\"#\" data-headword=\"כִּיבּוּשׁ\">כִּיבּוּשֵׁי</a>, v. supra.</div><div class=\"sense\"><b>—3)</b>  (only in <i>pl.</i>) <i>means of subduing one’s pride; reproof; evil prediction, penitence</i>. Pesik. V’zoth, p. 197ᵃ <span dir=\"rtl\">הן וכִיבּוּשֵׁיהֶן</span> they (the blessings) but also the reproofs connected therewith (<span class=\"citation\">Deut. ch. XXXII</span>); <span class=\"citation\">Yalk. Deut. 550</span>. <span class=\"citation\">Gen. R. s. 66</span> (ref. to <span class=\"citation\">Gen. XXVII, 28</span>) [read:] <span dir=\"rtl\">יתן לך ברכות ויתן לך כיבושיהן</span>; <span class=\"citation\">Yalk. Gen. 115</span> <span dir=\"rtl\">כיבושין הראויות לך</span> may He give thee blessings, but also such means of preventing overbearing as may be proper for thee.—דברי כ׳ <i>admonitions to penitence</i>. <span class=\"citation\">Taan. II, 1</span> (<span class=\"citation\">15ᵃ</span>); Tosef. ib. I, 8.</div>","alt":[]},"12349":{"h":"כִּיבּוּשׁ ²","r":"K00487","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(v. <a href=\"#\" data-headword=\"כְּבַשׁ\">כְּבַשׁ</a> 3) <i>fastening, connection, hammering in, welding</i>. <span class=\"citation\">Targ. I Kings VII, 29</span> <span dir=\"rtl\">עובד כ׳</span> welding work (h. text <a href=\"#\" data-headword=\"מוֹרָד I\">מורד</a>). <span class=\"citation\">Ib. 30</span> <span dir=\"rtl\">ככְבַשׁ</span> constr. (h. text <a href=\"#\" data-headword=\"מַעְבָּר\">מֵעֵבֶר</a>!). <span class=\"citation\">Ib. 36</span> <span dir=\"rtl\">(<a href=\"#\" data-headword=\"כֵּהֶה\">כֵּי׳</a>) <span dir=\"rtl\">כֵּבַשׁ חד</span></span> one connected body (h. text <span dir=\"rtl\">כמער איש</span>).—Pl. <span dir=\"rtl\">כִּיבּוּשִׁין</span>. <span class=\"citation\">Targ. Ex. XXVII, 10</span>, a. e. <i>sockets</i> for the hooks (h. text <span dir=\"rtl\">חֲשֻׁק־</span>). <span class=\"citation\">Targ. I Kings VII, 33</span> <i>naves</i> (h. text <span dir=\"rtl\">חִשֻּׁר־</span>).</div>","alt":["כֵּבַשׁ","כֵּיבַשׁ"]},"12350":{"h":"כֵּיבַשׁ","r":"K00488","html":"<div class=\"sense\"><b>,</b> v. <a href=\"#\" data-headword=\"כֵּבַשׁ II\"><span dir=\"rtl\">כְּבַשׁ</span> II</a> a. <a href=\"#\" data-headword=\"כִּיבּוּשׁ ²\">preced.</a></div>","alt":["כִּיבְשָׁא"]},"12351":{"h":"כִּיד","r":"K00489","html":"<div class=\"sense\">, <i>Pi.</i> <a href=\"#\" data-headword=\"כִּיֵּיד\">כִּיֵּיד</a>, v. <a href=\"#\" data-headword=\"כִּיר\">כִּיר</a>.</div>","alt":[]},"12352":{"h":"כִּיד ²","r":"K00490","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּד I\"><span dir=\"rtl\">כַּד</span> I</a></div>","alt":["כִּיד־"]},"12353":{"h":"כִּידְבָא","r":"K00491","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּדְבָא\">כַּדְבָא</a></div>","alt":[]},"12354":{"h":"כִּידוּ","r":"K00492","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּדוּ\">כְּדוּ</a></div>","alt":[]},"12355":{"h":"כידום","r":"K00493","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כידוס\">כידוס</a></div>","alt":[]},"12356":{"h":"כִּידוֹן I","r":"K00494","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) name of <i>a tree</i>, trnsf. <i>light spear, javelin.</i> <span class=\"citation\">Kel. XI, 8</span>. <span class=\"citation\">Num. R. s. 9</span> <span dir=\"rtl\">יכול ככ׳</span> you might think (Absalom with his head of hair was slender, looking) like a <i>kidon</i>, opp. <span dir=\"rtl\">כחרובית</span>; <span class=\"citation\">Y. Sot. I, 17ᵇ</span> <span dir=\"rtl\">בכ׳</span> (corr. acc.); Midr. Sam. ch. XIII; ib. XXVII; a. e.—Pl. <span dir=\"rtl\">כִּידוֹנִים</span>. <span class=\"citation\">Yalk. Gen. 133</span>.</div>","alt":[]},"12357":{"h":"כִּידוֹן II","r":"K00495","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Kidon</i>; <span dir=\"rtl\">גורן כ׳</span> the threshing floor of K. (<span class=\"citation\">I Chr. XIII, 9</span>), in place of <a href=\"#\" data-headword=\"נָכוֹן\">נָכוֹן</a> (<span class=\"citation\">II Sam. VI, 6</span>). <span class=\"citation\">Sot. 35ᵇ</span>; <span class=\"citation\">Num. R. s. 4</span> <span dir=\"rtl\">בתחלה כ׳ וכ׳</span> at first (the Ark was shaking like) a javelin (v. <a href=\"#\" data-headword=\"כִּידוֹן I\">preced.</a>), but afterwards (it was) firmly established; [oth. interpret., v. Rashi to Sot. l. c.]</div>","alt":[]},"12358":{"h":"כידוס","r":"K00496","html":"<div class=\"sense\">, Tosef. Meg. IV (III), 30, read: <a href=\"#\" data-headword=\"בִּירוֹס\">בִּירוֹס</a>.</div>","alt":["כידום"]},"12359":{"h":"כִּידוֹר","r":"K00497","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Kidor</i>. <span class=\"citation\">Yoma 83ᵇ</span> (as an ominous name, with ref. to <span dir=\"rtl\">כי דור</span>, <span class=\"citation\">Deut. XXXII, 20</span>); Y. R. Hash. III, end, 59ᵃ</div>","alt":[]},"12360":{"h":"כידי","r":"K00498","html":"<div class=\"sense\">, Pesik. Shub., p. 162ᵃ <span dir=\"rtl\">כ׳ ומנקייה</span>, v. <a href=\"#\" data-headword=\"כִּירוֹמָנִיקְיָא\">כִּירוֹמָנִיקְיָא</a></div>","alt":[]},"12361":{"h":"כידים","r":"K00499","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*כִּירִים\">כִּירִים</a></div>","alt":["כידין"]},"12362":{"h":"כִּיהוּן","r":"K00500","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"כֹּהֵן\">כֹּהֵן</a>) <i>priestly outfit</i>. <span class=\"citation\">Yoma 43ᵃ</span> הכהן בכִיהוּנוֹ ‘the priest’ (as such) in his priestly garments (v. Rabb. D. S. a. l. note 7); <span class=\"citation\">Yalk. Num. 760</span>.</div>","alt":[]},"12363":{"h":"כִּיּוּד","r":"K00501","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּיּוּר\">כִּיּוּר</a></div>","alt":[]},"12364":{"h":"כִּיוּוּן","r":"K00502","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּוּוּן\">כִּוּוּן</a>, a. <a href=\"#\" data-headword=\"כִּיּוּן\">כִּיּוּן</a></div>","alt":[]},"12365":{"h":"כֵּיוָון","r":"K00503","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֵּיוָן\">כֵּיוָן</a>, <span dir=\"rtl\">כֵּיונ׳</span>.</div>","alt":["כֵּיוָונִיתָא","כֵּיוַונְתָּא"]},"12366":{"h":"כִּיּוּן","r":"K00504","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>Kiyyun</i>, name of an idol. <span class=\"citation\">Targ. Am. V, 26</span> (some ed. <a href=\"#\" data-headword=\"כִּיוּוּן\">כִּיוּוּן</a>).</div>","alt":[]},"12367":{"h":"כִּיוָּן","r":"K00505","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כּוּן\">כּוּן</a>) [<i>firmness, directness, fitness</i>;] </div><div class=\"sense\"><b>1)</b>  (adv.) <i>directly, exactly</i>. <span class=\"citation\">Pes. 37ᵃ</span> <span dir=\"rtl\">אפשר … ויקבענה כ׳</span> he may form the dough in a mould and attach it to the cake directly (well fitting, without loss of time). <span class=\"citation\">Tam. III, 6</span> <span dir=\"rtl\">אחד … ואחד פותח כ׳</span> (with one key) a priest puts his hand through an opening in the door (v. <a href=\"#\" data-headword=\"אַמָּה\">אַמָּה</a>), and another priest opens (with the other key) directly; (Talm. ed. 30ᵇ <span dir=\"rtl\">ואחד שהוא פותח כ׳</span> and another key which opens directly).</div><div class=\"sense\"><b>—2)</b>  (conj. followed by <span dir=\"rtl\">ש־</span>) <i>as soon as, since</i>. <span class=\"citation\">Macc. 3ᵃ</span>, a. fr. <span dir=\"rtl\">כ׳ שהגיד וכ׳</span> as soon as a witness has finished his evidence, he is not permitted to testify again (retract or modify). <span class=\"citation\">Keth. 11ᵃ</span> <span dir=\"rtl\">כ׳ שהגדילה וכ׳</span> as soon as she was of age for one while without protesting &amp;c. <span class=\"citation\">Erub. 93ᵇ</span> <span dir=\"rtl\">כ׳ שהותרה הותרה</span> being once permitted (for one part of the Sabbath), it remains permitted; a. v. fr.</div>","alt":[]},"12368":{"h":"כֵּיוָן","r":"K00506","html":"<div class=\"sense\"><b>1)</b> <i>firmly established, true, straightforward</i>. <span class=\"citation\">Targ. Deut. XIII, 15</span> (h. text <a href=\"#\" data-headword=\"נָכוֹן\">נָכוֹן</a>). Targ. <span class=\"citation\">Hab. I, 4</span> <span dir=\"rtl\">לא כ׳</span> (h. text <span dir=\"rtl\">מעוקל</span>).—Pl. <span dir=\"rtl\">כֵּיוָנֵי</span> <i>honest men</i>. <span class=\"citation\">Targ. O. Gen. XLII, 11</span>; <span class=\"citation\">19</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  (conj. followed by <span dir=\"rtl\">ד־</span>) <i>as soon as, when, since</i>(also <a href=\"#\" data-headword=\"כִּיוָּן\">כִּיוָּן</a>). <span class=\"citation\">Targ. Y. Gen. XXI, 15</span>. <span class=\"citation\">Targ. Y. II, Gen. XXVIII, 10</span>; a. fr.—<span class=\"citation\">Ber. 8ᵃ</span> <span dir=\"rtl\">כ׳ דאמרי ליה</span> when they told him. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כ׳ דשמענא להא וכ׳</span> when we heard that which &amp;c.; a. v. fr.</div>","alt":["כֵּיוָון"]},"12369":{"h":"כֵּיוָנָא I","r":"K00507","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"כֵּיוָן\">preced.</a>) <i>straight, proper</i>. <span class=\"citation\">Targ. II Sam. XXII, 31</span> (ed. Lag. <a href=\"#\" data-headword=\"כֵּוָונָא\">כֵּוָונָא</a>).—Pl. f. <span dir=\"rtl\">כֵּיוָנָן</span>. <span class=\"citation\">Targ. Ps. XVIII, 31</span> (ed. Lag. <span dir=\"rtl\">כֵּוָו׳</span>); a. e.</div>","alt":[]},"12370":{"h":"כֵּיוָנָא II","r":"K00508","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כֵּיוָנָא I\">preced.</a>) <i>propriety, proper thing</i>(h. . <span class=\"citation\">Targ. Job XLII, 7</span> (ed. Wil. <a href=\"#\" data-headword=\"כְּוָא\">כְּוַ׳</a>); <span class=\"citation\">ib. 8</span> (ed. Lag. <a href=\"#\" data-headword=\"כֵּיוָון\">כֵּיוָו׳</a>). <span class=\"citation\">Targ. Mic. III, 9</span> (ed. Lag. <a href=\"#\" data-headword=\"כֵּיוָון\">כֵּיוָונִיתָא</a>). <span class=\"citation\">Targ. Am. V, 10</span> (ed. Lag. <span dir=\"rtl\">בֵּוָונִיתָא</span>; h. text <span dir=\"rtl\">תמים</span>).—Pl. <span dir=\"rtl\">כֵּיוָנָן</span>. <span class=\"citation\">Targ. Is. XXXIII, 15</span>; <span class=\"citation\">XLV, 19</span> (h. text <span dir=\"rtl\">מישרים</span>).—[<span class=\"citation\">Targ. Ps. XXXII, 9</span> <a href=\"#\" data-headword=\"כֵּיוָנָא I\">כיונא</a>, some ed., read: <a href=\"#\" data-headword=\"בִּיּוּנָא\">בִּיּוּנָא</a>.]</div>","alt":["כֵּיוַנְתָּא"]},"12371":{"h":"כיונותא","r":"K00509","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Ps. CIII, 2</span>, in an interpolation, read: <a href=\"#\" data-headword=\"בִּיּוּנָא\">בִּיּוּנְתָּא</a>.</div>","alt":[]},"12372":{"h":"כֵּיוָנִיתָא","r":"K00510","html":"<div class=\"sense\"><b>,</b> v. <a href=\"#\" data-headword=\"כֵּיוָנָא II\"><span dir=\"rtl\">כֵּיוָנָא</span> II</a></div>","alt":["כֵּיוַנְתָּא"]},"12373":{"h":"כִּיּוּר","r":"K00511","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כִּיר\">כִּיר</a>, <a href=\"#\" data-headword=\"כִּיד\">כִּיד</a>) <i>paneling work, panel</i> (abacus). <span class=\"citation\">B. Bath. 53ᵇ</span> <span dir=\"rtl\">וסד בהן סיוד אחד או כ׳ אחד</span> and added one piece of stucco or one panel. <span class=\"citation\">Midd. IV, 6</span> <span dir=\"rtl\">אמה כ׳</span> one cubit for the paneling work (tablature of the ceiling in the Temple). <span class=\"citation\">Zeb. 62ᵃ</span>, v. <a href=\"#\" data-headword=\"כַּרְכּוֹב\">כַּרְכּוֹב</a>.</div>","alt":["(כִּיּוּד)"]},"12374":{"h":"כִּיּוֹר","r":"K00512","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>basin</i>, esp. the <i>laver</i> for the priests in the Temple court. <span class=\"citation\">Midd. III, 6</span>. <span class=\"citation\">Tosef. Yoma II, 2</span>; a. e.</div>","alt":[]},"12375":{"h":"כִּיוֹרָא","r":"K00513","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Ex. XXX, 18</span>; a. fr.—Pl. <span dir=\"rtl\">כִּיוֹרִין</span>, <a href=\"#\" data-headword=\"כִּירַיָּא\">כִּיוֹרַיָּא</a>. <span class=\"citation\">Targ. II Chr. IV, 6</span>. <span class=\"citation\">Targ. I Kings VII, 40</span>; a. e.</div>","alt":["(כִּיוּרָא)"]},"12376":{"h":"כִּיוּרָא","r":"K00514","html":"<div class=\"sense\"><i>panel-work</i>. <span class=\"citation\">Targ. II Chr. VI, 13</span> (h. text <a href=\"#\" data-headword=\"כִּיּוֹר\">כִּיוֹר</a>).—Pl. constr. <span dir=\"rtl\">כִּיוֹרֵי</span>; <span dir=\"rtl\">כ׳ ארזיא</span> <i>cedar panels</i> in ceilings. <span class=\"citation\">Targ. II Sam. VII, 2</span>; <span class=\"citation\">7</span>; <span class=\"citation\">Targ. I Chr. XVII, 1</span> (ed. Rahm. <span dir=\"rtl\">כייורי</span>).—<span class=\"citation\">Targ. Jer. XXII, 14</span>. Targ. <span class=\"citation\">Ḥag. I, 4</span> (ed. Wil. <span dir=\"rtl\">נִסְרֵי</span>).</div>","alt":["(כִּיוֹרָא)"]},"12377":{"h":"*כִּיזְבָּא","r":"K00515","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (supposed to be) <i>a measure of length</i>, v. <a href=\"#\" data-headword=\"נִזְבָּא\">נִזְבָּא</a>.</div>","alt":[]},"12378":{"h":"כֵּיזֶה","r":"K00516","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כֵּי\">כֵּי</a>, a. <a href=\"#\" data-headword=\"כֵּיצַד\">כֵּיצַד</a>.</div>","alt":["כֵּיזְצַד"]},"12379":{"h":"כִּיחַ","r":"K00517","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כָּחַח\">כָּחַח</a>) <i>coughing, phlegm</i> of the lungs. <span class=\"citation\">Erub. 99ᵃ</span> <span dir=\"rtl\">בכִיחוֹ</span> it refers to the phlegm in his mouth. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כיחו שנתלש</span> phlegm which is loose in the mouth. [<span class=\"citation\">Ib.</span> <span dir=\"rtl\">כיח ורק</span>, <span dir=\"rtl\">כ׳ בפני</span>, v. <a href=\"#\" data-headword=\"כָּחַח\">כָּחַח</a>.]—<span class=\"citation\">B. Kam. 3ᵇ</span> <span dir=\"rtl\">כיחו וניעו</span> the phlegm brought out by coughing or hawking. <span class=\"citation\">Nidd. 55ᵇ</span>. <span class=\"citation\">Ib. 56ᵃ</span> <span dir=\"rtl\">כיחו וניעו ורוקי</span> phlegm, mucus and spittle (prob. to be read <span dir=\"rtl\">כרוקו</span>). <span class=\"citation\">Kidd. 81ᵇ</span> (in Chald. dict.) <span dir=\"rtl\">כיחו</span>, v. <a href=\"#\" data-headword=\"*אִכְמַר\">אִכְמַר</a>.</div>","alt":[]},"12380":{"h":"כַּיי","r":"K00518","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הַיי\">היי</a></div>","alt":[]},"12381":{"h":"כִּיֵּיד","r":"K00519","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּיר\">כִּיר</a></div>","alt":[]},"12382":{"h":"כִּייוּרָא","r":"K00520","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּיוּרָא\">כִּיוּרָא</a></div>","alt":[]},"12383":{"h":"כָּיִיל","r":"K00521","html":"<div class=\"sense\"><b>,</b> v. <a href=\"#\" data-headword=\"כּוּל\">כּוּל</a></div>","alt":["כַּיִּיל"]},"12384":{"h":"כַּיָּיל","r":"K00522","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כּוּל\">כּוּל</a>) <i>measurer</i>, a rural officer. Y. B. Mets. IX, beg. 12ᵃ.—Pl. <span dir=\"rtl\">כַּיָּילִין</span>. <span class=\"citation\">Tosef. ib. IX, 14</span> <span dir=\"rtl\">הביי׳</span> (corr. acc.).</div>","alt":[]},"12385":{"h":"כַּיְילָא","r":"K00523","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כַּיָּיל\">preced.</a>) <i>measure</i>. <span class=\"citation\">B. Mets. 40ᵃ</span> (Ms. H. <span dir=\"rtl\">בכילתא</span>, v. Rabb. D. S. a. l. note 6). <span class=\"citation\">Bets. 38ᵇ</span> כיי׳ חסריה Ms. M. (ed. <a href=\"#\" data-headword=\"כִּנָּרָא\">כי׳</a>) he lessened the measure (quantity) of his wheat by taking out the pebbles. <span class=\"citation\">Ib. 29ᵃ</span> <span dir=\"rtl\">מנא דכ׳</span> a vessel used for measuring.</div>","alt":["כַּיְלָא"]},"12386":{"h":"כַּיְיפָא","r":"K00524","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כּוּף\">כּוּף</a>) <i>pressure, necessity</i>. <span class=\"citation\">Targ. Prov. XVI, 26</span> ed. Lag. (oth. <a href=\"#\" data-headword=\"כִּיפְתָא\">כֵּיפָא</a>).</div>","alt":[]},"12387":{"h":"כִּיֵּיר","r":"K00525","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּיר\">כִּיר</a></div>","alt":[]},"12388":{"h":"כייר","r":"K00526","html":"<div class=\"sense\">, Y. B. Mets. IX, beg., 12ᵃ, v. <a href=\"#\" data-headword=\"בַּיָּיר\">בַּיָּיר</a></div>","alt":[]},"12389":{"h":"*כִּיכְלֵי","r":"K00527","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (= <span dir=\"rtl\">כלכלי</span>, Assyr. Kulukuku, Kaku-ullu, v. Del. Assyr. Thiernamen, p. 103) <i>partridges</i>. <span class=\"citation\">Yoma 75ᵇ</span> ד׳ מיני שליו … וכ׳ Ar. (ed. <a href=\"#\" data-headword=\"קִיבְלַי\">קיבלי</a>; Ms. M. 1 <a href=\"#\" data-headword=\"קִיפְלַי\">קיפלי</a>, 2 <a href=\"#\" data-headword=\"קיכלי\">קיכלי</a>, v. Rabb. D. S. a. l. note) there are four kinds of <i>s’lav</i> &amp;c. (v. Winer Realwörterbuch s. v. Wachtel); <span class=\"citation\">Yalk. Ex. 260</span> <a href=\"#\" data-headword=\"קִיבְלַי\">קיבלי</a>. [Mus.: κίχλη, <i>thrush</i>.]</div>","alt":[]},"12390":{"h":"כַּיְלָא","r":"K00528","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כַּיְילָא\">כַּיְילָא</a></div>","alt":[]},"12391":{"h":"כִּילָאוֹת","r":"K00529","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּילָה\">כִּילָה</a></div>","alt":[]},"12392":{"h":"כִּילְבִּית","r":"K00530","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כִּילְכִּית\">כִּילְכִּית</a></div>","alt":["כִּלְ׳"]},"12393":{"h":"כילדין","r":"K00531","html":"<div class=\"sense\">, <span class=\"citation\">Y. Pes. III, beg. 29ᵈ</span> <span dir=\"rtl\">והוא עביד כ׳</span> (?)—prob. a corrupt. to be restored after Bab. <span class=\"citation\">Pes. 42ᵇ</span> <span dir=\"rtl\">שואבת הזוהמא</span>.</div>","alt":[]},"12394":{"h":"כִּילָה","r":"K00532","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"כּוּל\">כּוּל</a> or <a href=\"#\" data-headword=\"כָּלַל\">כָּלַל</a>) [<i>enclosure</i>,] <i>curtain, curtained bed, canopy</i>. <span class=\"citation\">Gen. R. s. 36</span>, beg. <span dir=\"rtl\">כדיין שמותחין כ׳ על פניו</span> like a judge before whom they spread the curtain (that he may be undisturbed; <span class=\"citation\">Lev. R. s. 5</span> <span dir=\"rtl\">את הוילון</span>). <span class=\"citation\">Y. Sabb. XX, beg. 17ᶜ</span> (in Chald. dict.) <span dir=\"rtl\">ההן כ׳ דעל וכ׳</span> that curtain before the ark. <span class=\"citation\">Succ. 10ᵇ</span> <span dir=\"rtl\">מותר לישן בכ׳ וכ׳</span> it is permitted to sleep in the Succah in a tester-bed though it has a top cover. Ib. 11ᵃ <span dir=\"rtl\">כִּילַת חתנים</span> a bridal bed (without cover overhead). <span class=\"citation\">Num. R. s. 12</span> (ref. to <span class=\"citation\">Cant. III, 9</span>, v. <a href=\"#\" data-headword=\"אַפִּרְיוֹן\">אַפִּרְיוֹן</a>) ‘the king … made for himself a bridal litter’, that is the world <span dir=\"rtl\">שהוא עשוי כמין כ׳</span> which is formed like a canopy (v. <span class=\"citation\">Ps. CIV, 2</span>, sq.). Ib. s. 13; a. fr.—Pl. <a href=\"#\" data-headword=\"כִּילָאוֹת\">כִּילָיוֹת</a>, <a href=\"#\" data-headword=\"כִּילָאוֹת\">כִּילָאוֹת</a> (fr. <a href=\"#\" data-headword=\"כִּילִי\">כִּילַי</a> or <a href=\"#\" data-headword=\"כִּילָה\">כִּילָא</a>). <span class=\"citation\">Gen. R. s. 28</span> (<span class=\"citation\">Yalk. ib. 47</span> <a href=\"#\" data-headword=\"וִילָאוֹת\">וִילָאוֹת</a>, some ed. <span dir=\"rtl\">פלאות</span>, read: <a href=\"#\" data-headword=\"כִּלְכּוּל\">כִּילָ׳</a>).</div>","alt":[]},"12395":{"h":"כילה","r":"K00533","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Esth. 1056</span>, v. <a href=\"#\" data-headword=\"קִיל I\">קִילָא</a></div>","alt":[]},"12396":{"h":"כִּילּוּ","r":"K00534","html":"<div class=\"sense\"> = <span dir=\"rtl\">כְּאִילּוּ</span>, v. <a href=\"#\" data-headword=\"אִילּוּ\">אִילּוּ</a></div>","alt":[]},"12397":{"h":"כַּיְלוּ","r":"K00535","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Ps. LIX, 14</span> Ms., v. <a href=\"#\" data-headword=\"כָּלוּ\">כָּלוּ</a></div>","alt":[]},"12398":{"h":"כִּילָוַות","r":"K00536","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*כִּילְתָא II\"><span dir=\"rtl\">כִּילְתָא</span> II</a></div>","alt":[]},"12399":{"h":"כִּילוֹזָא","r":"K00537","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּלוֹזָא\">כְּלוֹזָא</a></div>","alt":[]}};
